INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39071, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "糸や布の原料となる、細くて長い物質のことです。植物や動物、石油などから作られます。", "primary_collocate": null, "pronunciation": "せんい", "ipa": "seɴi", "syllable_count": 3, "sentences": [{"text": "古来、人類は植物の生命力を繊維に宿す術を磨き上げてきた。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "綿は植物からとれる繊維だ。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "わた しょくぶつ せんい", "sentence_source": "generated"}, {"text": "この服は丈夫な繊維でできている。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "ふく じょうぶ せんい", "sentence_source": "generated"}, {"text": "羊の毛も繊維の一つです。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "ひつじ け せんい ひと", "sentence_source": "generated"}, {"text": "繊維を集めて糸を作る。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "せんい あつ いと つく", "sentence_source": "generated"}, {"text": "麻の繊維はとても強い。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "あさ せんい つよ", "sentence_source": "generated"}, {"text": "石油から新しい繊維が作られた。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "せきゆ あたら せんい つく", "sentence_source": "generated"}, {"text": "布の繊維がほつれている。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "ぬの せんい", "sentence_source": "generated"}, {"text": "祖父は繊維の工場で働いた。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "そふ せんい こうじょう はたら", "sentence_source": "generated"}, {"text": "細い繊維を顕微鏡で見た。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "ほそ せんい けんびきょう み", "sentence_source": "generated"}], "morphological_forms": [{"form": "化学繊維", "label": "派生"}, {"form": "食物繊維", "label": "派生"}, {"form": "本", "label": "助数詞"}], "register": "formal", "sense_fingerprint": "名詞 | 糸や布になる細長い物質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted f