INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35199, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間という生き物の全体。", "primary_collocate": null, "pronunciation": "じんるい", "ipa": "dʑiɴɾɯi", "syllable_count": 4, "sentences": [{"text": "古来、人類は植物の生命力を繊維に宿す術を磨き上げてきた。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "mined"}, {"text": "人類は火を使うようになった。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}, {"text": "人類の歴史はとても長い。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}, {"text": "月に行くのは人類の夢だった。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}, {"text": "戦争は人類の大きな問題だ。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}, {"text": "人類は地球を守るべきだ。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}, {"text": "この発見は人類を救うかもしれない。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}, {"text": "人類が生まれたのはアフリカだ。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}, {"text": "全人類が平和を願っている。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}, {"text": "人類の未来を考えている。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}], "morphological_forms": [{"form": "人類学", "label": "派生"}, {"form": "人類史", "label": "派生"}, {"form": "全人類", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 生物の種としての人間全体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47a7e27-7029-4783-8c7c-afd23037a542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38309, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "事業をするためのもとになるお金や設備。", "primary_collocate": null, "pronunciation": "しほん", "ipa": "ɕihoɴ", "syllable_count": 3, "sentences": [{"text": "これは事業の終了ではなく、資本の循環と新たな創造への移行を意味する重要なプロセスだ。", "target_word": "資本", "complexity_tier": "T3", "furigana": "しほん", "sentence_source": "mined"}, {"text": "特に、初期段階のスタートアップ資金調達を担う彼らの役割は、単なる資本の提供にとどまらない。", "target_word": "資本", "complexity_tier": "T3", "furigana": "しほん", "sentence_source": "mined"}, {"text": "会社を作るには資本が必要だ。", "target_word": "資本", "complexity_tier": "T3", "furigana": "しほん", "sentence_source": "generated"}, {"text": "彼は少ない資本で店を始めた。", "target_word": "資本", "complexity_tier": "T3", "furigana": "しほん", "sentence_source": "generated"}, {"text": "外国の資本が入ってきた。", "target_word": "資本", "complexity_tier": "T3", "furigana": "しほん", "sentence_source": "generated"}, {"text": "資本が足りなくて困っている。", "target_word": "資本", "complexity_tier": "T3", "furigana": "しほん", "sentence_source": "generated"}, {"text": "この会社は資本が大きい。", "target_word": "資本", "complexity_tier": "T3", "furigana": "しほん", "sentence_source": "generated"}, {"text": "資本を集めて工場を建てた。", "target_word": "資本", "complexity_tier": "T3", "furigana": "しほん", "sentence_source": "generated"}, {"text": "銀行から資本を借りている。", "target_word": "資本", "complexity_tier": "T3", "furigana": "しほん", "sentence_source": "generated"}, {"text": "新しい事業には資本が要る。", "target_word": "資本", "complexity_tier": "T3", "furigana": "しほん", "sentence_source": "generated"}], "morphological_forms": [{"form": "資本金", "label": "派生"}, {"form": "資本家", "label": "派生"}, {"form": "資本主義", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 事業の元手となる資金や資産", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47a7e27-7029-4783-8c7c-afd23037a542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39127, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天然", "is_correct": true, "explanation": "正解。「天然」（てんねん）。"}, {"text": "点検", "is_correct": false, "explanation": "「点検」はてんけんと読み、「ね」が「け」に変わる一モーラ差。"}, {"text": "点線", "is_correct": false, "explanation": "「点線」はてんせんと読み、「ね」が「せ」に変わる一モーラ差。"}, {"text": "転勤", "is_correct": false, "explanation": "「転勤」はてんきんと読み、「ね」が「き」に変わる一モーラ差。"}, {"text": "千年", "is_correct": false, "explanation": "「千年」はせんねんと読み、「て」が「せ」に変わる一モーラ差。"}], "explanations": {"天然": "正解。「天然」（てんねん）。", "点検": "「点検」はてんけんと読み、「ね」が「け」に変わる一モーラ差。", "点線": "「点線」はてんせんと読み、「ね」が「せ」に変わる一モーラ差。", "転勤": "「転勤」はてんきんと読み、「ね」が「き」に変わる一モーラ差。", "千年": "「千年」はせんねんと読み、「て」が「せ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "天然"}, "level_3": {"options": [{"text": "天然", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "人工", "is_correct": false, "explanation": "意味：人の手で作ったもので、自然のままの染料という文意と逆になる。"}, {"text": "合成", "is_correct": false, "explanation": "意味：化学的に作ったもので、文の対比と合わない。"}, {"text": "大量", "is_correct": false, "explanation": "連語：「大量染料」とは言わず、量を表す語は文脈に合わない。"}], "explanations": {"天然": "文脈に合う正しい語。", "人工": "意味：人の手で作ったもので、自然のままの染料という文意と逆になる。", "合成": "意味：化学的に作ったもので、文の対比と合わない。", "大量": "連語：「大量染料」とは言わず、量を表す語は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "天然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天然の魚を三冊買いました。", "explanation": "助数詞の誤り：魚は「匹」「尾」で数える。"}, {"text": "天然を魚は少し高いです。", "explanation": "助詞の混同：「天然の魚」とすべきところを「を」にしている。"}, {"text": "昨日天然の魚は少し高いでした。", "explanation": "活用の誤り：「高いでした」は誤りで「高かったです」が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04e1d9ab-3efb-4f6d-8f3f-b4ce787f2fa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_va