INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39127, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "天然", "is_correct": true, "explanation": "正解。「天然」（てんねん）。"}, {"text": "年々", "is_correct": false, "explanation": "「年々」はねんねんと読み、「て」が「ね」に変わる一モーラ差。"}, {"text": "点眼", "is_correct": false, "explanation": "「点眼」はてんがんと読み、「ね」が「が」に変わる一モーラ差。"}, {"text": "点線", "is_correct": false, "explanation": "「点線」はてんせんと読み、「ね」が「せ」に変わる一モーラ差。"}, {"text": "転勤", "is_correct": false, "explanation": "「転勤」はてんきんと読み、「ね」が「き」に変わる一モーラ差。"}], "explanations": {"天然": "正解。「天然」（てんねん）。", "年々": "「年々」はねんねんと読み、「て」が「ね」に変わる一モーラ差。", "点眼": "「点眼」はてんがんと読み、「ね」が「が」に変わる一モーラ差。", "点線": "「点線」はてんせんと読み、「ね」が「せ」に変わる一モーラ差。", "転勤": "「転勤」はてんきんと読み、「ね」が「き」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "天然"}, "level_3": {"options": [{"text": "天然", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "電気", "is_correct": false, "explanation": "意味：「電気ガス」という語はなく、料理に使うガスの種類として合わない。"}, {"text": "毒", "is_correct": false, "explanation": "意味：毒ガスで料理はしない。"}, {"text": "時間", "is_correct": false, "explanation": "意味：「時間ガス」という語はなく、文が成立しない。"}], "explanations": {"天然": "文脈に合う正しい語。", "電気": "意味：「電気ガス」という語はなく、料理に使うガスの種類として合わない。", "毒": "意味：毒ガスで料理はしない。", "時間": "意味：「時間ガス」という語はなく、文が成立しない。"}, "sentence_index": 6, "correct_answer": "天然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天然が人工か、見て分かりますか。", "explanation": "助詞の混同：選択を表す「か」を「が」にしている。"}, {"text": "天然か人工か、見て分かるますか。", "explanation": "活用の誤り：「分かるます」ではなく「分かります」が正しい。"}, {"text": "天然か人工か、見てを分かりますか。", "explanation": "助詞の誤り：「見て」の後に「を」は入らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04e1d9ab-3efb-4f6d-8f3f-b4ce787f2fa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
