INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52832, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在の場所を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語標示で、「ある」とは結びつかない。"}, {"text": "で", "is_correct": false, "explanation": "動作の場所を表し、存在の「ある」には使えない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、存在の「ある」とは結びつかない。"}], "correct_answer": "に", "explanations": {"に": "存在の場所を表す。", "を": "目的語標示で、「ある」とは結びつかない。", "で": "動作の場所を表し、存在の「ある」には使えない。", "へ": "方向を表し、存在の「ある」とは結びつかない。"}, "error_tags": {"を": "object_marking", "で": "location_vs_target", "へ": "location_vs_target"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "表面", "is_correct": true, "explanation": "奥底と反対に、外側を指す。"}, {"text": "心底", "is_correct": false, "explanation": "奥底に近い意味で対義ではない。"}, {"text": "手紙", "is_correct": false, "explanation": "無関係の語。"}, {"text": "中身", "is_correct": false, "explanation": "内部を指し、対義ではない。"}], "correct_answer": "表面", "explanations": {"表面": "奥底と反対に、外側を指す。", "心底": "奥底に近い意味で対義ではない。", "手紙": "無関係の語。", "中身": "内部を指し、対義ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04e1d9ab-3efb-4f6d-8f3f-b4ce787f2fa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38117, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "連鎖", "is_correct": true, "explanation": "正解。「連鎖」（れんさ）。"}, {"text": "煉瓦", "is_correct": false, "explanation": "「煉瓦」はれんがと読み、「さ」が「が」に変わる一モーラ差。"}, {"text": "廉価", "is_correct": false, "explanation": "「廉価」はれんかと読み、「さ」が「か」に変わる一モーラ差。"}, {"text": "検査", "is_correct": false, "explanation": "「検査」はけんさと読み、「れ」が「け」に変わる一モーラ差。"}, {"text": "偏差", "is_correct": false, "explanation": "「偏差」はへんさと読み、「れ」が「へ」に変わる一モーラ差。"}], "explanations": {"連鎖": "正解。「連鎖」（れんさ）。", "煉瓦": "「煉瓦」はれんがと読み、「さ」が「が」に変わる一モーラ差。", "廉価": "「廉価」はれんかと読み、「さ」が「か」に変わる一モーラ差。", "検査": "「検査」はけんさと読み、「れ」が「け」に変わる一モーラ差。", "偏差": "「偏差」はへんさと読み、「れ」が「へ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "連鎖"}, "level_3": {"options": [{"text": "連鎖", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "停止", "is_correct": false, "explanation": "意味：操作が止まることで、次々と続く染色工程の意味にならない。"}, {"text": "価格", "is_correct": false, "explanation": "意味：化学的操作の値段ではなく、文意に合わない。"}, {"text": "無視", "is_correct": false, "explanation": "項構造：「操作の無視ではなく」は対比として不自然。"}], "explanations": {"連鎖": "文脈に合う正しい語。", "停止": "意味：操作が止まることで、次々と続く染色工程の意味にならない。", "価格": "意味：化学的操作の値段ではなく、文意に合わない。", "無視": "項構造：「操作の無視ではなく」は対比として不自然。"}, "sentence_index": 0, "correct_answer": "連鎖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "失敗の連鎖に止めたい。", "explanation": "助詞の混同：他動詞「止める」の目的語は「を」で、「に」は誤り。"}, {"text": "失敗の連鎖を二枚止めたい。", "explanation": "助数詞の誤り：連鎖を「枚」で数えない。"}, {"text": "失敗の連鎖を止めるたい。", "explanation": "活用の誤り：「たい」は連用形につき「止めたい」が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04e1d9ab-3efb-4f6d-8f3f-b4ce787f2fa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EX