INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37739, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高度", "is_correct": true, "explanation": "正解。「高度」（こうど）。"}, {"text": "口語", "is_correct": false, "explanation": "「口語」はこうごと読み、「ど」が「ご」に変わる一モーラ差。"}, {"text": "国土", "is_correct": false, "explanation": "「国土」はこくどと読み、「う」が「く」に変わる一モーラ差。"}, {"text": "今度", "is_correct": false, "explanation": "「今度」はこんどと読み、長音「う」が「ん」に変わる一モーラ差。"}, {"text": "航路", "is_correct": false, "explanation": "「航路」はこうろと読み、「ど」が「ろ」に変わる一モーラ差。"}], "explanations": {"高度": "正解。「高度」（こうど）。", "口語": "「口語」はこうごと読み、「ど」が「ご」に変わる一モーラ差。", "国土": "「国土」はこくどと読み、「う」が「く」に変わる一モーラ差。", "今度": "「今度」はこんどと読み、長音「う」が「ん」に変わる一モーラ差。", "航路": "「航路」はこうろと読み、「ど」が「ろ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "高度"}, "level_3": {"options": [{"text": "高度", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "値段", "is_correct": false, "explanation": "意味：飛行機が値段を上げるのは飛行の文脈に合わない。"}, {"text": "体重", "is_correct": false, "explanation": "意味：飛行機の体重とは言わない。"}, {"text": "温度", "is_correct": false, "explanation": "連語：「温度を上げている」は飛行の高さの意味にならない。"}], "explanations": {"高度": "文脈に合う正しい語。", "値段": "意味：飛行機が値段を上げるのは飛行の文脈に合わない。", "体重": "意味：飛行機の体重とは言わない。", "温度": "連語：「温度を上げている」は飛行の高さの意味にならない。"}, "sentence_index": 0, "correct_answer": "高度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鳥はとても高い高度が飛べる。", "explanation": "助詞の混同：経過する空間は「を」で示す。"}, {"text": "鳥はとても高い高度を三冊飛べる。", "explanation": "助数詞の誤り：高度を「冊」で数えない。"}, {"text": "鳥はとても高い高度を飛べった。", "explanation": "活用の誤り：「飛べった」ではなく「飛べた」が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04e1d9ab-3efb-4f6d-8f3f-b4ce787f2fa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
