INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37739, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "状況・範囲を限定し、「この高度では」となる。"}, {"text": "を", "is_correct": false, "explanation": "目的語標示で、「この高度をは」は非文。"}, {"text": "と", "is_correct": false, "explanation": "並列・引用を表し、「この高度とは空気が薄い」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、「この高度へは空気が薄い」は非文。"}], "correct_answer": "で", "explanations": {"で": "状況・範囲を限定し、「この高度では」となる。", "を": "目的語標示で、「この高度をは」は非文。", "と": "並列・引用を表し、「この高度とは空気が薄い」は不自然。", "へ": "方向を表し、「この高度へは空気が薄い」は非文。"}, "error_tags": {"を": "object_marking", "と": "listing", "へ": "location_vs_target"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04e1d9ab-3efb-4f6d-8f3f-b4ce787f2fa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37739, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "高度", "is_correct": true, "explanation": "正解。「高度」（こうど）。"}, {"text": "酵素", "is_correct": false, "explanation": "「酵素」はこうそと読み、「ど」が「そ」に変わる一モーラ差。"}, {"text": "航路", "is_correct": false, "explanation": "「航路」はこうろと読み、最後の「ど」が「ろ」に変わる一モーラ差。"}, {"text": "今度", "is_correct": false, "explanation": "「今度」はこんどと読み、長音が撥音「ん」に変わる一モーラ差。"}, {"text": "強度", "is_correct": false, "explanation": "「強度」はきょうどと読み、「こ」が「きょ」に変わる一モーラ差。"}], "explanations": {"高度": "正解。「高度」（こうど）。", "酵素": "「酵素」はこうそと読み、「ど」が「そ」に変わる一モーラ差。", "航路": "「航路」はこうろと読み、最後の「ど」が「ろ」に変わる一モーラ差。", "今度": "「今度」はこんどと読み、長音が撥音「ん」に変わる一モーラ差。", "強度": "「強度」はきょうどと読み、「こ」が「きょ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "高度"}, "level_3": {"options": [{"text": "高度", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "声", "is_correct": false, "explanation": "意味：飛行機が声を下げることはない。"}, {"text": "名前", "is_correct": false, "explanation": "意味：名前を下げるとは言わない。"}, {"text": "窓", "is_correct": false, "explanation": "意味：窓を下げ始めたでは飛行の文脈にならない。"}], "explanations": {"高度": "文脈に合う正しい語。", "声": "意味：飛行機が声を下げることはない。", "名前": "意味：名前を下げるとは言わない。", "窓": "意味：窓を下げ始めたでは飛行の文脈にならない。"}, "sentence_index": 6, "correct_answer": "高度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "高度を変わると気温も変わる。", "explanation": "助詞の混同：自動詞「変わる」の主語は「が」。"}, {"text": "高度が変わるると気温も変わる。", "explanation": "活用の誤り：「変わるる」ではなく「変わる」が正しい。"}, {"text": "高度が変わると変わる気温も。", "explanation": "語順の誤り：述語が主語の前に出て「も」で文が終わっている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04e1d9ab-3efb-4f6d-8f3f-b4ce787f2fa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
