INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37739, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「見る」の目的語を表す。"}, {"text": "が", "is_correct": false, "explanation": "主格で、目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、「高度へ見て」は非文。"}], "correct_answer": "を", "explanations": {"を": "他動詞「見る」の目的語を表す。", "が": "主格で、目的語にならない。", "に": "着点を表し、非文。", "へ": "方向を表し、「高度へ見て」は非文。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "へ": "location_vs_target"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04e1d9ab-3efb-4f6d-8f3f-b4ce787f2fa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35199, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人類", "is_correct": true, "explanation": "正解。「人類」（じんるい）。"}, {"text": "人体", "is_correct": false, "explanation": "「人体」はじんたいと読み、「る」が「た」に変わる一モーラ差。"}, {"text": "親類", "is_correct": false, "explanation": "「親類」はしんるいと読み、「じ」が清音「し」になる清濁の対立。"}, {"text": "分類", "is_correct": false, "explanation": "「分類」はぶんるいと読み、「じ」が「ぶ」に変わる一モーラ差。"}], "explanations": {"人類": "正解。「人類」（じんるい）。", "人体": "「人体」はじんたいと読み、「る」が「た」に変わる一モーラ差。", "親類": "「親類」はしんるいと読み、「じ」が清音「し」になる清濁の対立。", "分類": "「分類」はぶんるいと読み、「じ」が「ぶ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "人類"}, "level_3": {"options": [{"text": "人類", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "机", "is_correct": false, "explanation": "意味：机は術を磨けない。"}, {"text": "植物", "is_correct": false, "explanation": "意味：植物が植物の生命力を宿す術を磨くのは文意に合わない。"}, {"text": "繊維", "is_correct": false, "explanation": "項構造：繊維は術を磨く主体になれない。"}], "explanations": {"人類": "文脈に合う正しい語。", "机": "意味：机は術を磨けない。", "植物": "意味：植物が植物の生命力を宿す術を磨くのは文意に合わない。", "繊維": "項構造：繊維は術を磨く主体になれない。"}, "sentence_index": 0, "correct_answer": "人類"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "月に行くのは人類を夢だった。", "explanation": "助詞の混同：「人類の夢」の「の」を「を」にしている。"}, {"text": "月に行くのは三匹の人類の夢だった。", "explanation": "助数詞の誤り：人類全体を「匹」で数えない。"}, {"text": "月に行くのは夢人類のだった。", "explanation": "語順の誤り：「人類の」が修飾する「夢」の後ろに置かれている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04e1d9ab-3efb-4f6d-8f3f-b4ce787f2fa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
