INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36011, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が始まったばかりの段階。時間的に最初の部分。", "primary_collocate": null, "pronunciation": "しょき", "ipa": "ɕokʲi", "syllable_count": 2, "sentences": [{"text": "初期段階では、投資家からの資金調達を通じて事業の基盤を固め、市場での急速な成長を目指す。", "target_word": "初期", "complexity_tier": "T3", "furigana": "しょき", "sentence_source": "mined"}, {"text": "特に、初期段階のスタートアップ資金調達を担う彼らの役割は、単なる資本の提供にとどまらない。", "target_word": "初期", "complexity_tier": "T3", "furigana": "しょき", "sentence_source": "mined"}, {"text": "病気は初期なら治りやすい。", "target_word": "初期", "complexity_tier": "T3", "furigana": "びょうき しょき なお", "sentence_source": "generated"}, {"text": "この絵は画家の初期の作品だ。", "target_word": "初期", "complexity_tier": "T3", "furigana": "え がか しょき さくひん", "sentence_source": "generated"}, {"text": "初期のゲームはとても簡単だった。", "target_word": "初期", "complexity_tier": "T3", "furigana": "しょき かんたん", "sentence_source": "generated"}, {"text": "問題は初期に見つけるのが大切だ。", "target_word": "初期", "complexity_tier": "T3", "furigana": "もんだい しょき み たいせつ", "sentence_source": "generated"}, {"text": "江戸時代の初期に城が建てられた。", "target_word": "初期", "complexity_tier": "T3", "furigana": "えど じだい しょき しろ た", "sentence_source": "generated"}, {"text": "その会社は初期に苦労した。", "target_word": "初期", "complexity_tier": "T3", "furigana": "かいしゃ しょき くろう", "sentence_source": "generated"}, {"text": "彼は初期からのメンバーだ。", "target_word": "初期", "complexity_tier": "T3", "furigana": "かれ しょき", "sentence_source": "generated"}, {"text": "初期の計画は少し変わった。", "target_word": "初期", "complexity_tier": "T3", "furigana": "しょき けいかく すこ か", "sentence_source": "generated"}], "morphological_forms": [{"form": "初期段階", "label": "派生"}, {"form": "初期化", "label": "派生"}, {"form": "初期設定", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事が始まったばかりの段階", "collocate_grounding": {"status": "no_source",