INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36007, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "録音や録画した音や映像をもう一度流すこと。", "primary_collocate": null, "pronunciation": "さいせい", "ipa": "sai.seː", "syllable_count": 4, "sentences": [{"text": "この取り組みは、単なる植物の栽培を超え、環境再生と社会的結束の醸成を同時に企図する点に特徴がある。", "target_word": "再生", "complexity_tier": "T3", "furigana": "さいせい", "sentence_source": "mined"}, {"text": "再生可能エネルギーの導入加速にもかかわらず、製造プロセスの性質上、炭素発生をゼロ化し得ない領域において、CCUSは極めて重要な役割を担う。", "target_word": "再生", "complexity_tier": "T3", "furigana": "さいせい", "sentence_source": "mined"}, {"text": "動画の再生が急に止まった。", "target_word": "再生", "complexity_tier": "T3", "furigana": "どうが さいせい きゅう と", "sentence_source": "generated"}, {"text": "ボタンを押して再生してください。", "target_word": "再生", "complexity_tier": "T3", "furigana": "お さいせい", "sentence_source": "generated"}, {"text": "この曲の再生回数はとても多い。", "target_word": "再生", "complexity_tier": "T3", "furigana": "きょく さいせい かいすう おお", "sentence_source": "generated"}, {"text": "録音した声を再生して聞いた。", "target_word": "再生", "complexity_tier": "T3", "furigana": "ろくおん こえ さいせい き", "sentence_source": "generated"}, {"text": "再生中に画面が暗くなった。", "target_word": "再生", "complexity_tier": "T3", "furigana": "さいせいちゅう がめん くら", "sentence_source": "generated"}, {"text": "先生がビデオを再生している。", "target_word": "再生", "complexity_tier": "T3", "furigana": "せんせい さいせい", "sentence_source": "generated"}, {"text": "もう一度最初から再生しよう。", "target_word": "再生", "complexity_tier": "T3", "furigana": "いちど さいしょ さいせい", "sentence_source": "generated"}, {"text": "このアプリは音楽の再生ができる。", "target_word": "再生", "complexity_tier": "T3", "furigana": "おんがく さいせい", "sentence_source": "generated"}], "morphological_forms": [{"form": "再生する", "label": "活用"}, {"form": "再生した", "label": "活用"}, {"form": "再生ボタン", "label": "派生"}, {"form": "再生回数", "label": "派生"}], "register": "formal", "sense_fingerprint": "