INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53168, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "同じ地域や同じ関心を持つ人々が交流し合う集団。", "primary_collocate": null, "pronunciation": "こみゅにてぃ", "ipa": "ko.mʲɯ.ni.tʲi", "syllable_count": 4, "sentences": [{"text": "近年、都市の無秩序な拡大に伴う緑の希薄化に歯止めをかけるべく、地域コミュニティガーデンプロジェクトが各地で顕在化している。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "こみゅにてぃ", "sentence_source": "mined"}, {"text": "コンクリートの打ちっぱなしという素材感を活かした設計は、入居者のコミュニティ形成に多大な社会的影響を与えました。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "こみゅにてぃ", "sentence_source": "mined"}, {"text": "町のコミュニティに参加した。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "まち さんか", "sentence_source": "generated"}, {"text": "このコミュニティはとても温かい。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "あたた", "sentence_source": "generated"}, {"text": "ネットのコミュニティで友達ができた。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "ともだち", "sentence_source": "generated"}, {"text": "コミュニティの集まりが毎月ある。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "あつ まいつき", "sentence_source": "generated"}, {"text": "新しいコミュニティを作りたい。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "あたら つく", "sentence_source": "generated"}, {"text": "祖父は地元のコミュニティで働く。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "そふ じもと はたら", "sentence_source": "generated"}, {"text": "コミュニティが小さくなっている。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "ちい", "sentence_source": "generated"}, {"text": "みんなでコミュニティを支えている。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "ささ", "sentence_source": "generated"}], "morphological_forms": [{"form": "コミュニティー", "label": "派生"}, {"form": "地域コミュニティ", "label": "派生"}, {"form": "オンラインコミュニティ", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 交流