INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36659, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事の、特定の部分や見方。", "primary_collocate": null, "pronunciation": "そくめん", "ipa": "so.kɯ.meɴ", "syllable_count": 4, "sentences": [{"text": "特に、住民の主体的な参加により創出されるガーデンは、生物多様性の回復のみならず、微気候の改善といった側面においても近隣緑地に好影響を及ぼしている。", "target_word": "側面", "complexity_tier": "T3", "furigana": "そくめん", "sentence_source": "mined"}, {"text": "中央銀行による大規模な資産買入オペレーション、すなわち量的緩和政策は、単なる流動性の供給にとどまらず、国債市場における価格発見機能を歪曲せしめる側面を孕んでいる。", "target_word": "側面", "complexity_tier": "T3", "furigana": "そくめん", "sentence_source": "mined"}, {"text": "彼には優しい側面もある。", "target_word": "側面", "complexity_tier": "T3", "furigana": "かれ やさ そくめん", "sentence_source": "generated"}, {"text": "この問題には二つの側面がある。", "target_word": "側面", "complexity_tier": "T3", "furigana": "もんだい ふた そくめん", "sentence_source": "generated"}, {"text": "別の側面から考えてみよう。", "target_word": "側面", "complexity_tier": "T3", "furigana": "べつ そくめん かんが", "sentence_source": "generated"}, {"text": "経済的な側面が大切だ。", "target_word": "側面", "complexity_tier": "T3", "furigana": "けいざいてき そくめん たいせつ", "sentence_source": "generated"}, {"text": "その側面は見落とされていた。", "target_word": "側面", "complexity_tier": "T3", "furigana": "そくめん みお", "sentence_source": "generated"}, {"text": "新しい側面を知って驚いた。", "target_word": "側面", "complexity_tier": "T3", "furigana": "あたら そくめん し おどろ", "sentence_source": "generated"}, {"text": "社会の側面について話し合う。", "target_word": "側面", "complexity_tier": "T3", "furigana": "しゃかい そくめん はな あ", "sentence_source": "generated"}, {"text": "どの側面を重視するかが問題だ。", "target_word": "側面", "complexity_tier": "T3", "furigana": "そくめん じゅうし もんだい", "sentence_source": "generated"}], "morphological_forms": [{"form": "側面的", "label": "派生"}, {"form": "側面から", "label": "派生"}, {"form": "一側面", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事