INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35529, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある範囲の土地や場所。", "primary_collocate": null, "pronunciation": "ちいき", "ipa": "tɕi.i.ki", "syllable_count": 3, "sentences": [{"text": "近年、都市の無秩序な拡大に伴う緑の希薄化に歯止めをかけるべく、地域コミュニティガーデンプロジェクトが各地で顕在化している。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき", "sentence_source": "mined"}, {"text": "既存の緑地と有機的にネットワークを形成することで生態系の回廊としての機能を補完し、ひいては地域全体の環境リテラシーを向上させる原動力となり得るのである。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき", "sentence_source": "mined"}, {"text": "彼がこれらを大切に育てる理由は、地域の子供たちに安全な給食を安定的に提供するためだ。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき", "sentence_source": "mined"}, {"text": "この地域は雪が多い。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき ゆき おお", "sentence_source": "generated"}, {"text": "地域の祭りに行った。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき まつ い", "sentence_source": "generated"}, {"text": "寒い地域で育った。", "target_word": "地域", "complexity_tier": "T3", "furigana": "さむ ちいき そだ", "sentence_source": "generated"}, {"text": "地域によって言葉が違う。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき ことば ちが", "sentence_source": "generated"}, {"text": "その地域には川がある。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき かわ", "sentence_source": "generated"}, {"text": "地域の人と掃除をした。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき ひと そうじ", "sentence_source": "generated"}, {"text": "山の多い地域に住んでいる。", "target_word": "地域", "complexity_tier": "T3", "furigana": "やま おお ちいき す", "sentence_source": "generated"}], "morphological_forms": [{"form": "地域的", "label": "派生"}, {"form": "地域社会", "label": "派生"}, {"form": "地域差", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 一定の範囲の土地", "collocate_grounding": {"status": "no_sou