INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37453, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "足りない部分を補って、完全にすること。", "primary_collocate": null, "pronunciation": "ほかん", "ipa": "ho.kaɴ", "syllable_count": 3, "sentences": [{"text": "既存の緑地と有機的にネットワークを形成することで生態系の回廊としての機能を補完し、ひいては地域全体の環境リテラシーを向上させる原動力となり得るのである。", "target_word": "補完", "complexity_tier": "T3", "furigana": "ほかん", "sentence_source": "mined"}, {"text": "不確実性の高い技術的課題に挑む起業家に対し、リスクマネーを供給することで、彼らは市場の失敗を補完し、破壊的なイノベーションの萌芽を育むのである。", "target_word": "補完", "complexity_tier": "T3", "furigana": "ほかん", "sentence_source": "mined"}, {"text": "二人は互いに補完している。", "target_word": "補完", "complexity_tier": "T3", "furigana": "ふたり たが ほかん", "sentence_source": "generated"}, {"text": "足りない情報を補完した。", "target_word": "補完", "complexity_tier": "T3", "furigana": "た じょうほう ほかん", "sentence_source": "generated"}, {"text": "この本は授業を補完する。", "target_word": "補完", "complexity_tier": "T3", "furigana": "ほん じゅぎょう ほかん", "sentence_source": "generated"}, {"text": "補完の役目を果たす道具だ。", "target_word": "補完", "complexity_tier": "T3", "furigana": "ほかん やくめ は どうぐ", "sentence_source": "generated"}, {"text": "データの補完が必要だ。", "target_word": "補完", "complexity_tier": "T3", "furigana": "ほかん ひつよう", "sentence_source": "generated"}, {"text": "弱い点を補完し合おう。", "target_word": "補完", "complexity_tier": "T3", "furigana": "よわ てん ほかん あ", "sentence_source": "generated"}, {"text": "説明の補完として図を使う。", "target_word": "補完", "complexity_tier": "T3", "furigana": "せつめい ほかん ず つか", "sentence_source": "generated"}, {"text": "先生の話を本で補完する。", "target_word": "補完", "complexity_tier": "T3", "furigana": "せんせい はなし ほん ほかん", "sentence_source": "generated"}], "morphological_forms": [{"form": "補完する", "label": "活用"}, {"form": "補完した", "label": "活用"}, {"form": "補完し合う", "label": "派生"}, {"form": "補完的", "label": "派生"}], "register": "formal", "sense_fingerprint"