INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37453, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "補完", "is_correct": true, "explanation": "正解。「補完（ほかん）」と聞こえる。"}, {"text": "下巻", "is_correct": false, "explanation": "「げかん」と読み、最初の拍が違う別の語。"}, {"text": "移管", "is_correct": false, "explanation": "「いかん」と読み、最初の拍が違う別の語。"}, {"text": "美観", "is_correct": false, "explanation": "「びかん」と読み、最初の拍が違う別の語。"}, {"text": "保険", "is_correct": false, "explanation": "「ほけん」と読み、二つ目の拍が違う別の語。"}], "explanations": {"補完": "正解。「補完（ほかん）」と聞こえる。", "下巻": "「げかん」と読み、最初の拍が違う別の語。", "移管": "「いかん」と読み、最初の拍が違う別の語。", "美観": "「びかん」と読み、最初の拍が違う別の語。", "保険": "「ほけん」と読み、二つ目の拍が違う別の語。"}, "sentence_index": null, "correct_answer": "補完"}, "level_3": {"options": [{"text": "補完", "is_correct": true, "explanation": "文脈に合う唯一の語。"}, {"text": "昼寝", "is_correct": false, "explanation": "「データの昼寝」は意味が通らない。"}, {"text": "散歩", "is_correct": false, "explanation": "文脈に合わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "データを洗濯することはない。"}], "explanations": {"補完": "文脈に合う唯一の語。", "昼寝": "「データの昼寝」は意味が通らない。", "散歩": "文脈に合わない。", "洗濯": "データを洗濯することはない。"}, "sentence_index": 6, "correct_answer": "補完"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公園を補完して走った。", "explanation": "移動の意味ではない。"}, {"text": "音楽を補完して踊った。", "explanation": "踊る意味ではない。"}, {"text": "お茶を補完して飲んだ。", "explanation": "飲む意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdfefe4-8ec6-4c0d-80ea-0b95dc66eb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
