INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35917, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "物のサイズや程度、規模が標準以上であること。", "primary_collocate": null, "pronunciation": "おおきい", "ipa": "oːkiː", "syllable_count": 4, "sentences": [{"text": "その社会的意義は極めて大きい。", "target_word": "大きい", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "都会の限られたスペースを持つアパートメントでは、モダンなインテリアデザインが空間の印象を大きく左右します。", "target_word": "大きく", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "この犬はとても大きい。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "おお", "sentence_source": "generated"}, {"text": "大きい箱を二つ買った。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "おお はこ ふた か", "sentence_source": "generated"}, {"text": "彼の声は大きくて元気だ。", "target_word": "大きく", "complexity_tier": "T3", "furigana": "かれ こえ おお げんき", "sentence_source": "generated"}, {"text": "父の手は大きい。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "ちち て おお", "sentence_source": "generated"}, {"text": "大きいかばんが欲しい。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "おお ほ", "sentence_source": "generated"}, {"text": "この町は前より大きくなった。", "target_word": "大きく", "complexity_tier": "T3", "furigana": "まち まえ おお", "sentence_source": "generated"}, {"text": "問題はとても大きいと思う。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "もんだい おお おも", "sentence_source": "generated"}, {"text": "大きい木の下で休んだ。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "おお き した やす", "sentence_source": "generated"}], "morphological_forms": [{"form": "大きかった", "label": "活用"}, {"form": "大きく", "label": "活用"}, {"form": "大きくない", "label": "活用"}, {"form": "大きさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | サイズや程度が標準より上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: アパートメント (Zipf 2.37)']::text[], 'bd46283a-be24-4984-9df4-26cf7330d10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36953, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "悪くなった状態が、もとのよい状態にもどること。", "primary_collocate": null, "pronunciation": "かいふく", "ipa": "kaiɸɯkɯ", "syllable_count": 4, "sentences": [{"text": "特に、住民の主体的な参加により創出されるガーデンは、生物多様性の回復のみならず、微気候の改善といった側面においても近隣緑地に好影響を及ぼしている。", "target_word": "回復", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "次いで、ラズベリー等のジャムを対になる片割れ、あるいは同一の切片上に重ね合わせる。\n\n甘味と塩気、滑らかさと顆粒感が口腔内で織りなす対照的なハーモニーは、単なる栄養補給の域を超え、短時間での認知機能回復をもたらし、合理性と美学が融合した食の営みとして完成する。", "target_word": "回復", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "祖母の体の回復を祈っている。", "target_word": "回復", "complexity_tier": "T3", "furigana": "そぼ からだ かいふく いの", "sentence_source": "generated"}, {"text": "景気の回復はまだ遅い。", "target_word": "回復", "complexity_tier": "T3", "furigana": "けいき かいふく おそ", "sentence_source": "generated"}, {"text": "彼は病気から回復した。", "target_word": "回復", "complexity_tier": "T3", "furigana": "かれ びょうき かいふく", "sentence_source": "generated"}, {"text": "よく寝ると体力が回復する。", "target_word": "回復", "complexity_tier": "T3", "furigana": "ね たいりょく かいふく", "sentence_source": "generated"}, {"text": "回復には時間がかかる。", "target_word": "回復", "complexity_tier": "T3", "furigana": "かいふく じかん", "sentence_source": "generated"}, {"text": "信頼の回復は難しい。", "target_word": "回復", "complexity_tier": "T3", "furigana": "しんらい かいふく むずか", "sentence_source": "generated"}, {"text": "天気が回復して晴れた。", "target_word": "回復", "complexity_tier": "T3", "furigana": "てんき かいふく は", "sentence_source": "generated"}, {"text": "早い回復を願っています。", "target_word": "回復", "complexity_tier": "T3", "furigana": "はや かいふく ねが", "sentence_source": "generated"}], "morphological_forms": [{"form": "回復する", "label": "派生"}, {"form": "回復した", "label": "活用"}, {"form": "回復力", "label": "派生"}, {"form": "回復期", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 悪い状態から元に戻ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 好影響 (Zipf 2.16)','sentence 1 above tier T2: contains vocabulary far above tier T2: 切片 (Zipf 1.86)']::text[], 'bd46283a-be24-4984-9df4-26cf7330d10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36831, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物の葉のような色。また、草や木。", "primary_collocate": null, "pronunciation": "みどり", "ipa": "midoɾi", "syllable_count": 3, "sentences": [{"text": "近年、都市の無秩序な拡大に伴う緑の希薄化に歯止めをかけるべく、地域コミュニティガーデンプロジェクトが各地で顕在化している。", "target_word": "緑", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "さらに、こうした緑の拠点が生み出す波及効果は計り知れない。", "target_word": "緑", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "鉢という限定された宇宙の中で、命は水という恩恵を糧に、時を重ねてその緑を深めていく。", "target_word": "緑", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "公園には緑が多い。", "target_word": "緑", "complexity_tier": "T3", "furigana": "こうえん みどり おお", "sentence_source": "generated"}, {"text": "春になると山が緑になる。", "target_word": "緑", "complexity_tier": "T3", "furigana": "はる やま みどり", "sentence_source": "generated"}, {"text": "緑のシャツを着ている。", "target_word": "緑", "complexity_tier": "T3", "furigana": "みどり き", "sentence_source": "generated"}, {"text": "窓から緑が見えて気持ちいい。", "target_word": "緑", "complexity_tier": "T3", "furigana": "まど みどり み きも", "sentence_source": "generated"}, {"text": "町の緑を守りたい。", "target_word": "緑", "complexity_tier": "T3", "furigana": "まち みどり まも", "sentence_source": "generated"}, {"text": "信号が緑に変わった。", "target_word": "緑", "complexity_tier": "T3", "furigana": "しんごう みどり か", "sentence_source": "generated"}, {"text": "緑の葉がきれいだ。", "target_word": "緑", "complexity_tier": "T3", "furigana": "みどり は", "sentence_source": "generated"}], "morphological_forms": [{"form": "緑色", "label": "派生"}, {"form": "緑茶", "label": "派生"}, {"form": "緑地", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 草木の葉のような色や植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 4 words above tier T2 (max 3): 無秩序 (Zipf 2.99), 希薄 (Zipf 3.22), 歯止め (Zipf 3.18), 顕在 (Zipf 3.05)']::text[], 'bd46283a-be24-4984-9df4-26cf7330d10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37471, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "集まって行う活動やイベントに加わること。", "primary_collocate": null, "pronunciation": "さんか", "ipa": "saŋka", "syllable_count": 3, "sentences": [{"text": "特に、住民の主体的な参加により創出されるガーデンは、生物多様性の回復のみならず、微気候の改善といった側面においても近隣緑地に好影響を及ぼしている。", "target_word": "参加", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "この創造的プロセスこそが、行事の記憶を永続的なものへと変貌させ、参加者の帰属意識を強固なものへと昇華させるのである。", "target_word": "参加", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "友だちと大会に参加した。", "target_word": "参加", "complexity_tier": "T3", "furigana": "とも たいかい さんか", "sentence_source": "generated"}, {"text": "参加は自由です。", "target_word": "参加", "complexity_tier": "T3", "furigana": "さんか じゆう", "sentence_source": "generated"}, {"text": "明日の会議に参加できますか。", "target_word": "参加", "complexity_tier": "T3", "furigana": "あした かいぎ さんか", "sentence_source": "generated"}, {"text": "参加の申し込みは今日までだ。", "target_word": "参加", "complexity_tier": "T3", "furigana": "さんか もう こ きょう", "sentence_source": "generated"}, {"text": "多くの人が祭りに参加している。", "target_word": "参加", "complexity_tier": "T3", "furigana": "おお ひと まつ さんか", "sentence_source": "generated"}, {"text": "彼は参加を決めた。", "target_word": "参加", "complexity_tier": "T3", "furigana": "かれ さんか き", "sentence_source": "generated"}, {"text": "参加者に名前を書いてもらう。", "target_word": "参加", "complexity_tier": "T3", "furigana": "さんかしゃ なまえ か", "sentence_source": "generated"}, {"text": "クラブ活動への参加が楽しい。", "target_word": "参加", "complexity_tier": "T3", "furigana": "かつどう さんか たの", "sentence_source": "generated"}], "morphological_forms": [{"form": "参加する", "label": "派生"}, {"form": "参加者", "label": "派生"}, {"form": "参加した", "label": "活用"}, {"form": "不参加", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 活動や行事に加わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 好影響 (Zipf 2.16)','sentence 1 above tier T1: 5 words above tier T1 (max 2): 永続 (Zipf 3.37), 変貌 (Zipf 3.46), 帰属 (Zipf 3.56), 強固 (Zipf 3.56), 昇華 (Zipf 3.35)']::text[], 'bd46283a-be24-4984-9df4-26cf7330d10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39285, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分の意思で行動する中心となる人や集団。", "primary_collocate": null, "pronunciation": "しゅたい", "ipa": "ɕɯtai", "syllable_count": 3, "sentences": [{"text": "特に、住民の主体的な参加により創出されるガーデンは、生物多様性の回復のみならず、微気候の改善といった側面においても近隣緑地に好影響を及ぼしている。", "target_word": "主体", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "グローバルな金融市場やサプライチェーンといった社会経済的文脈において、個々の企業や投資家といったミクロな主体による局所的な意思決定は、決して単純な線形モデルでは捉えきれない。", "target_word": "主体", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "なぜならば、無数の主体が限られた情報に基づき絶えず適応を繰り返す過程で、意図せぬイノベーションやシステミック・リスクが突発的に顕現するからに他ならない。", "target_word": "主体", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "この活動の主体は生徒だ。", "target_word": "主体", "complexity_tier": "T3", "furigana": "かつどう しゅたい せいと", "sentence_source": "generated"}, {"text": "市民が主体となって町を作る。", "target_word": "主体", "complexity_tier": "T3", "furigana": "しみん しゅたい まち つく", "sentence_source": "generated"}, {"text": "学ぶ主体は自分自身だ。", "target_word": "主体", "complexity_tier": "T3", "furigana": "まな しゅたい じぶんじしん", "sentence_source": "generated"}, {"text": "若者主体の会が開かれた。", "target_word": "主体", "complexity_tier": "T3", "furigana": "わかもの しゅたい かい ひら", "sentence_source": "generated"}, {"text": "行動の主体を考える。", "target_word": "主体", "complexity_tier": "T3", "furigana": "こうどう しゅたい かんが", "sentence_source": "generated"}, {"text": "主体がはっきりしない文だ。", "target_word": "主体", "complexity_tier": "T3", "furigana": "しゅたい ぶん", "sentence_source": "generated"}, {"text": "地域の住民が主体だ。", "target_word": "主体", "complexity_tier": "T3", "furigana": "ちいき じゅうみん しゅたい", "sentence_source": "generated"}], "morphological_forms": [{"form": "主体的", "label": "派生"}, {"form": "主体性", "label": "派生"}, {"form": "主体的に", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 自ら行動する中心となる者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: 4 words above tier T3 (max 3): サプライ (Zipf 3.19), ミクロ (Zipf 3.34), 局所 (Zipf 3.35), 線形 (Zipf 2.97)']::text[], 'bd46283a-be24-4984-9df4-26cf7330d10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37755, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "はっきりと表に現れていること。", "primary_collocate": null, "pronunciation": "けんざい", "ipa": "kenzai", "syllable_count": 4, "sentences": [{"text": "近年、都市の無秩序な拡大に伴う緑の希薄化に歯止めをかけるべく、地域コミュニティガーデンプロジェクトが各地で顕在化している。", "target_word": "顕在", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "まず、現場や鑑識ラボにおいて、肉眼では捉えられぬ潜在指紋を、シアノアクリレート法や光学的手法といったアプローチにより顕在化させる。", "target_word": "顕在", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "問題が顕在化してきた。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "もんだい けんざい か", "sentence_source": "generated"}, {"text": "不満が顕在化している。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "ふまん けんざいか", "sentence_source": "generated"}, {"text": "危険はまだ顕在していない。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "きけん けんざい", "sentence_source": "generated"}, {"text": "顕在する問題から考える。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "けんざい もんだい かんが", "sentence_source": "generated"}, {"text": "顕在的な需要を調べる。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "けんざいてき じゅよう しら", "sentence_source": "generated"}, {"text": "対立が顕在化した。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "たいりつ けんざいか", "sentence_source": "generated"}, {"text": "課題が顕在化する前に動く。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "かだい けんざいか まえ うご", "sentence_source": "generated"}, {"text": "リスクの顕在化を防ぐ。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "けんざいか ふせ", "sentence_source": "generated"}], "morphological_forms": [{"form": "顕在化", "label": "派生"}, {"form": "顕在的", "label": "派生"}, {"form": "顕在化する", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 表面にはっきり現れていること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T4: contains vocabulary far above tier T4: シアノアクリレート (Zipf 1.04)']::text[], 'bd46283a-be24-4984-9df4-26cf7330d10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35917, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大きい", "is_correct": true, "explanation": "正解：おおきい。"}, {"text": "雄々しい", "is_correct": false, "explanation": "おおしい。三つ目の「き」が「し」に変わる一モーラ差。"}, {"text": "大君", "is_correct": false, "explanation": "おおきみ。最後の「い」が「み」に変わる一モーラ差。"}, {"text": "おおきに", "is_correct": false, "explanation": "おおきに。最後の「い」が「に」に変わる一モーラ差。"}], "explanations": {"大きい": "正解：おおきい。", "雄々しい": "おおしい。三つ目の「き」が「し」に変わる一モーラ差。", "大君": "おおきみ。最後の「い」が「み」に変わる一モーラ差。", "おおきに": "おおきに。最後の「い」が「に」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "大きい"}, "level_3": {"options": [{"text": "大きい", "is_correct": true, "explanation": "意義の程度が標準以上であることを表す。"}, {"text": "丸い", "is_correct": false, "explanation": "意味：形を表す語で、意義の程度は表せない。"}, {"text": "冷たい", "is_correct": false, "explanation": "意味：温度を表す語で、意義には使えない。"}, {"text": "若い", "is_correct": false, "explanation": "連語：「意義」は年齢を表す「若い」と結びつかない。"}], "explanations": {"大きい": "意義の程度が標準以上であることを表す。", "丸い": "意味：形を表す語で、意義の程度は表せない。", "冷たい": "意味：温度を表す語で、意義には使えない。", "若い": "連語：「意義」は年齢を表す「若い」と結びつかない。"}, "sentence_index": 0, "correct_answer": "大きい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大きいな箱を二つ買った。", "explanation": "活用の誤り：い形容詞「大きい」は「な」を付けずに名詞を修飾する。"}, {"text": "大きく箱を二つ買った。", "explanation": "活用の誤り：名詞「箱」を修飾するには連用形「大きく」ではなく「大きい」。"}, {"text": "箱を大きい二つ買った。", "explanation": "語順の誤り：「大きい」は名詞「箱」の前に置く。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35917, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この犬はとても大きいだ。", "corrected_sentence": "この犬はとても大きい。", "error_description": "活用の誤り：い形容詞の後に「だ」は付けない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "大きく", "is_correct": true, "explanation": "動詞「左右します」を修飾するので連用形「く」が必要。"}, {"text": "大きい", "is_correct": false, "explanation": "終止・連体形で、動詞を修飾できない。"}, {"text": "大きかった", "is_correct": false, "explanation": "過去形で、動詞の前に置けない。"}, {"text": "大きくない", "is_correct": false, "explanation": "否定形で文意と矛盾し、形もつながらない。"}], "correct_form": "大きく", "base_form": "大きい", "form_label": "連用形（く形）", "sentence_index": 1, "explanations": {"大きく": "動詞「左右します」を修飾するので連用形「く」が必要。", "大きい": "終止・連体形で、動詞を修飾できない。", "大きかった": "過去形で、動詞の前に置けない。", "大きくない": "否定形で文意と矛盾し、形もつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35917, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小さい", "is_correct": true, "explanation": "サイズや程度が標準より下で、「大きい」の対義語。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表し、大きさの対義語ではない。"}, {"text": "長い", "is_correct": false, "explanation": "長さを表し、対義関係にない。"}, {"text": "高い", "is_correct": false, "explanation": "高さを表し、「大きい」の対義語ではない。"}], "correct_answer": "小さい", "explanations": {"小さい": "サイズや程度が標準より下で、「大きい」の対義語。", "重い": "重さを表し、大きさの対義語ではない。", "長い": "長さを表し、対義関係にない。", "高い": "高さを表し、「大きい」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35917, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大きい", "is_correct": true, "explanation": "読みは「おおきい」。"}, {"text": "大木戸", "is_correct": false, "explanation": "最後の「い」が「ど」になる一モーラ差の語（おおきど）。"}, {"text": "多い", "is_correct": false, "explanation": "「き」が抜けた語（おおい）。"}, {"text": "おおきに", "is_correct": false, "explanation": "最後の「い」が「に」になる一モーラ差の語。"}], "explanations": {"大きい": "読みは「おおきい」。", "大木戸": "最後の「い」が「ど」になる一モーラ差の語（おおきど）。", "多い": "「き」が抜けた語（おおい）。", "おおきに": "最後の「い」が「に」になる一モーラ差の語。"}, "sentence_index": null, "correct_answer": "大きい"}, "level_3": {"options": [{"text": "大きい", "is_correct": true, "explanation": "かばんのサイズを表し、自然に入る。"}, {"text": "眠い", "is_correct": false, "explanation": "意味：人の状態を表し、かばんには使えない。"}, {"text": "嬉しい", "is_correct": false, "explanation": "意味：気持ちを表し、物の性質にならない。"}, {"text": "痛い", "is_correct": false, "explanation": "連語：「痛いかばん」とは言わない。"}], "explanations": {"大きい": "かばんのサイズを表し、自然に入る。", "眠い": "意味：人の状態を表し、かばんには使えない。", "嬉しい": "意味：気持ちを表し、物の性質にならない。", "痛い": "連語：「痛いかばん」とは言わない。"}, "sentence_index": 6, "correct_answer": "大きい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きいの木の下で休んだ。", "explanation": "活用の誤り：い形容詞は「の」を挟まずに名詞を修飾する。"}, {"text": "大きく木の下で休んだ。", "explanation": "活用の誤り：名詞「木」を修飾するには「大きい」が必要。"}, {"text": "下で大きい木の休んだ。", "explanation": "語順の誤り：「大きい木の下で」の順でなければならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35917, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この町は前より大きいなった。", "corrected_sentence": "この町は前より大きくなった。", "error_description": "活用の誤り：「なる」の前は連用形「大きく」にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "大きく", "is_correct": true, "explanation": "「なる」の前は連用形「大きく」。"}, {"text": "大きい", "is_correct": false, "explanation": "終止形で「なった」につながらない。"}, {"text": "大きくて", "is_correct": false, "explanation": "て形は「なった」の前に置けない。"}, {"text": "大きければ", "is_correct": false, "explanation": "条件形で文が成り立たない。"}], "correct_form": "大きく", "base_form": "大きい", "form_label": "連用形（く形）", "sentence_index": 7, "explanations": {"大きく": "「なる」の前は連用形「大きく」。", "大きい": "終止形で「なった」につながらない。", "大きくて": "て形は「なった」の前に置けない。", "大きければ": "条件形で文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35917, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小さい", "is_correct": true, "explanation": "「大きい」の反対で、サイズが標準より下。"}, {"text": "広い", "is_correct": false, "explanation": "面積の広さで、対義語ではない。"}, {"text": "太い", "is_correct": false, "explanation": "太さを表し、対義関係にない。"}, {"text": "多い", "is_correct": false, "explanation": "数量を表し、「大きい」の対義語ではない。"}], "correct_answer": "小さい", "explanations": {"小さい": "「大きい」の反対で、サイズが標準より下。", "広い": "面積の広さで、対義語ではない。", "太い": "太さを表し、対義関係にない。", "多い": "数量を表し、「大きい」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36953, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回復", "is_correct": true, "explanation": "正解：かいふく。"}, {"text": "海賊", "is_correct": false, "explanation": "かいぞく。「ふ」が「ぞ」に変わる一モーラ差。"}, {"text": "快速", "is_correct": false, "explanation": "かいそく。「ふ」が「そ」に変わる一モーラ差。"}, {"text": "解読", "is_correct": false, "explanation": "かいどく。「ふ」が「ど」に変わる一モーラ差。"}, {"text": "開封", "is_correct": false, "explanation": "かいふう。最後の「く」が「う」に変わる一モーラ差。"}], "explanations": {"回復": "正解：かいふく。", "海賊": "かいぞく。「ふ」が「ぞ」に変わる一モーラ差。", "快速": "かいそく。「ふ」が「そ」に変わる一モーラ差。", "解読": "かいどく。「ふ」が「ど」に変わる一モーラ差。", "開封": "かいふう。最後の「く」が「う」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "回復"}, "level_3": {"options": [{"text": "回復", "is_correct": true, "explanation": "生物多様性が元のよい状態に戻ることを表す。"}, {"text": "出席", "is_correct": false, "explanation": "意味：人が会に出ることで、生物多様性には使えない。"}, {"text": "卒業", "is_correct": false, "explanation": "意味：学校を終えることで、文脈に合わない。"}, {"text": "到着", "is_correct": false, "explanation": "連語：「生物多様性の到着」とは言わない。"}], "explanations": {"回復": "生物多様性が元のよい状態に戻ることを表す。", "出席": "意味：人が会に出ることで、生物多様性には使えない。", "卒業": "意味：学校を終えることで、文脈に合わない。", "到着": "連語：「生物多様性の到着」とは言わない。"}, "sentence_index": 0, "correct_answer": "回復"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "景気が回復はまだ遅い。", "explanation": "助詞の混同：「景気の回復」と「の」でつなぐ。"}, {"text": "景気の回復はまだ遅かっている。", "explanation": "活用の誤り：い形容詞に「ている」は付かない。"}, {"text": "まだ景気の遅い回復は。", "explanation": "語順の誤り：主題と述語の構造が壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36953, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は病気を回復した。", "corrected_sentence": "彼は病気から回復した。", "error_description": "助詞の混同：病気の状態から戻るので「から」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36953, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「もたらす」の目的語を表す。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表し、目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、ここでは非文。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手を表し、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「もたらす」の目的語を表す。", "で": "手段・場所を表し、目的語にならない。", "へ": "方向を表し、ここでは非文。", "と": "並列・相手を表し、意味が通らない。"}, "error_tags": {"で": "instrument", "へ": "direction", "と": "listing"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悪化", "is_correct": true, "explanation": "状態が悪くなることで、「回復」の反対。"}, {"text": "改善", "is_correct": false, "explanation": "よくなることで、対義語ではない。"}, {"text": "治療", "is_correct": false, "explanation": "病気を治す行為で、対義関係にない。"}, {"text": "発展", "is_correct": false, "explanation": "伸びていくことで、反対の意味ではない。"}], "correct_answer": "悪化", "explanations": {"悪化": "状態が悪くなることで、「回復」の反対。", "改善": "よくなることで、対義語ではない。", "治療": "病気を治す行為で、対義関係にない。", "発展": "伸びていくことで、反対の意味ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36953, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "回復", "is_correct": true, "explanation": "読みは「かいふく」。"}, {"text": "快楽", "is_correct": false, "explanation": "「ふ」が「ら」になる一モーラ差の語（かいらく）。"}, {"text": "海賊", "is_correct": false, "explanation": "「ふ」が「ぞ」になる一モーラ差の語（かいぞく）。"}, {"text": "開幕", "is_correct": false, "explanation": "「ふ」が「ま」になる一モーラ差の語（かいまく）。"}, {"text": "会則", "is_correct": false, "explanation": "「ふ」が「そ」になる一モーラ差の語（かいそく）。"}], "explanations": {"回復": "読みは「かいふく」。", "快楽": "「ふ」が「ら」になる一モーラ差の語（かいらく）。", "海賊": "「ふ」が「ぞ」になる一モーラ差の語（かいぞく）。", "開幕": "「ふ」が「ま」になる一モーラ差の語（かいまく）。", "会則": "「ふ」が「そ」になる一モーラ差の語（かいそく）。"}, "sentence_index": null, "correct_answer": "回復"}, "level_3": {"options": [{"text": "回復", "is_correct": true, "explanation": "元の状態に戻るまでには時間が必要という意味になる。"}, {"text": "瞬間", "is_correct": false, "explanation": "意味：ごく短い時間で、「時間がかかる」と矛盾する。"}, {"text": "即答", "is_correct": false, "explanation": "意味：すぐに答えることで、時間がかからない。"}, {"text": "昨日", "is_correct": false, "explanation": "アスペクト：過去の日を表し、これからかかる時間と合わない。"}], "explanations": {"回復": "元の状態に戻るまでには時間が必要という意味になる。", "瞬間": "意味：ごく短い時間で、「時間がかかる」と矛盾する。", "即答": "意味：すぐに答えることで、時間がかからない。", "昨日": "アスペクト：過去の日を表し、これからかかる時間と合わない。"}, "sentence_index": 6, "correct_answer": "回復"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早い回復が願っています。", "explanation": "助詞の混同：願う対象は「を」で表す。"}, {"text": "回復を早い願っています。", "explanation": "語順の誤り：「早い」は名詞「回復」の前に置く。"}, {"text": "早い回復を一枚願っています。", "explanation": "助数詞の誤り：「回復」は数えられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36953, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天気を回復して晴れた。", "corrected_sentence": "天気が回復して晴れた。", "error_description": "助詞の混同：天気が自然に戻る意味では主語「が」を使い、「を」は取らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36953, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "名詞「信頼」と「回復」をつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "後ろに動詞がなく、目的語標示にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表し、名詞同士をつなげない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、ここでは非文。"}], "correct_answer": "の", "explanations": {"の": "名詞「信頼」と「回復」をつなぐ。", "を": "後ろに動詞がなく、目的語標示にならない。", "で": "手段を表し、名詞同士をつなげない。", "へ": "方向を表し、ここでは非文。"}, "error_tags": {"を": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悪化", "is_correct": true, "explanation": "よい状態が悪くなることで、「回復」の対義語。"}, {"text": "進歩", "is_correct": false, "explanation": "よくなっていくことで、対義語ではない。"}, {"text": "変化", "is_correct": false, "explanation": "単に変わることで、反対の意味ではない。"}, {"text": "安定", "is_correct": false, "explanation": "落ち着いた状態で、対義関係にない。"}], "correct_answer": "悪化", "explanations": {"悪化": "よい状態が悪くなることで、「回復」の対義語。", "進歩": "よくなっていくことで、対義語ではない。", "変化": "単に変わることで、反対の意味ではない。", "安定": "落ち着いた状態で、対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36831, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "緑", "is_correct": true, "explanation": "正解：みどり。"}, {"text": "千鳥", "is_correct": false, "explanation": "ちどり。最初の「み」が「ち」に変わる一モーラ差。"}, {"text": "実り", "is_correct": false, "explanation": "みのり。「ど」が「の」に変わる一モーラ差。"}, {"text": "看取り", "is_correct": false, "explanation": "みとり。「ど」と「と」の清濁の違い。"}, {"text": "御堂", "is_correct": false, "explanation": "みどう。最後の「り」が「う」に変わる一モーラ差。"}], "explanations": {"緑": "正解：みどり。", "千鳥": "ちどり。最初の「み」が「ち」に変わる一モーラ差。", "実り": "みのり。「ど」が「の」に変わる一モーラ差。", "看取り": "みとり。「ど」と「と」の清濁の違い。", "御堂": "みどう。最後の「り」が「う」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "緑"}, "level_3": {"options": [{"text": "緑", "is_correct": true, "explanation": "都市の草木が少なくなることを表す。"}, {"text": "赤", "is_correct": false, "explanation": "意味：色を表すが、都市で減る植物を指さない。"}, {"text": "夜", "is_correct": false, "explanation": "意味：時間を表し、文脈に合わない。"}, {"text": "机", "is_correct": false, "explanation": "連語：「机の希薄化」とは言わない。"}], "explanations": {"緑": "都市の草木が少なくなることを表す。", "赤": "意味：色を表すが、都市で減る植物を指さない。", "夜": "意味：時間を表し、文脈に合わない。", "机": "連語：「机の希薄化」とは言わない。"}, "sentence_index": 0, "correct_answer": "緑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公園には緑を多い。", "explanation": "助詞の混同：「多い」の主語は「が」で表す。"}, {"text": "公園には緑が三冊多い。", "explanation": "助数詞の誤り：緑は「冊」で数えない。"}, {"text": "多い公園には緑が。", "explanation": "語順の誤り：述語が前に出て文が壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36831, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春になると山が緑くなる。", "corrected_sentence": "春になると山が緑になる。", "error_description": "品詞の誤り：「緑」は名詞なので「緑くなる」ではなく「緑になる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36831, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "名詞「緑」と「拠点」をつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "目的語標示で、後ろの「拠点が」とつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、ここでは非文。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、名詞同士をつなげない。"}], "correct_answer": "の", "explanations": {"の": "名詞「緑」と「拠点」をつなぐ。", "を": "目的語標示で、後ろの「拠点が」とつながらない。", "へ": "方向を表し、ここでは非文。", "に": "着点を表し、名詞同士をつなげない。"}, "error_tags": {"を": "object_marking", "へ": "direction", "に": "location_vs_target"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36831, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "緑", "is_correct": true, "explanation": "読みは「みどり」。"}, {"text": "日取り", "is_correct": false, "explanation": "「み」が「ひ」になる一モーラ差の語（ひどり）。"}, {"text": "看取り", "is_correct": false, "explanation": "「ど」が清音「と」になった語（みとり）。"}, {"text": "見張り", "is_correct": false, "explanation": "「ど」が「は」になる一モーラ差の語（みはり）。"}, {"text": "身振り", "is_correct": false, "explanation": "「ど」が「ぶ」になる一モーラ差の語（みぶり）。"}], "explanations": {"緑": "読みは「みどり」。", "日取り": "「み」が「ひ」になる一モーラ差の語（ひどり）。", "看取り": "「ど」が清音「と」になった語（みとり）。", "見張り": "「ど」が「は」になる一モーラ差の語（みはり）。", "身振り": "「ど」が「ぶ」になる一モーラ差の語（みぶり）。"}, "sentence_index": null, "correct_answer": "緑"}, "level_3": {"options": [{"text": "緑", "is_correct": true, "explanation": "窓から草木が見えるという意味になる。"}, {"text": "音", "is_correct": false, "explanation": "項構造：音は聞こえるもので「見える」の主語にならない。"}, {"text": "匂い", "is_correct": false, "explanation": "項構造：匂いは見えない。"}, {"text": "宿題", "is_correct": false, "explanation": "意味：窓から見える景色ではない。"}], "explanations": {"緑": "窓から草木が見えるという意味になる。", "音": "項構造：音は聞こえるもので「見える」の主語にならない。", "匂い": "項構造：匂いは見えない。", "宿題": "意味：窓から見える景色ではない。"}, "sentence_index": 6, "correct_answer": "緑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "緑の葉をきれいだ。", "explanation": "助詞の混同：「きれいだ」の主語は「が」。"}, {"text": "緑い葉がきれいだ。", "explanation": "品詞の誤り：「緑」は名詞で「い」は付かない。「緑の葉」とする。"}, {"text": "緑の葉がきれいだった明日。", "explanation": "アスペクトの誤り：「明日」に過去形は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36831, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "信号が緑で変わった。", "corrected_sentence": "信号が緑に変わった。", "error_description": "助詞の混同：変化の結果は「に」で表す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36831, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「守る」の目的語を表す。"}, {"text": "で", "is_correct": false, "explanation": "手段を表し、守る対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、ここでは非文。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、「守る」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「守る」の目的語を表す。", "で": "手段を表し、守る対象を示せない。", "へ": "方向を表し、ここでは非文。", "に": "着点を表し、「守る」の目的語にならない。"}, "error_tags": {"で": "instrument", "へ": "direction", "に": "location_vs_target"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37471, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "参加", "is_correct": true, "explanation": "正解：さんか。"}, {"text": "担架", "is_correct": false, "explanation": "たんか。最初の「さ」が「た」に変わる一モーラ差。"}, {"text": "珊瑚", "is_correct": false, "explanation": "さんご。「か」が「ご」に変わる一モーラ差。"}, {"text": "秋刀魚", "is_correct": false, "explanation": "さんま。「か」が「ま」に変わる一モーラ差。"}, {"text": "作家", "is_correct": false, "explanation": "さっか。「ん」が促音「っ」に変わる。"}], "explanations": {"参加": "正解：さんか。", "担架": "たんか。最初の「さ」が「た」に変わる一モーラ差。", "珊瑚": "さんご。「か」が「ご」に変わる一モーラ差。", "秋刀魚": "さんま。「か」が「ま」に変わる一モーラ差。", "作家": "さっか。「ん」が促音「っ」に変わる。"}, "sentence_index": null, "correct_answer": "参加"}, "level_3": {"options": [{"text": "参加", "is_correct": true, "explanation": "住民が活動に加わることを表す。"}, {"text": "欠席", "is_correct": false, "explanation": "意味：加わらないことで、創出と矛盾する。"}, {"text": "睡眠", "is_correct": false, "explanation": "意味：眠ることで、ガーデン作りと無関係。"}, {"text": "誕生", "is_correct": false, "explanation": "連語：「主体的な誕生」とは言わない。"}], "explanations": {"参加": "住民が活動に加わることを表す。", "欠席": "意味：加わらないことで、創出と矛盾する。", "睡眠": "意味：眠ることで、ガーデン作りと無関係。", "誕生": "連語：「主体的な誕生」とは言わない。"}, "sentence_index": 0, "correct_answer": "参加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "参加が自由ます。", "explanation": "活用の誤り：名詞の後は「です」。"}, {"text": "参加を自由です。", "explanation": "助詞の混同：主題は「は」で表す。"}, {"text": "自由参加はです。", "explanation": "語順の誤り：主題—解説の構造が壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
