INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39285, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主体", "is_correct": true, "explanation": "正解：しゅたい。"}, {"text": "主題", "is_correct": false, "explanation": "しゅだい。「た」と「だ」の清濁の違い。"}, {"text": "醜態", "is_correct": false, "explanation": "しゅうたい。「しゅ」が長音「しゅう」になる。"}, {"text": "所帯", "is_correct": false, "explanation": "しょたい。「しゅ」が「しょ」に変わる一モーラ差。"}, {"text": "死体", "is_correct": false, "explanation": "したい。「しゅ」が「し」に変わる一モーラ差。"}], "explanations": {"主体": "正解：しゅたい。", "主題": "しゅだい。「た」と「だ」の清濁の違い。", "醜態": "しゅうたい。「しゅ」が長音「しゅう」になる。", "所帯": "しょたい。「しゅ」が「しょ」に変わる一モーラ差。", "死体": "したい。「しゅ」が「し」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "主体"}, "level_3": {"options": [{"text": "主体", "is_correct": true, "explanation": "住民が自ら中心となる参加を表す。"}, {"text": "海洋", "is_correct": false, "explanation": "意味：海に関する語で、住民の参加の様子に合わない。"}, {"text": "金属", "is_correct": false, "explanation": "意味：物質を表し、人の参加に使えない。"}, {"text": "液体", "is_correct": false, "explanation": "連語：「液体的な参加」とは言わない。"}], "explanations": {"主体": "住民が自ら中心となる参加を表す。", "海洋": "意味：海に関する語で、住民の参加の様子に合わない。", "金属": "意味：物質を表し、人の参加に使えない。", "液体": "連語：「液体的な参加」とは言わない。"}, "sentence_index": 0, "correct_answer": "主体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この活動の主体を生徒だ。", "explanation": "助詞の混同：主題は「は」で表す。"}, {"text": "この活動の主体的は生徒だ。", "explanation": "派生の誤り：「主体的」は形容動詞で、主題の名詞として使えない。"}, {"text": "生徒だ主体はこの活動の。", "explanation": "語順の誤り：主題—解説の構造が壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = E