INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35109, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しいな靴を買ってもらった。", "corrected_sentence": "新しい靴を買ってもらった。", "error_description": "い形容詞「新しい」は「な」を付けずに名詞を直接修飾する。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "新しい", "is_correct": true, "explanation": "正解。名詞「知識」を修飾する連体形。"}, {"text": "新しく", "is_correct": false, "explanation": "連用形で、名詞の前には置けない。"}, {"text": "新しかった", "is_correct": false, "explanation": "過去形で、一般的な必要性を述べる文脈に合わない。"}, {"text": "新しければ", "is_correct": false, "explanation": "仮定形で、名詞を修飾できない。"}], "correct_form": "新しい", "base_form": "新しい", "form_label": "連体形", "sentence_index": 1, "explanations": {"新しい": "正解。名詞「知識」を修飾する連体形。", "新しく": "連用形で、名詞の前には置けない。", "新しかった": "過去形で、一般的な必要性を述べる文脈に合わない。", "新しければ": "仮定形で、名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35109, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "古い", "is_correct": true, "explanation": "正解。「新しい」の反対語。"}, {"text": "広い", "is_correct": false, "explanation": "大きさの語で反対語ではない。"}, {"text": "高い", "is_correct": false, "explanation": "高さ・値段の語で反対語ではない。"}, {"text": "明るい", "is_correct": false, "explanation": "光の語で反対語ではない。"}], "correct_answer": "古い", "explanations": {"古い": "正解。「新しい」の反対語。", "広い": "大きさの語で反対語ではない。", "高い": "高さ・値段の語で反対語ではない。", "明るい": "光の語で反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35109, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "新しい", "is_correct": true, "explanation": "正解。「あたらしい」。"}, {"text": "煩わしい", "is_correct": false, "explanation": "「わずらわしい」。拍数・音が近いが別の語。"}, {"text": "いやらしい", "is_correct": false, "explanation": "「いやらしい」。前の二拍が異なり、「らしい」が共通。"}, {"text": "温かい", "is_correct": false, "explanation": "「あたたかい」。「あた」が共通で後半が異なる。"}], "explanations": {"新しい": "正解。「あたらしい」。", "煩わしい": "「わずらわしい」。拍数・音が近いが別の語。", "いやらしい": "「いやらしい」。前の二拍が異なり、「らしい」が共通。", "温かい": "「あたたかい」。「あた」が共通で後半が異なる。"}, "sentence_index": null, "correct_answer": "新しい"}, "level_3": {"options": [{"text": "新しい", "is_correct": true, "explanation": "正解。始まったばかりのクラスを表す。"}, {"text": "すっぱい", "is_correct": false, "explanation": "意味：味の語で「クラス」とは結びつかない。"}, {"text": "おいしい", "is_correct": false, "explanation": "連語：味の語で「クラス」とは結びつかない。"}, {"text": "重い", "is_correct": false, "explanation": "意味：重さはクラスの性質にならない。"}], "explanations": {"新しい": "正解。始まったばかりのクラスを表す。", "すっぱい": "意味：味の語で「クラス」とは結びつかない。", "おいしい": "連語：味の語で「クラス」とは結びつかない。", "重い": "意味：重さはクラスの性質にならない。"}, "sentence_index": 6, "correct_answer": "新しい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の家はまだ新しいだった。", "explanation": "活用の誤り：い形容詞の過去は「新しかった」で、「だった」は付かない。"}, {"text": "彼の家をまだ新しかった。", "explanation": "助詞の誤り：形容詞述語の主語は「は／が」で示す。"}, {"text": "まだ彼の新しかった家はです。", "explanation": "語順の誤り：主題—解説の構造が崩れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35109, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この本は新しいて、きれいだ。", "corrected_sentence": "この本は新しくて、きれいだ。", "error_description": "い形容詞のて形は「新しくて」で、「新しいて」とは言わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "新しく", "is_correct": true, "explanation": "正解。「て」に続く連用形。"}, {"text": "新しい", "is_correct": false, "explanation": "終止・連体形で「て」には続かない。"}, {"text": "新しかっ", "is_correct": false, "explanation": "過去の語幹で「た」に続く形。"}, {"text": "新しけれ", "is_correct": false, "explanation": "仮定の形で「ば」に続く。"}], "correct_form": "新しく", "base_form": "新しい", "form_label": "連用形（て形）", "sentence_index": 7, "explanations": {"新しく": "正解。「て」に続く連用形。", "新しい": "終止・連体形で「て」には続かない。", "新しかっ": "過去の語幹で「た」に続く形。", "新しけれ": "仮定の形で「ば」に続く。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35109, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "古かった", "is_correct": true, "explanation": "正解。「新しかった」の反対。"}, {"text": "小さかった", "is_correct": false, "explanation": "大きさの語で反対ではない。"}, {"text": "安かった", "is_correct": false, "explanation": "値段の語で反対ではない。"}, {"text": "暗かった", "is_correct": false, "explanation": "明るさの語で反対ではない。"}], "correct_answer": "古かった", "explanations": {"古かった": "正解。「新しかった」の反対。", "小さかった": "大きさの語で反対ではない。", "安かった": "値段の語で反対ではない。", "暗かった": "明るさの語で反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39687, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "ロボット", "is_correct": true, "explanation": "正解。「ろぼっと」。"}, {"text": "ロケット", "is_correct": false, "explanation": "「ろけっと」。二拍目「ぼ」が「け」に変わる一拍差。"}, {"text": "ロゼット", "is_correct": false, "explanation": "「ろぜっと」。二拍目「ぼ」が「ぜ」に変わる一拍差。"}, {"text": "ポケット", "is_correct": false, "explanation": "「ぽけっと」。一・二拍目が異なる。"}], "explanations": {"ロボット": "正解。「ろぼっと」。", "ロケット": "「ろけっと」。二拍目「ぼ」が「け」に変わる一拍差。", "ロゼット": "「ろぜっと」。二拍目「ぼ」が「ぜ」に変わる一拍差。", "ポケット": "「ぽけっと」。一・二拍目が異なる。"}, "sentence_index": null, "correct_answer": "ロボット"}, "level_3": {"options": [{"text": "ロボット", "is_correct": true, "explanation": "正解。家で手伝いをする機械。"}, {"text": "テレビ", "is_correct": false, "explanation": "意味：テレビは手伝いをしない。"}, {"text": "リンゴ", "is_correct": false, "explanation": "意味：果物は手伝いができない。"}, {"text": "ポスト", "is_correct": false, "explanation": "意味：郵便受けは家で動いて手伝わない。"}], "explanations": {"ロボット": "正解。家で手伝いをする機械。", "テレビ": "意味：テレビは手伝いをしない。", "リンゴ": "意味：果物は手伝いができない。", "ポスト": "意味：郵便受けは家で動いて手伝わない。"}, "sentence_index": 0, "correct_answer": "ロボット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟は一冊のロボットが大好きだ。", "explanation": "助数詞の誤り：ロボットは「一台」で数える。"}, {"text": "弟をロボットが大好きだ。", "explanation": "助詞の誤り：好きな人は「は」で示す。「弟はロボットが大好きだ」。"}, {"text": "弟はロボットを大好きだ。", "explanation": "助詞の誤り：「好きだ」の対象は「が」で示す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39687, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ロボットを一枚買ってもらった。", "corrected_sentence": "ロボットを一台買ってもらった。", "error_description": "ロボットを数える助数詞は「台」で、「枚」ではない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39687, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「ロボット製作の本質」で名詞をつなぐ。"}, {"text": "が", "is_correct": false, "explanation": "「本質」を修飾できない。"}, {"text": "を", "is_correct": false, "explanation": "名詞と名詞をつなげない。"}, {"text": "に", "is_correct": false, "explanation": "名詞を修飾する働きがない。"}], "correct_answer": "の", "explanations": {"の": "正解。「ロボット製作の本質」で名詞をつなぐ。", "が": "「本質」を修飾できない。", "を": "名詞と名詞をつなげない。", "に": "名詞を修飾する働きがない。"}, "error_tags": {"が": "subject_marker", "を": "object_marker", "に": "location_target"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39687, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "ロボット", "is_correct": true, "explanation": "正解。「ろぼっと」。"}, {"text": "ロビー", "is_correct": false, "explanation": "「ろびー」。「ろ」が共通で後半が異なる。"}, {"text": "ロデオ", "is_correct": false, "explanation": "「ろでお」。「ろ」が共通で後半が異なる。"}, {"text": "ローマ", "is_correct": false, "explanation": "「ろーま」。「ろ」が共通で後半が異なる。"}], "explanations": {"ロボット": "正解。「ろぼっと」。", "ロビー": "「ろびー」。「ろ」が共通で後半が異なる。", "ロデオ": "「ろでお」。「ろ」が共通で後半が異なる。", "ローマ": "「ろーま」。「ろ」が共通で後半が異なる。"}, "sentence_index": null, "correct_answer": "ロボット"}, "level_3": {"options": [{"text": "ロボット", "is_correct": true, "explanation": "正解。作ることができる機械。"}, {"text": "天気", "is_correct": false, "explanation": "意味：天気は作るものではない。"}, {"text": "友情", "is_correct": false, "explanation": "意味：抽象名詞で、工作の対象にならない。"}, {"text": "空", "is_correct": false, "explanation": "意味：空は作れない。"}], "explanations": {"ロボット": "正解。作ることができる機械。", "天気": "意味：天気は作るものではない。", "友情": "意味：抽象名詞で、工作の対象にならない。", "空": "意味：空は作れない。"}, "sentence_index": 6, "correct_answer": "ロボット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "未来の町にはロボットに多い。", "explanation": "助詞の誤り：多いものは「が」で示す。"}, {"text": "未来の町にはロボットを多い。", "explanation": "助詞の誤り：存在・量の主体は「が」で示す。"}, {"text": "ロボットが一人の町に多い。", "explanation": "助数詞の誤り：ロボットは「台」で数え、「人」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39687, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "掃除はロボットを任せている。", "corrected_sentence": "掃除はロボットに任せている。", "error_description": "任せる相手は「に」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
