INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36235, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "友達", "is_correct": true, "explanation": "正解。「ともだち」。"}, {"text": "友釣り", "is_correct": false, "explanation": "「ともづり」。後半が異なる。"}, {"text": "共倒れ", "is_correct": false, "explanation": "「ともだおれ」。「ともだ」が共通で後半が異なる。"}, {"text": "共働き", "is_correct": false, "explanation": "「ともばたらき」。「とも」が共通で後半が異なる。"}], "explanations": {"友達": "正解。「ともだち」。", "友釣り": "「ともづり」。後半が異なる。", "共倒れ": "「ともだおれ」。「ともだ」が共通で後半が異なる。", "共働き": "「ともばたらき」。「とも」が共通で後半が異なる。"}, "sentence_index": null, "correct_answer": "友達"}, "level_3": {"options": [{"text": "友達", "is_correct": true, "explanation": "正解。手紙を送る親しい人。"}, {"text": "机", "is_correct": false, "explanation": "意味：机には手紙を書かない。"}, {"text": "雨", "is_correct": false, "explanation": "意味：天気は手紙の相手にならない。"}, {"text": "台所", "is_correct": false, "explanation": "意味：場所は手紙の相手にならない。"}], "explanations": {"友達": "正解。手紙を送る親しい人。", "机": "意味：机には手紙を書かない。", "雨": "意味：天気は手紙の相手にならない。", "台所": "意味：場所は手紙の相手にならない。"}, "sentence_index": 6, "correct_answer": "友達"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "困った時は友達を相談する。", "explanation": "助詞の誤り：相談の相手は「に」で示す。"}, {"text": "困った時は一匹の友達に相談する。", "explanation": "助数詞の誤り：人に「匹」は使わない。"}, {"text": "困った時は三台の友達に相談する。", "explanation": "助数詞の誤り：人は「人」で数え、「台」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
