INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51688, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "無垢", "is_correct": true, "explanation": "正解。「むく」。"}, {"text": "虫", "is_correct": false, "explanation": "「むし」。二拍目「く」が「し」に変わる。"}, {"text": "胸", "is_correct": false, "explanation": "「むね」。二拍目「く」が「ね」に変わる。"}, {"text": "向き", "is_correct": false, "explanation": "「むき」。二拍目「く」が「き」に変わる。"}, {"text": "服", "is_correct": false, "explanation": "「ふく」。一拍目「む」が「ふ」に変わる。"}], "explanations": {"無垢": "正解。「むく」。", "虫": "「むし」。二拍目「く」が「し」に変わる。", "胸": "「むね」。二拍目「く」が「ね」に変わる。", "向き": "「むき」。二拍目「く」が「き」に変わる。", "服": "「ふく」。一拍目「む」が「ふ」に変わる。"}, "sentence_index": null, "correct_answer": "無垢"}, "level_3": {"options": [{"text": "無垢", "is_correct": true, "explanation": "正解。まじりけのない一枚板の材木。"}, {"text": "雪", "is_correct": false, "explanation": "意味：雪は家具の材料にならない。"}, {"text": "紙", "is_correct": false, "explanation": "意味：紙で家具は作れない。"}, {"text": "氷", "is_correct": false, "explanation": "意味：家具の材料にならない。"}], "explanations": {"無垢": "正解。まじりけのない一枚板の材木。", "雪": "意味：雪は家具の材料にならない。", "紙": "意味：紙で家具は作れない。", "氷": "意味：家具の材料にならない。"}, "sentence_index": 0, "correct_answer": "無垢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このテーブルは無垢を木でできている。", "explanation": "助詞の誤り：名詞を修飾するには「の」を使う。"}, {"text": "このテーブルは一匹の無垢の木でできている。", "explanation": "助数詞の誤り：木や家具に「匹」は使わない。"}, {"text": "このテーブルは無垢に木でできている。", "explanation": "助詞の誤り：名詞を修飾するには「の」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
