INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37775, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "集合", "is_correct": true, "explanation": "正しい表記。"}, {"text": "縫合", "is_correct": false, "explanation": "ほうごう。第一モーラ「しゅ」が「ほ」になる一モーラ差。"}, {"text": "収容", "is_correct": false, "explanation": "しゅうよう。「ご」が「よ」になる一モーラ差。"}, {"text": "就航", "is_correct": false, "explanation": "しゅうこう。「ご」と「こ」の清濁の違い。"}, {"text": "酒豪", "is_correct": false, "explanation": "しゅごう。長音の有無の違い。"}], "explanations": {"集合": "正しい表記。", "縫合": "ほうごう。第一モーラ「しゅ」が「ほ」になる一モーラ差。", "収容": "しゅうよう。「ご」が「よ」になる一モーラ差。", "就航": "しゅうこう。「ご」と「こ」の清濁の違い。", "酒豪": "しゅごう。長音の有無の違い。"}, "sentence_index": null, "correct_answer": "集合"}, "level_3": {"options": [{"text": "集合", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "名前", "is_correct": false, "explanation": "意味：森は木の名前ではない。"}, {"text": "速さ", "is_correct": false, "explanation": "意味：速さは森を説明しない。"}, {"text": "味", "is_correct": false, "explanation": "連語：「木の味だと言える」は森の説明として不自然。"}], "explanations": {"集合": "文脈に合う正しい語。", "名前": "意味：森は木の名前ではない。", "速さ": "意味：速さは森を説明しない。", "味": "連語：「木の味だと言える」は森の説明として不自然。"}, "sentence_index": 6, "correct_answer": "集合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "集合としての力を大きい。", "explanation": "助詞の混同：形容詞の主語に「を」は使えない。"}, {"text": "集合としての力は大きかっている。", "explanation": "活用の誤り：形容詞に「ている」は付かない。"}, {"text": "二枚の集合としての力は大きい。", "explanation": "助数詞の誤り：力や集まりを「枚」では数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0835a5b8-0c2b-475e-a81f-6b8c4b182eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
