INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51908, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "この位置に正しく入る助詞。"}, {"text": "を", "is_correct": false, "explanation": "自動詞「絶える」は目的語をとらない。"}, {"text": "に", "is_correct": false, "explanation": "「客足に絶える」は非文。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表し不自然。"}], "correct_answer": "が", "explanations": {"が": "この位置に正しく入る助詞。", "を": "自動詞「絶える」は目的語をとらない。", "に": "「客足に絶える」は非文。", "で": "手段・場所を表し不自然。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "続く", "is_correct": true, "explanation": "続いて途切れないことで「絶える」の反対。"}, {"text": "尽きる", "is_correct": false, "explanation": "なくなる意味で似ている。"}, {"text": "止む", "is_correct": false, "explanation": "終わる意味で似ている。"}, {"text": "座る", "is_correct": false, "explanation": "関係のない動作。"}], "correct_answer": "続く", "explanations": {"続く": "続いて途切れないことで「絶える」の反対。", "尽きる": "なくなる意味で似ている。", "止む": "終わる意味で似ている。", "座る": "関係のない動作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0835a5b8-0c2b-475e-a81f-6b8c4b182eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
