INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51708, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "建築", "is_correct": true, "explanation": "正しい表記。"}, {"text": "減築", "is_correct": false, "explanation": "げんちく。「け」が「げ」になる清濁の違い。"}, {"text": "献策", "is_correct": false, "explanation": "けんさく。「ち」が「さ」になる一モーラ差。"}, {"text": "見地", "is_correct": false, "explanation": "けんち。最後の「く」がない一モーラ差。"}], "explanations": {"建築": "正しい表記。", "減築": "げんちく。「け」が「げ」になる清濁の違い。", "献策": "けんさく。「ち」が「さ」になる一モーラ差。", "見地": "けんち。最後の「く」がない一モーラ差。"}, "sentence_index": null, "correct_answer": "建築"}, "level_3": {"options": [{"text": "建築", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "名前", "is_correct": false, "explanation": "意味：名前は「始まる」ものではない。"}, {"text": "色", "is_correct": false, "explanation": "意味：駅の色が始まるとは言えない。"}, {"text": "匂い", "is_correct": false, "explanation": "連語：「匂いが始まった」は不自然。"}], "explanations": {"建築": "文脈に合う正しい語。", "名前": "意味：名前は「始まる」ものではない。", "色": "意味：駅の色が始まるとは言えない。", "匂い": "連語：「匂いが始まった」は不自然。"}, "sentence_index": 6, "correct_answer": "建築"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "建築には長い時間をかかる。", "explanation": "助詞の混同：「かかる」の主語は「が」。"}, {"text": "建築をは長い時間がかかる。", "explanation": "助詞の誤り：「建築」には「を」ではなく「に（は）」が付く。"}, {"text": "建築には三冊の長い時間がかかる。", "explanation": "助数詞の誤り：時間は「冊」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0835a5b8-0c2b-475e-a81f-6b8c4b182eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51708, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は建築を興味がある。", "corrected_sentence": "彼女は建築に興味がある。", "error_description": "興味の対象は「に」で表す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0835a5b8-0c2b-475e-a81f-6b8c4b182eae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
