INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35661, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "目的を持って体や頭を使って働くこと。特にお金を得るための仕事。", "primary_collocate": null, "pronunciation": "ろうどう", "ipa": "ɾoːdoː", "syllable_count": 4, "sentences": [{"text": "一方で、農村経済全体を見ると、労働需要の質が変化するという社会経済的影響も無視できません。", "target_word": "労働", "complexity_tier": "T3", "furigana": "ろうどう", "sentence_source": "mined"}, {"text": "従来の肉体労働は減少しますが、機械を操作する専門知識を持つ人材の確保が、新たな課題として浮上しているのです。", "target_word": "労働", "complexity_tier": "T3", "furigana": "ろうどう", "sentence_source": "mined"}, {"text": "最初の一年は、美しい田園風景とは裏腹に、泥にまみれた過酷な肉体労働の連続でした。", "target_word": "労働", "complexity_tier": "T3", "furigana": "ろうどう", "sentence_source": "mined"}, {"text": "長い時間の労働はつらい。", "target_word": "労働", "complexity_tier": "T3", "furigana": "ろうどう", "sentence_source": "generated"}, {"text": "父は毎日工場で労働している。", "target_word": "労働", "complexity_tier": "T3", "furigana": "ろうどう", "sentence_source": "generated"}, {"text": "労働の時間が短くなった。", "target_word": "労働", "complexity_tier": "T3", "furigana": "ろうどう", "sentence_source": "generated"}, {"text": "労働にはきちんとお金が必要だ。", "target_word": "労働", "complexity_tier": "T3", "furigana": "ろうどう", "sentence_source": "generated"}, {"text": "ロボットが人の労働を助ける。", "target_word": "労働", "complexity_tier": "T3", "furigana": "ろうどう", "sentence_source": "generated"}, {"text": "夏の外での労働は大変だ。", "target_word": "労働", "complexity_tier": "T3", "furigana": "ろうどう", "sentence_source": "generated"}, {"text": "子どもの労働は禁止されている。", "target_word": "労働", "complexity_tier": "T3", "furigana": "ろうどう", "sentence_source": "generated"}], "morphological_forms": [{"form": "労働者", "label": "派生"}, {"form": "労働する", "label": "活用"}, {"form": "労働時間", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 収入を得るために働くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45a2ade8-13aa-47db-9282-c68f3148d36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37723, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある目的のために、道具や方法などを使う。", "primary_collocate": null, "pronunciation": "もちいる", "ipa": "motɕiiɾɯ", "syllable_count": 4, "sentences": [{"text": "センサー等を用いた技術導入は、収量の安定化により収益性を向上させます。", "target_word": "用い", "complexity_tier": "T3", "furigana": "もち", "sentence_source": "mined"}, {"text": "天然酵母を用いた製パンは、職人の緻密な管理が不可欠な工程です。", "target_word": "用い", "complexity_tier": "T3", "furigana": "もち", "sentence_source": "mined"}, {"text": "この実験では水を用いる。", "target_word": "用いる", "complexity_tier": "T3", "furigana": "もちいる", "sentence_source": "generated"}, {"text": "図を用いて説明した。", "target_word": "用い", "complexity_tier": "T3", "furigana": "もち", "sentence_source": "generated"}, {"text": "新しい方法を用いている。", "target_word": "用い", "complexity_tier": "T3", "furigana": "もち", "sentence_source": "generated"}, {"text": "古い道具は今は用いない。", "target_word": "用い", "complexity_tier": "T3", "furigana": "もち", "sentence_source": "generated"}, {"text": "この薬は昔から用いられる。", "target_word": "用い", "complexity_tier": "T3", "furigana": "もち", "sentence_source": "generated"}, {"text": "辞書を用いて調べてみた。", "target_word": "用い", "complexity_tier": "T3", "furigana": "もち", "sentence_source": "generated"}, {"text": "木を用いた家に住みたい。", "target_word": "用い", "complexity_tier": "T3", "furigana": "もち", "sentence_source": "generated"}, {"text": "彼は機械を上手に用いる。", "target_word": "用いる", "complexity_tier": "T3", "furigana": "もちいる", "sentence_source": "generated"}], "morphological_forms": [{"form": "用いた", "label": "活用"}, {"form": "用いて", "label": "活用"}, {"form": "用いない", "label": "活用"}, {"form": "用いられる", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 目的のために道具や方法を使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45a2ade8-13aa-47db-9282-c68f3148d36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51586, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "収量", "is_correct": true, "explanation": "正解：「収量」（しゅうりょう）。"}, {"text": "少量", "is_correct": false, "explanation": "「少量」（しょうりょう）：「しゅ」が「しょ」になった語で、量が少ないこと。"}, {"text": "重量", "is_correct": false, "explanation": "「重量」（じゅうりょう）：最初が濁音になった語で、重さのこと。"}, {"text": "狩猟", "is_correct": false, "explanation": "「狩猟」（しゅりょう）：「しゅう」が短くなった語で、動物をとること。"}, {"text": "収容", "is_correct": false, "explanation": "「収容」（しゅうよう）：「りょ」が「よ」になった語で、人や物を入れること。"}], "explanations": {"収量": "正解：「収量」（しゅうりょう）。", "少量": "「少量」（しょうりょう）：「しゅ」が「しょ」になった語で、量が少ないこと。", "重量": "「重量」（じゅうりょう）：最初が濁音になった語で、重さのこと。", "狩猟": "「狩猟」（しゅりょう）：「しゅう」が短くなった語で、動物をとること。", "収容": "「収容」（しゅうよう）：「りょ」が「よ」になった語で、人や物を入れること。"}, "sentence_index": null, "correct_answer": "収量"}, "level_3": {"options": [{"text": "収量", "is_correct": true, "explanation": "「収量」が文の意味に合う。"}, {"text": "友情", "is_correct": false, "explanation": "意味：友だちの気持ちは技術で安定させて収益にするものではない。"}, {"text": "年齢", "is_correct": false, "explanation": "意味：年齢は技術導入で安定化するものではない。"}, {"text": "勇気", "is_correct": false, "explanation": "連語：「勇気の安定化」は不自然な結びつきだ。"}], "explanations": {"収量": "「収量」が文の意味に合う。", "友情": "意味：友だちの気持ちは技術で安定させて収益にするものではない。", "年齢": "意味：年齢は技術導入で安定化するものではない。", "勇気": "連語：「勇気の安定化」は不自然な結びつきだ。"}, "sentence_index": 0, "correct_answer": "収量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が少なくて収量で減っている。", "explanation": "助詞の混同：「収量で」では何が減るのか示せない。「が」が正しい。"}, {"text": "収量が雨が少なくて減っているに。", "explanation": "語順・係り受けの誤り：文末に助詞「に」が残り、文が成立しない。"}, {"text": "収量を二冊とれた。", "explanation": "助数詞の誤り：収量は「冊」で数えない。量は「トン」などで表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4397dffc-9090-43ce-b166-88579989dd89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
