INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51588, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "無視", "is_correct": true, "explanation": "正解：「無視」（むし）。"}, {"text": "無理", "is_correct": false, "explanation": "「無理」（むり）：「し」が「り」になった語。できそうにないこと。"}, {"text": "牛", "is_correct": false, "explanation": "「牛」（うし）：「む」が「う」になった語。動物の牛。"}, {"text": "無地", "is_correct": false, "explanation": "「無地」（むじ）：「し」が濁った語。模様がないこと。"}, {"text": "武士", "is_correct": false, "explanation": "「武士」（ぶし）：「む」が「ぶ」になった語。昔のさむらい。"}], "explanations": {"無視": "正解：「無視」（むし）。", "無理": "「無理」（むり）：「し」が「り」になった語。できそうにないこと。", "牛": "「牛」（うし）：「む」が「う」になった語。動物の牛。", "無地": "「無地」（むじ）：「し」が濁った語。模様がないこと。", "武士": "「武士」（ぶし）：「む」が「ぶ」になった語。昔のさむらい。"}, "sentence_index": null, "correct_answer": "無視"}, "level_3": {"options": [{"text": "無視", "is_correct": true, "explanation": "「無視」が文の意味に合う。"}, {"text": "料理", "is_correct": false, "explanation": "意味：「影響も料理できない」は意味が通らない。"}, {"text": "散歩", "is_correct": false, "explanation": "連語：「影響を散歩する」という結びつきはない。"}, {"text": "入学", "is_correct": false, "explanation": "項構造：「入学」は影響を目的語にとれない。"}], "explanations": {"無視": "「無視」が文の意味に合う。", "料理": "意味：「影響も料理できない」は意味が通らない。", "散歩": "連語：「影響を散歩する」という結びつきはない。", "入学": "項構造：「入学」は影響を目的語にとれない。"}, "sentence_index": 0, "correct_answer": "無視"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "信号が無視してはいけない。", "explanation": "助詞の混同：無視する対象は「を」で示す。"}, {"text": "信号で無視してはいけない。", "explanation": "助詞の混同：無視する対象は「で」ではなく「を」で示す。"}, {"text": "信号を無視しってはいけない。", "explanation": "活用の誤り：「無視する」のて形は「無視して」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4397dffc-9090-43ce-b166-88579989dd89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validati