INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35515, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "農業", "is_correct": true, "explanation": "正解：「農業」（のうぎょう）。"}, {"text": "工業", "is_correct": false, "explanation": "「工業」（こうぎょう）：「の」が「こ」になった語。物を作る産業。"}, {"text": "農協", "is_correct": false, "explanation": "「農協」（のうきょう）：「ぎょ」が清音の「きょ」になった語。農業協同組合。"}, {"text": "農場", "is_correct": false, "explanation": "「農場」（のうじょう）：「ぎょ」が「じょ」になった語。作物を育てる場所。"}, {"text": "商業", "is_correct": false, "explanation": "「商業」（しょうぎょう）：「の」が「しょ」になった語。売り買いの仕事。"}], "explanations": {"農業": "正解：「農業」（のうぎょう）。", "工業": "「工業」（こうぎょう）：「の」が「こ」になった語。物を作る産業。", "農協": "「農協」（のうきょう）：「ぎょ」が清音の「きょ」になった語。農業協同組合。", "農場": "「農場」（のうじょう）：「ぎょ」が「じょ」になった語。作物を育てる場所。", "商業": "「商業」（しょうぎょう）：「の」が「しょ」になった語。売り買いの仕事。"}, "sentence_index": null, "correct_answer": "農業"}, "level_3": {"options": [{"text": "農業", "is_correct": true, "explanation": "「農業」が文の意味に合う。"}, {"text": "音楽", "is_correct": false, "explanation": "意味：音楽の導入が農家の経営に可能性をもたらすのは文脈に合わない。"}, {"text": "料理", "is_correct": false, "explanation": "意味：「精密料理」は農家の経営と結びつかない。"}, {"text": "睡眠", "is_correct": false, "explanation": "連語：「精密睡眠の導入」は不自然な結びつきだ。"}], "explanations": {"農業": "「農業」が文の意味に合う。", "音楽": "意味：音楽の導入が農家の経営に可能性をもたらすのは文脈に合わない。", "料理": "意味：「精密料理」は農家の経営と結びつかない。", "睡眠": "連語：「精密睡眠の導入」は不自然な結びつきだ。"}, "sentence_index": 0, "correct_answer": "農業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この村を農業がさかんだ。", "explanation": "助詞の混同：主題は「を」ではなく「は」で示す。"}, {"text": "この村は農業をさかんだ。", "explanation": "助詞の混同：「さかんだ」の主語は「が」で示す。"}, {"text": "この村は農業がさかんな。", "explanation": "活用の誤り：文末で「さかんな」は使えず「さかんだ」になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4397dffc-9090-43ce-b166-88579989dd89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version,