INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35515, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "農業", "is_correct": true, "explanation": "正解：「農業」（のうぎょう）。"}, {"text": "漁業", "is_correct": false, "explanation": "「漁業」（ぎょぎょう）：最初が「ぎょ」の語。魚をとる産業。"}, {"text": "林業", "is_correct": false, "explanation": "「林業」（りんぎょう）：最初が「りん」の語。森林を育てる産業。"}, {"text": "農道", "is_correct": false, "explanation": "「農道」（のうどう）：後半が「どう」の語。畑の中の道。"}, {"text": "農園", "is_correct": false, "explanation": "「農園」（のうえん）：後半が「えん」の語。作物を育てる園。"}], "explanations": {"農業": "正解：「農業」（のうぎょう）。", "漁業": "「漁業」（ぎょぎょう）：最初が「ぎょ」の語。魚をとる産業。", "林業": "「林業」（りんぎょう）：最初が「りん」の語。森林を育てる産業。", "農道": "「農道」（のうどう）：後半が「どう」の語。畑の中の道。", "農園": "「農園」（のうえん）：後半が「えん」の語。作物を育てる園。"}, "sentence_index": null, "correct_answer": "農業"}, "level_3": {"options": [{"text": "農業", "is_correct": true, "explanation": "「農業」が文の意味に合う。"}, {"text": "昼寝", "is_correct": false, "explanation": "意味：昼寝で働く若者という言い方は成り立たない。"}, {"text": "散歩", "is_correct": false, "explanation": "意味：散歩は働く場所・分野ではない。"}, {"text": "宿題", "is_correct": false, "explanation": "語域：宿題は学校の語で、働く分野を表さない。"}], "explanations": {"農業": "「農業」が文の意味に合う。", "昼寝": "意味：昼寝で働く若者という言い方は成り立たない。", "散歩": "意味：散歩は働く場所・分野ではない。", "宿題": "語域：宿題は学校の語で、働く分野を表さない。"}, "sentence_index": 6, "correct_answer": "農業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "農業の機械を新しくなった。", "explanation": "助詞の混同：自動詞「なる」の主語は「が」で示す。"}, {"text": "農業の機械が三人新しくなった。", "explanation": "助数詞の誤り：機械は「人」ではなく「台」で数える。"}, {"text": "農業の機械が新しいなった。", "explanation": "活用の誤り：「なる」に続くのは連用形「新しく」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4397dffc-9090-43ce-b166-88579989dd89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
