INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37723, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "用いる", "is_correct": true, "explanation": "正解：「用いる」（もちいる）。"}, {"text": "陥る", "is_correct": false, "explanation": "「陥る」（おちいる）：「も」が「お」になった語。悪い状態に落ちこむこと。"}, {"text": "持ち去る", "is_correct": false, "explanation": "「持ち去る」（もちさる）：「い」が「さ」になった語。持って行ってしまうこと。"}, {"text": "持ち寄る", "is_correct": false, "explanation": "「持ち寄る」（もちよる）：「い」が「よ」になった語。皆で物を持って集まること。"}, {"text": "持ち切る", "is_correct": false, "explanation": "「持ち切る」（もちきる）：「い」が「き」になった語。その話題ばかりが続くこと。"}], "explanations": {"用いる": "正解：「用いる」（もちいる）。", "陥る": "「陥る」（おちいる）：「も」が「お」になった語。悪い状態に落ちこむこと。", "持ち去る": "「持ち去る」（もちさる）：「い」が「さ」になった語。持って行ってしまうこと。", "持ち寄る": "「持ち寄る」（もちよる）：「い」が「よ」になった語。皆で物を持って集まること。", "持ち切る": "「持ち切る」（もちきる）：「い」が「き」になった語。その話題ばかりが続くこと。"}, "sentence_index": null, "correct_answer": "用いる"}, "level_3": {"options": [{"text": "用い", "is_correct": true, "explanation": "「用い」が文の意味に合う。"}, {"text": "眠っ", "is_correct": false, "explanation": "意味：センサーを眠った技術導入は意味が通らない。"}, {"text": "泳い", "is_correct": false, "explanation": "意味：「センサー等を泳いだ」は意味が通らない。"}, {"text": "笑っ", "is_correct": false, "explanation": "項構造：「センサーを笑った技術導入」は格の取り方が合わない。"}], "explanations": {"用い": "「用い」が文の意味に合う。", "眠っ": "意味：センサーを眠った技術導入は意味が通らない。", "泳い": "意味：「センサー等を泳いだ」は意味が通らない。", "笑っ": "項構造：「センサーを笑った技術導入」は格の取り方が合わない。"}, "sentence_index": 0, "correct_answer": "用い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "図が用いて説明した。", "explanation": "助詞の混同：使う道具は「を」で示す。"}, {"text": "図を用いるて説明した。", "explanation": "活用の誤り：「て」には連用形「用い」が付く。"}, {"text": "図を説明した用いて。", "explanation": "語順・係り受けの誤り：「用いて」が文末に来て文が成立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4397dffc-9090-43ce-b166-88579989dd89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37723, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この実験では水に用いる。", "corrected_sentence": "この実験では水を用いる。", "error_description": "助詞の混同：使う物は「に」ではなく「を」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "用い", "is_correct": true, "explanation": "「た」に続く連用形で、「用いた」になる。"}, {"text": "用いる", "is_correct": false, "explanation": "辞書形は「た」に直接続かない。"}, {"text": "用いれ", "is_correct": false, "explanation": "仮定形で「ば」に続く形。「た」には続かない。"}, {"text": "用いよ", "is_correct": false, "explanation": "命令形で、「た」に続かない。"}], "correct_form": "用い", "base_form": "用いる", "form_label": "活用", "sentence_index": 1, "explanations": {"用い": "「た」に続く連用形で、「用いた」になる。", "用いる": "辞書形は「た」に直接続かない。", "用いれ": "仮定形で「ば」に続く形。「た」には続かない。", "用いよ": "命令形で、「た」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4397dffc-9090-43ce-b166-88579989dd89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
