INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38095, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「向ける」の目的語「関心」を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」では他動詞「向けよう」の目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」は「関心で向けよう」となり非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は向ける物を示せない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「向ける」の目的語「関心」を示す。", "が": "主格の「が」では他動詞「向けよう」の目的語にならない。", "で": "手段の「で」は「関心で向けよう」となり非文。", "へ": "方向の「へ」は向ける物を示せない。"}, "error_tags": {"が": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "背ける", "is_correct": true, "explanation": "「ライトを向ける」の反対で、顔や目をそちらからそらすこと。"}, {"text": "当てる", "is_correct": false, "explanation": "光などを対象に届かせることで、反対ではない。"}, {"text": "集める", "is_correct": false, "explanation": "視線などを一か所に集めることで、反対ではない。"}, {"text": "傾ける", "is_correct": false, "explanation": "耳や気持ちを向けることで、むしろ近い意味。"}], "correct_answer": "背ける", "explanations": {"背ける": "「ライトを向ける」の反対で、顔や目をそちらからそらすこと。", "当てる": "光などを対象に届かせることで、反対ではない。", "集める": "視線などを一か所に集めることで、反対ではない。", "傾ける": "耳や気持ちを向けることで、むしろ近い意味。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35793, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "炭素", "is_correct": true, "explanation": "正解：読み上げられた語そのもの。"}, {"text": "単語", "is_correct": false, "explanation": "「たんご」と読む別の語。「そ」が「ご」に変わる一モーラ差。"}, {"text": "簡素", "is_correct": false, "explanation": "「かんそ」と読む別の語。語頭の「た」が「か」に変わる一モーラ差。"}, {"text": "たんす", "is_correct": false, "explanation": "「たんす」と読む別の語。「そ」が「す」に変わる一モーラ差。"}], "explanations": {"炭素": "正解：読み上げられた語そのもの。", "単語": "「たんご」と読む別の語。「そ」が「ご」に変わる一モーラ差。", "簡素": "「かんそ」と読む別の語。語頭の「た」が「か」に変わる一モーラ差。", "たんす": "「たんす」と読む別の語。「そ」が「す」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "炭素"}, "level_3": {"options": [{"text": "炭素", "is_correct": true, "explanation": "製造の過程で出てしまう炭素（二酸化炭素のもとになる元素）を表す。"}, {"text": "酸味", "is_correct": false, "explanation": "意味：味のことで、「発生をゼロ化」する対象にならない。"}, {"text": "木材", "is_correct": false, "explanation": "意味：材料で、「発生」とは結びつかない。"}, {"text": "金属", "is_correct": false, "explanation": "連語：「金属発生」は不自然。"}], "explanations": {"炭素": "製造の過程で出てしまう炭素（二酸化炭素のもとになる元素）を表す。", "酸味": "意味：味のことで、「発生をゼロ化」する対象にならない。", "木材": "意味：材料で、「発生」とは結びつかない。", "金属": "連語：「金属発生」は不自然。"}, "sentence_index": 0, "correct_answer": "炭素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ダイヤモンドは炭素をできている。", "explanation": "助詞の混同：材料は「で」で示し、「を」は使えない。"}, {"text": "ダイヤモンドは炭素にできている。", "explanation": "助詞の誤り：材料の「炭素」は「に」ではなく「で」で示す。"}, {"text": "ダイヤモンドは炭素なでできている。", "explanation": "助詞の誤り：名詞「炭素」のあとに「な」は入らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28af3b09-4b31-45de-a494-6b64872f7e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
