INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52448, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事が及ぶ範囲や分野。", "primary_collocate": null, "pronunciation": "りょういき", "ipa": "ɾʲoːiki", "syllable_count": 4, "sentences": [{"text": "再生可能エネルギーの導入加速にもかかわらず、製造プロセスの性質上、炭素発生をゼロ化し得ない領域において、CCUSは極めて重要な役割を担う。", "target_word": "領域", "complexity_tier": "T3", "furigana": "りょういき", "sentence_source": "mined"}, {"text": "凍てつく空気の中、ボタンを一つひとつ留める仕草には、未知の領域へ挑む戦士のような厳粛ささえ漂っていた。", "target_word": "領域", "complexity_tier": "T3", "furigana": "りょういき", "sentence_source": "mined"}, {"text": "彼は新しい領域に挑んでいる。", "target_word": "領域", "complexity_tier": "T3", "furigana": "かれ あたら りょういき いど", "sentence_source": "generated"}, {"text": "それは私の専門領域ではない。", "target_word": "領域", "complexity_tier": "T3", "furigana": "わたし せんもん りょういき", "sentence_source": "generated"}, {"text": "この問題は心理学の領域に入る。", "target_word": "領域", "complexity_tier": "T3", "furigana": "もんだい しんりがく りょういき はい", "sentence_source": "generated"}, {"text": "研究の領域が広がってきた。", "target_word": "領域", "complexity_tier": "T3", "furigana": "けんきゅう りょういき ひろ", "sentence_source": "generated"}, {"text": "未知の領域に足を踏み入れた。", "target_word": "領域", "complexity_tier": "T3", "furigana": "みち りょういき あし ふ い", "sentence_source": "generated"}, {"text": "この領域では経験が大切だ。", "target_word": "領域", "complexity_tier": "T3", "furigana": "りょういき けいけん たいせつ", "sentence_source": "generated"}, {"text": "二つの領域を結ぶ仕事をする。", "target_word": "領域", "complexity_tier": "T3", "furigana": "ふた りょういき むす しごと", "sentence_source": "generated"}, {"text": "領域を越えて協力し合う。", "target_word": "領域", "complexity_tier": "T3", "furigana": "りょういき こ きょうりょく あ", "sentence_source": "generated"}], "morphological_forms": [{"form": "領域外", "label": "派生"}, {"form": "専門領域", "label": "派生"}, {"form": "研究領域", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事が及ぶ範囲や分