INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35427, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の状態や数量が時とともに変わること。", "primary_collocate": null, "pronunciation": "へんどう", "ipa": "hendoː", "syllable_count": 4, "sentences": [{"text": "気候変動という地球的危機の緩和に向け、産業セクターにおける排出量の抑制は、持続可能性を担保する上で不可避の責務である。", "target_word": "変動", "complexity_tier": "T3", "furigana": "へんどう", "sentence_source": "mined"}, {"text": "人為的な要因によって大気中に放出された過剰な温室効果ガスは、放射強制力を変化させ、全球規模での気候変動を加速させている。", "target_word": "変動", "complexity_tier": "T3", "furigana": "へんどう", "sentence_source": "mined"}, {"text": "物価の変動が大きい年だった。", "target_word": "変動", "complexity_tier": "T3", "furigana": "ぶっか へんどう おお とし", "sentence_source": "generated"}, {"text": "気温が一日で大きく変動した。", "target_word": "変動", "complexity_tier": "T3", "furigana": "きおん いちにち おお へんどう", "sentence_source": "generated"}, {"text": "株価は毎日変動している。", "target_word": "変動", "complexity_tier": "T3", "furigana": "かぶか まいにち へんどう", "sentence_source": "generated"}, {"text": "人口の変動を調べてみた。", "target_word": "変動", "complexity_tier": "T3", "furigana": "じんこう へんどう しら", "sentence_source": "generated"}, {"text": "変動する数字を記録した。", "target_word": "変動", "complexity_tier": "T3", "furigana": "へんどう すうじ きろく", "sentence_source": "generated"}, {"text": "為替の変動に注意が必要だ。", "target_word": "変動", "complexity_tier": "T3", "furigana": "かわせ へんどう ちゅうい ひつよう", "sentence_source": "generated"}, {"text": "天候の変動で収穫が減った。", "target_word": "変動", "complexity_tier": "T3", "furigana": "てんこう へんどう しゅうかく へ", "sentence_source": "generated"}, {"text": "価格が変動しやすい商品だ。", "target_word": "変動", "complexity_tier": "T3", "furigana": "かかく へんどう しょうひん", "sentence_source": "generated"}], "morphological_forms": [{"form": "変動する", "label": "派生"}, {"form": "変動した", "label": "活用"}, {"form": "価格変動", "label": "派生"}, {"form": "変動制", "label": "派生"}], "register": "formal", "sense_fingerp