INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39001, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "品質を担保して、商品が壊れてしまった。", "corrected_sentence": "品質を担保して、安心して売れるようになった。", "error_description": "「担保」は確実さを保証する意味なので、壊れる結果とは結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99349385-2231-496d-a689-4c46ca1b4bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39001, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "この位置に入る正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "「担保する」は目的語を「を」で取るので「に」は不可。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所を表し、目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、この位置では非文。"}], "correct_answer": "を", "explanations": {"を": "この位置に入る正しい助詞。", "に": "「担保する」は目的語を「を」で取るので「に」は不可。", "で": "「で」は手段・場所を表し、目的語にならない。", "へ": "「へ」は方向を表し、この位置では非文。"}, "error_tags": {"に": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99349385-2231-496d-a689-4c46ca1b4bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39001, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "担保", "is_correct": true, "explanation": "正解。「担保（たんぽ）」の音。"}, {"text": "短歌", "is_correct": false, "explanation": "「短歌（たんか）」。「ぽ」が「か」になる一モーラ差。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩（さんぽ）」。語頭「た」が「さ」になる一モーラ差。"}, {"text": "田んぼ", "is_correct": false, "explanation": "「田んぼ（たんぼ）」。「ぽ」と「ぼ」の半濁音・濁音の違い。"}, {"text": "端午", "is_correct": false, "explanation": "「端午（たんご）」。「ぽ」が「ご」になる一モーラ差。"}], "explanations": {"担保": "正解。「担保（たんぽ）」の音。", "短歌": "「短歌（たんか）」。「ぽ」が「か」になる一モーラ差。", "散歩": "「散歩（さんぽ）」。語頭「た」が「さ」になる一モーラ差。", "田んぼ": "「田んぼ（たんぼ）」。「ぽ」と「ぼ」の半濁音・濁音の違い。", "端午": "「端午（たんご）」。「ぽ」が「ご」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "担保"}, "level_3": {"options": [{"text": "担保", "is_correct": true, "explanation": "文脈に合う唯一の語。"}, {"text": "隠蔽", "is_correct": false, "explanation": "透明性を隠すことは公開と矛盾する。"}, {"text": "削除", "is_correct": false, "explanation": "透明性を消すのでは意味が通らない。"}, {"text": "損失", "is_correct": false, "explanation": "「損失する」とは言わず、文意にも合わない。"}], "explanations": {"担保": "文脈に合う唯一の語。", "隠蔽": "透明性を隠すことは公開と矛盾する。", "削除": "透明性を消すのでは意味が通らない。", "損失": "「損失する」とは言わず、文意にも合わない。"}, "sentence_index": 6, "correct_answer": "担保"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お腹が空いたので、パンを担保した。", "explanation": "「食べる・買う」の意味で誤用している。"}, {"text": "雨が担保して、道がぬれた。", "explanation": "自然現象の「降る」の意味で誤用している。"}, {"text": "友達と駅で担保して、映画を見た。", "explanation": "「待ち合わせる」の意味で誤用している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99349385-2231-496d-a689-4c46ca1b4bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_