INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38235, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "増す", "is_correct": true, "explanation": "正解。「増す（ます）」の音。"}, {"text": "待つ", "is_correct": false, "explanation": "「待つ（まつ）」。「す」が「つ」になる一モーラ差。"}, {"text": "貸す", "is_correct": false, "explanation": "「貸す（かす）」。「ま」が「か」になる一モーラ差。"}, {"text": "茄子", "is_correct": false, "explanation": "「茄子（なす）」。「ま」が「な」になる一モーラ差。"}, {"text": "豆", "is_correct": false, "explanation": "「豆（まめ）」。「す」が「め」になる一モーラ差。"}], "explanations": {"増す": "正解。「増す（ます）」の音。", "待つ": "「待つ（まつ）」。「す」が「つ」になる一モーラ差。", "貸す": "「貸す（かす）」。「ま」が「か」になる一モーラ差。", "茄子": "「茄子（なす）」。「ま」が「な」になる一モーラ差。", "豆": "「豆（まめ）」。「す」が「め」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "増す"}, "level_3": {"options": [{"text": "増し", "is_correct": true, "explanation": "文脈に合う唯一の語。"}, {"text": "減らし", "is_correct": false, "explanation": "「存在感を減らしていく」では要石としての文意と矛盾する。"}, {"text": "失い", "is_correct": false, "explanation": "「存在感をさらに失い」は「さらに」と要石の文脈に合わない。"}, {"text": "隠し", "is_correct": false, "explanation": "「存在感を隠していく」は文意に合わない。"}], "explanations": {"増し": "文脈に合う唯一の語。", "減らし": "「存在感を減らしていく」では要石としての文意と矛盾する。", "失い": "「存在感をさらに失い」は「さらに」と要石の文脈に合わない。", "隠し": "「存在感を隠していく」は文意に合わない。"}, "sentence_index": 0, "correct_answer": "増し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅で友達を増して、一緒に帰った。", "explanation": "「待つ・会う」の意味で誤用している。"}, {"text": "この服は私に増している。", "explanation": "「似合う」の意味で誤用している。"}, {"text": "先生に本を増して、お礼を言った。", "explanation": "「渡す」の意味で誤用している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99349385-2231-496d-a689-4c46ca1b4bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38235, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人気が日ごとに増すている。", "corrected_sentence": "人気が日ごとに増している。", "error_description": "「増す」のテ形は「増して」で、「増すて」とは言わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "増し", "is_correct": true, "explanation": "連用形で次の節へつなぐ。"}, {"text": "増す", "is_correct": false, "explanation": "終止形では文が続かない。"}, {"text": "増した", "is_correct": false, "explanation": "過去形の後に読点で文が続くのは不自然。"}, {"text": "増さ", "is_correct": false, "explanation": "未然形は「ない」などが続く形。"}], "correct_form": "増し", "base_form": "増す", "form_label": "連用形", "sentence_index": 1, "explanations": {"増し": "連用形で次の節へつなぐ。", "増す": "終止形では文が続かない。", "増した": "過去形の後に読点で文が続くのは不自然。", "増さ": "未然形は「ない」などが続く形。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99349385-2231-496d-a689-4c46ca1b4bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38235, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "この位置に入る正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "「増す」の対象は「に」で示さない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所で、この位置では非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は不可。"}], "correct_answer": "を", "explanations": {"を": "この位置に入る正しい助詞。", "に": "「増す」の対象は「に」で示さない。", "で": "「で」は手段・場所で、この位置では非文。", "へ": "方向の「へ」は不可。"}, "error_tags": {"に": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "減る", "is_correct": true, "explanation": "この語義の対義語。"}, {"text": "広がる", "is_correct": false, "explanation": "対義語ではなく、似た方向の意味。"}, {"text": "変わる", "is_correct": false, "explanation": "変化一般を表し、対義ではない。"}, {"text": "止まる", "is_correct": false, "explanation": "動きがやむ意味で、量の増減の対義ではない。"}], "correct_answer": "減る", "explanations": {"減る": "この語義の対義語。", "広がる": "対義語ではなく、似た方向の意味。", "変わる": "変化一般を表し、対義ではない。", "止まる": "動きがやむ意味で、量の増減の対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99349385-2231-496d-a689-4c46ca1b4bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
