INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37245, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "緩和", "is_correct": true, "explanation": "正解。「緩和（かんわ）」の音。"}, {"text": "電話", "is_correct": false, "explanation": "「電話（でんわ）」。「か」が「で」になる一モーラ差。"}, {"text": "神話", "is_correct": false, "explanation": "「神話（しんわ）」。「か」が「し」になる一モーラ差。"}, {"text": "寒波", "is_correct": false, "explanation": "「寒波（かんぱ）」。「わ」が「ぱ」になる一モーラ差。"}, {"text": "鉋", "is_correct": false, "explanation": "「鉋（かんな）」。「わ」が「な」になる一モーラ差。"}], "explanations": {"緩和": "正解。「緩和（かんわ）」の音。", "電話": "「電話（でんわ）」。「か」が「で」になる一モーラ差。", "神話": "「神話（しんわ）」。「か」が「し」になる一モーラ差。", "寒波": "「寒波（かんぱ）」。「わ」が「ぱ」になる一モーラ差。", "鉋": "「鉋（かんな）」。「わ」が「な」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "緩和"}, "level_3": {"options": [{"text": "緩和", "is_correct": true, "explanation": "文脈に合う唯一の語。"}, {"text": "悪化", "is_correct": false, "explanation": "危機の悪化に向けて抑制するのは矛盾する。"}, {"text": "拡大", "is_correct": false, "explanation": "危機を広げる方向では責務と矛盾する。"}, {"text": "発生", "is_correct": false, "explanation": "危機の発生に向けるのは文意に合わない。"}], "explanations": {"緩和": "文脈に合う唯一の語。", "悪化": "危機の悪化に向けて抑制するのは矛盾する。", "拡大": "危機を広げる方向では責務と矛盾する。", "発生": "危機の発生に向けるのは文意に合わない。"}, "sentence_index": 0, "correct_answer": "緩和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ケーキを緩和して友達と食べた。", "explanation": "「切る・分ける」の意味で誤用している。"}, {"text": "窓を緩和して外を見た。", "explanation": "「開ける」の意味で誤用している。"}, {"text": "彼は新しい靴を緩和した。", "explanation": "「買う・はく」の意味で誤用している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99349385-2231-496d-a689-4c46ca1b4bb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
