INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51926, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "計画や目標などを考えて決めること。", "primary_collocate": "計画", "pronunciation": "たてる", "ipa": "tateɾɯ", "syllable_count": 3, "sentences": [{"text": "子供は躊躇いなくその表皮に歯を立て、甘酸っぱい果汁を唇に伝わせながら貪るように食べる。", "target_word": "立て", "complexity_tier": "T3", "furigana": "こども ためら ひょうひ は た あまず かじゅう くちびる つた むさぼ た", "sentence_source": "mined"}, {"text": "この販売活動は、単にお金を稼ぐためだけでなく、自分で計画を立てて実行するという貴重な経験を積むことが目的だった。", "target_word": "立て", "complexity_tier": "T3", "furigana": "はんばいかつどう たん かね かせ じぶん けいかく た じっこう きちょう けいけん つ もくてき", "sentence_source": "mined"}, {"text": "夏休みの計画を立てる。", "target_word": "立てる", "complexity_tier": "T3", "furigana": "なつやす けいかく た", "sentence_source": "generated"}, {"text": "兄は毎朝、一日の予定を立てている。", "target_word": "立て", "complexity_tier": "T3", "furigana": "あに まいあさ いちにち よてい た", "sentence_source": "generated"}, {"text": "新しい目標を立てたので、がんばります。", "target_word": "立て", "complexity_tier": "T3", "furigana": "あたら もくひょう た", "sentence_source": "generated"}, {"text": "旅行の計画を一緒に立てよう。", "target_word": "立て", "complexity_tier": "T3", "furigana": "りょこう けいかく いっしょ た", "sentence_source": "generated"}, {"text": "立てた計画どおりに進まなかった。", "target_word": "立て", "complexity_tier": "T3", "furigana": "た けいかく すす", "sentence_source": "generated"}, {"text": "彼女は作戦を立てるのが上手だ。", "target_word": "立てる", "complexity_tier": "T3", "furigana": "かのじょ さくせん た じょうず", "sentence_source": "generated"}, {"text": "予定を立てずに出かけた。", "target_word": "立て", "complexity_tier": "T3", "furigana": "よてい た で", "sentence_source": "generated"}, {"text": "みんなで方針を立てて話し合った。", "target_word": "立て", "complexity_tier": "T3", "furigana": "ほうしん た はな あ", "sentence_source": "generated"}], "morphological_forms": [{"form": "立てた", "label": "活用"}, {"form": "立てて", "label": "活用"}, {"form": "立てない", "label": "活用"}, {"form": "立てられる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 計画や目標を考えて決める", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 5 words above tier T3 (max 3): 躊躇い (Zipf 2.5), 表皮 (Zipf 3.15), 甘酸っぱい (Zipf 2.99), 伝わ (Zipf 2.78), 貪る (Zipf 2.82)']::text[], '5e718609-9871-4bd6-abdf-e563d329fa7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37081, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものや人をつなぎ合わせて、関係を作ること。", "primary_collocate": null, "pronunciation": "むすぶ", "ipa": "mɯsɯbɯ", "syllable_count": 3, "sentences": [{"text": "靴紐を固く結び、踵で床を鳴らせば、鈍い音が魂の鼓動と共鳴する。", "target_word": "結び", "complexity_tier": "T3", "furigana": "くつひも かた むす かかと ゆか な にぶ おと たましい こどう きょうめい", "sentence_source": "mined"}, {"text": "冷たくて甘いレモネードは、暑さに疲れた人々の喉を潤し、少年の努力は小さな売上となって確実に実を結んでいった。", "target_word": "結ん", "complexity_tier": "T3", "furigana": "つめ あま あつ つか ひとびと のど うるお しょうねん どりょく ちい うりあげ かくじつ み むす", "sentence_source": "mined"}, {"text": "二つの町を橋が結んでいる。", "target_word": "結ん", "complexity_tier": "T3", "furigana": "ふた まち はし むす", "sentence_source": "generated"}, {"text": "両国は新しい条約を結んだ。", "target_word": "結ん", "complexity_tier": "T3", "furigana": "りょうこく あたら じょうやく むす", "sentence_source": "generated"}, {"text": "リボンをきれいに結ぶ。", "target_word": "結ぶ", "complexity_tier": "T3", "furigana": "むす", "sentence_source": "generated"}, {"text": "この道は駅と学校を結ぶ。", "target_word": "結ぶ", "complexity_tier": "T3", "furigana": "みち えき がっこう むす", "sentence_source": "generated"}, {"text": "友情で結ばれた二人だ。", "target_word": "結ば", "complexity_tier": "T3", "furigana": "ゆうじょう むす ふたり", "sentence_source": "generated"}, {"text": "会社と契約を結ぶことになった。", "target_word": "結ぶ", "complexity_tier": "T3", "furigana": "かいしゃ けいやく むす", "sentence_source": "generated"}, {"text": "ひもを結んで箱を閉じた。", "target_word": "結ん", "complexity_tier": "T3", "furigana": "むす はこ と", "sentence_source": "generated"}, {"text": "人と人を結ぶ仕事がしたい。", "target_word": "結ぶ", "complexity_tier": "T3", "furigana": "ひと ひと むす しごと", "sentence_source": "generated"}], "morphological_forms": [{"form": "結んだ", "label": "活用"}, {"form": "結んで", "label": "活用"}, {"form": "結ばない", "label": "活用"}, {"form": "結び", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | ものや人をつないで関係を作る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 踵 (Zipf 3.15), 鳴らせ (Zipf 3.25), 鈍い (Zipf 3.23), 共鳴 (Zipf 3.38)']::text[], '5e718609-9871-4bd6-abdf-e563d329fa7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35165, 3, 'prompt1_core', '{"pos": "代名詞", "semantic_class": "function", "definition": "その人自身。話し手や書き手自身のこと。", "primary_collocate": null, "pronunciation": "じぶん", "ipa": "dʑibɯɴ", "syllable_count": 3, "sentences": [{"text": "私にとってこの行為は、自分自身と対話するための重要な手段なのだ。", "target_word": "自分", "complexity_tier": "T3", "furigana": "わたし こうい じぶんじしん たいわ じゅうよう しゅだん", "sentence_source": "mined"}, {"text": "この販売活動は、単にお金を稼ぐためだけでなく、自分で計画を立てて実行するという貴重な経験を積むことが目的だった。", "target_word": "自分", "complexity_tier": "T3", "furigana": "はんばいかつどう たん かね かせ じぶん けいかく た じっこう きちょう けいけん つ もくてき", "sentence_source": "mined"}, {"text": "自分の部屋を掃除した。", "target_word": "自分", "complexity_tier": "T3", "furigana": "じぶん へや そうじ", "sentence_source": "generated"}, {"text": "宿題は自分でやりなさい。", "target_word": "自分", "complexity_tier": "T3", "furigana": "しゅくだい じぶん", "sentence_source": "generated"}, {"text": "自分が正しいと思っている。", "target_word": "自分", "complexity_tier": "T3", "furigana": "じぶん ただ おも", "sentence_source": "generated"}, {"text": "彼は自分のことをよく話す。", "target_word": "自分", "complexity_tier": "T3", "furigana": "かれ じぶん はな", "sentence_source": "generated"}, {"text": "自分を信じることが大切だ。", "target_word": "自分", "complexity_tier": "T3", "furigana": "じぶん しん たいせつ", "sentence_source": "generated"}, {"text": "自分らしく生きたい。", "target_word": "自分", "complexity_tier": "T3", "furigana": "じぶん い", "sentence_source": "generated"}, {"text": "失敗したのは自分のせいだ。", "target_word": "自分", "complexity_tier": "T3", "furigana": "しっぱい じぶん", "sentence_source": "generated"}, {"text": "自分で作った料理はおいしい。", "target_word": "自分", "complexity_tier": "T3", "furigana": "じぶん つく りょうり", "sentence_source": "generated"}], "morphological_forms": [{"form": "自分自身", "label": "派生"}, {"form": "自分たち", "label": "派生"}, {"form": "自分勝手", "label": "派生"}], "register": "plain", "sense_fingerprint": "代名詞 | その人自身を指す言葉", "collocate_grou