INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37357, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "実現しようとして目指すこと。行動のねらい。", "primary_collocate": null, "pronunciation": "もくてき", "ipa": "mokɯteki", "syllable_count": 4, "sentences": [{"text": "犯行の客観的裏付けという目的のため、この緻密な照合作業を経て、初めて不可謬な身元特定が達成されるのである。", "target_word": "目的", "complexity_tier": "T3", "furigana": "はんこう きゃっかんてき うらづ もくてき ちみつ しょうごうさぎょう へ はじ ふかびゅう みもととくてい たっせい", "sentence_source": "mined"}, {"text": "この販売活動は、単にお金を稼ぐためだけでなく、自分で計画を立てて実行するという貴重な経験を積むことが目的だった。", "target_word": "目的", "complexity_tier": "T3", "furigana": "はんばいかつどう たん かね かせ じぶん けいかく た じっこう きちょう けいけん つ もくてき", "sentence_source": "mined"}, {"text": "旅行の目的は何ですか。", "target_word": "目的", "complexity_tier": "T3", "furigana": "りょこう もくてき なん", "sentence_source": "generated"}, {"text": "目的を持って勉強している。", "target_word": "目的", "complexity_tier": "T3", "furigana": "もくてき も べんきょう", "sentence_source": "generated"}, {"text": "会議の目的がわからない。", "target_word": "目的", "complexity_tier": "T3", "furigana": "かいぎ もくてき", "sentence_source": "generated"}, {"text": "彼はついに目的を果たした。", "target_word": "目的", "complexity_tier": "T3", "furigana": "かれ もくてき は", "sentence_source": "generated"}, {"text": "健康のための運動が目的だ。", "target_word": "目的", "complexity_tier": "T3", "furigana": "けんこう うんどう もくてき", "sentence_source": "generated"}, {"text": "目的もなく町を歩いた。", "target_word": "目的", "complexity_tier": "T3", "furigana": "もくてき まち ある", "sentence_source": "generated"}, {"text": "同じ目的の仲間が集まった。", "target_word": "目的", "complexity_tier": "T3", "furigana": "おな もくてき なかま あつ", "sentence_source": "generated"}, {"text": "目的に合った方法を選ぶ。", "target_word": "目的", "complexity_tier": "T3", "furigana": "もくてき あ ほうほう えら", "sentence_source": "generated"}], "morphological_forms": [{"form": "目的地", "label": "派生"}, {"form": "目的語", "label": "派生"}, {"form": "目的意識", "label": "派生"}], "reg