INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36635, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "過剰", "is_correct": true, "explanation": "正解：音声どおりの語"}, {"text": "牙城", "is_correct": false, "explanation": "がじょう：一拍目「か」→「が」の清濁差"}, {"text": "華僑", "is_correct": false, "explanation": "かきょう：二拍目「じょ」→「きょ」の一モーラ差"}, {"text": "歌唱", "is_correct": false, "explanation": "かしょう：二拍目「じょ」→「しょ」の清濁差"}, {"text": "非常", "is_correct": false, "explanation": "ひじょう：一拍目「か」→「ひ」の一モーラ差"}], "explanations": {"過剰": "正解：音声どおりの語", "牙城": "がじょう：一拍目「か」→「が」の清濁差", "華僑": "かきょう：二拍目「じょ」→「きょ」の一モーラ差", "歌唱": "かしょう：二拍目「じょ」→「しょ」の清濁差", "非常": "ひじょう：一拍目「か」→「ひ」の一モーラ差"}, "sentence_index": null, "correct_answer": "過剰"}, "level_3": {"options": [{"text": "過剰", "is_correct": true, "explanation": "文脈に合う正しい語"}, {"text": "静か", "is_correct": false, "explanation": "意味：流動性が静かとは言わない"}, {"text": "親切", "is_correct": false, "explanation": "意味：人の性質で流動性に合わない"}, {"text": "上手", "is_correct": false, "explanation": "意味：技能の語で文脈に合わない"}], "explanations": {"過剰": "文脈に合う正しい語", "静か": "意味：流動性が静かとは言わない", "親切": "意味：人の性質で流動性に合わない", "上手": "意味：技能の語で文脈に合わない"}, "sentence_index": 0, "correct_answer": "過剰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は少し過剰な反応した。", "explanation": "活用の誤り：動詞を修飾するには「過剰に」"}, {"text": "彼は少し過剰が反応した。", "explanation": "助詞の混同：過剰は主語にならない"}, {"text": "彼は少し過剰だに反応した。", "explanation": "活用の誤り：動詞を修飾するのは「過剰に」"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8819faf8-cf25-4d9e-a1be-e3e0d7121491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
