INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36139, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "長い歴史の中で受け継がれてきた、特定の社会や集団に特有の習慣や考え方。", "primary_collocate": null, "pronunciation": "でんとう", "ipa": "deɴtoː", "syllable_count": 4, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "しかし現代ファッションの文脈では、この伝統的な職人技はデジタルデザインという新たなパラダイムと衝突し、あるいは融合しつつある。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "この祭りには長い伝統がある。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "まつ なが でんとう", "sentence_source": "generated"}, {"text": "村の伝統を守りたい。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "むら でんとう まも", "sentence_source": "generated"}, {"text": "伝統は大切にするべきだ。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "でんとう たいせつ", "sentence_source": "generated"}, {"text": "祖母が伝統の料理を作った。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "そぼ でんとう りょうり つく", "sentence_source": "generated"}, {"text": "この学校の伝統は合唱です。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "がっこう でんとう がっしょう", "sentence_source": "generated"}, {"text": "新しい伝統を作っている。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "あたら でんとう つく", "sentence_source": "generated"}, {"text": "伝統的な家に住んでいる。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "でんとうてき いえ す", "sentence_source": "generated"}, {"text": "古い伝統が消えつつある。", "target_word": "伝統", "complexity_tier": "T3", "furigana": "ふる でんとう き", "sentence_source": "generated"}], "morphological_forms": [{"form": "伝統的", "label": "派生"}, {"form": "伝統文化", "label": "派生"}, {"form": "伝統行事", "label": "派生"}], "register": "f