INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36139, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「作る」の目的語「伝統」を示す。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、「伝統に作る」は非文。"}, {"text": "で", "is_correct": false, "explanation": "手段を表し、作る対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「作る」の目的語「伝統」を示す。", "に": "着点を表し、「伝統に作る」は非文。", "で": "手段を表し、作る対象を示せない。", "へ": "方向を表し、目的語にならない。"}, "error_tags": {"に": "location_vs_target", "で": "instrument", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "革新", "is_correct": true, "explanation": "受け継ぐ「伝統」と、新しく変える「革新」は反対の意味。"}, {"text": "風習", "is_correct": false, "explanation": "伝統に近い意味で、対義ではない。"}, {"text": "行事", "is_correct": false, "explanation": "伝統に関わる語だが、反対の意味ではない。"}, {"text": "習わし", "is_correct": false, "explanation": "伝統とほぼ同じ意味の語。"}], "correct_answer": "革新", "explanations": {"革新": "受け継ぐ「伝統」と、新しく変える「革新」は反対の意味。", "風習": "伝統に近い意味で、対義ではない。", "行事": "伝統に関わる語だが、反対の意味ではない。", "習わし": "伝統とほぼ同じ意味の語。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c95e541-ea0e-452e-8900-36e3506d76bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39471, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中央", "is_correct": true, "explanation": "正解。読みは「ちゅうおう」。"}, {"text": "中東", "is_correct": false, "explanation": "読みは「ちゅうとう」。「お」が「と」に変わる一モーラ差。"}, {"text": "中庸", "is_correct": false, "explanation": "読みは「ちゅうよう」。「お」が「よ」に変わる一モーラ差。"}, {"text": "抽象", "is_correct": false, "explanation": "読みは「ちゅうしょう」。「お」が「しょ」に変わる一モーラ差。"}, {"text": "中興", "is_correct": false, "explanation": "読みは「ちゅうこう」。「お」が「こ」に変わる一モーラ差。"}], "explanations": {"中央": "正解。読みは「ちゅうおう」。", "中東": "読みは「ちゅうとう」。「お」が「と」に変わる一モーラ差。", "中庸": "読みは「ちゅうよう」。「お」が「よ」に変わる一モーラ差。", "抽象": "読みは「ちゅうしょう」。「お」が「しょ」に変わる一モーラ差。", "中興": "読みは「ちゅうこう」。「お」が「こ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "中央"}, "level_3": {"options": [{"text": "中央", "is_correct": true, "explanation": "「中央銀行」で、国の金融の中心となる銀行を表す。"}, {"text": "海岸", "is_correct": false, "explanation": "「海岸銀行」は国の金融政策を担う銀行の名ではない。"}, {"text": "台所", "is_correct": false, "explanation": "「台所銀行」という語は存在しない。"}, {"text": "屋根", "is_correct": false, "explanation": "「屋根銀行」は意味が通らない。"}], "explanations": {"中央": "「中央銀行」で、国の金融の中心となる銀行を表す。", "海岸": "「海岸銀行」は国の金融政策を担う銀行の名ではない。", "台所": "「台所銀行」という語は存在しない。", "屋根": "「屋根銀行」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "中央"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この中央はとても甘い。", "explanation": "中央は位置を表す語で、味を持たない。"}, {"text": "中央を二枚買ってきた。", "explanation": "中央は品物ではなく、買ったり枚で数えたりできない。"}, {"text": "昨日、中央と話した。", "explanation": "中央は人ではないので話し相手にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c95e541-ea0e-452e-8900-36e3506d76bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_wa