INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36603, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "メカニズム", "is_correct": true, "explanation": "正解。読みは「めかにずむ」。"}, {"text": "メカニック", "is_correct": false, "explanation": "読みは「めかにっく」。語頭「めかに」が同じで、後半の音だけが違う。"}, {"text": "メカニカル", "is_correct": false, "explanation": "読みは「めかにかる」。語頭「めかに」が同じで、後半の音だけが違う。"}, {"text": "リアリズム", "is_correct": false, "explanation": "読みは「りありずむ」。語尾「ずむ」が同じで、前半の音が違う。"}], "explanations": {"メカニズム": "正解。読みは「めかにずむ」。", "メカニック": "読みは「めかにっく」。語頭「めかに」が同じで、後半の音だけが違う。", "メカニカル": "読みは「めかにかる」。語頭「めかに」が同じで、後半の音だけが違う。", "リアリズム": "読みは「りありずむ」。語尾「ずむ」が同じで、前半の音が違う。"}, "sentence_index": null, "correct_answer": "メカニズム"}, "level_3": {"options": [{"text": "メカニズム", "is_correct": true, "explanation": "「市場メカニズム」で、需要と供給で価格が決まる仕組みを表す。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "「市場ハンカチ」は意味が通らない。"}, {"text": "カーテン", "is_correct": false, "explanation": "「市場カーテンを通じた形成」は不自然。"}, {"text": "スリッパ", "is_correct": false, "explanation": "「市場スリッパ」という語はない。"}], "explanations": {"メカニズム": "「市場メカニズム」で、需要と供給で価格が決まる仕組みを表す。", "ハンカチ": "「市場ハンカチ」は意味が通らない。", "カーテン": "「市場カーテンを通じた形成」は不自然。", "スリッパ": "「市場スリッパ」という語はない。"}, "sentence_index": 0, "correct_answer": "メカニズム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "メカニズムを冷蔵庫で冷やした。", "explanation": "メカニズムは仕組みで、冷やせる物ではない。"}, {"text": "メカニズムが二人でご飯を食べた。", "explanation": "メカニズムは人ではない。"}, {"text": "メカニズムを一杯ください。", "explanation": "メカニズムは飲み物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c95e541-ea0e-452e-8900-36e3506d76bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
