INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35707, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。この位置には「を」が必要。"}, {"text": "が", "is_correct": false, "explanation": "他動詞「比べる」の目的語を「が」では示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は目的語にならない。"}, {"text": "の", "is_correct": false, "explanation": "「価格の比べてみた」は非文。"}], "correct_answer": "を", "explanations": {"を": "正解。この位置には「を」が必要。", "が": "他動詞「比べる」の目的語を「が」では示せない。", "へ": "方向を表す「へ」は目的語にならない。", "の": "「価格の比べてみた」は非文。"}, "error_tags": {"が": "object_marking", "へ": "direction", "の": "other"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36099, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "装飾", "is_correct": true, "explanation": "正解。「装飾（そうしょく）」。"}, {"text": "増殖", "is_correct": false, "explanation": "「増殖（ぞうしょく）」。一拍目「そ」が濁音「ぞ」になる清濁の対立。"}, {"text": "葬式", "is_correct": false, "explanation": "「葬式（そうしき）」。四拍目「く」が「き」に変わる一モーラ差。"}, {"text": "朝食", "is_correct": false, "explanation": "「朝食（ちょうしょく）」。一拍目「そ」が「ちょ」に変わる一モーラ差。"}, {"text": "公職", "is_correct": false, "explanation": "「公職（こうしょく）」。一拍目「そ」が「こ」に変わる一モーラ差。"}], "explanations": {"装飾": "正解。「装飾（そうしょく）」。", "増殖": "「増殖（ぞうしょく）」。一拍目「そ」が濁音「ぞ」になる清濁の対立。", "葬式": "「葬式（そうしき）」。四拍目「く」が「き」に変わる一モーラ差。", "朝食": "「朝食（ちょうしょく）」。一拍目「そ」が「ちょ」に変わる一モーラ差。", "公職": "「公職（こうしょく）」。一拍目「そ」が「こ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "装飾"}, "level_3": {"options": [{"text": "装飾", "is_correct": true, "explanation": "正解。文脈に合うのは「装飾」。"}, {"text": "睡眠", "is_correct": false, "explanation": "意味：Tシャツデザインが「睡眠を超える」は意味をなさない。"}, {"text": "天気", "is_correct": false, "explanation": "意味：天気はデザインの役割ではない。"}, {"text": "運賃", "is_correct": false, "explanation": "連語：デザインと運賃は結びつかない。"}], "explanations": {"装飾": "正解。文脈に合うのは「装飾」。", "睡眠": "意味：Tシャツデザインが「睡眠を超える」は意味をなさない。", "天気": "意味：天気はデザインの役割ではない。", "運賃": "連語：デザインと運賃は結びつかない。"}, "sentence_index": 0, "correct_answer": "装飾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱は装飾をとてもきれいだ。", "explanation": "助詞の混同：「きれいだ」の主語は「が」で示す。"}, {"text": "この箱は装飾がとてもおいしい。", "explanation": "意味の不一致：「装飾」は味わうものではなく、「おいしい」とは結びつかない。"}, {"text": "この箱はとても装飾がきれいている。", "explanation": "活用の誤り：「きれいだ」に「ている」は付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36099, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教室の装飾がみんなで考えた。", "corrected_sentence": "教室の装飾をみんなで考えた。", "error_description": "「考える」の目的語は「を」で示す。「が」では主語になってしまう。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36099, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "正解。この位置には「から」が必要。"}, {"text": "を", "is_correct": false, "explanation": "「観点を」では後の動詞と結びつかず非文。"}, {"text": "が", "is_correct": false, "explanation": "「観点が」は主語になり文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では観点を根拠として表せない。"}], "correct_answer": "から", "explanations": {"から": "正解。この位置には「から」が必要。", "を": "「観点を」では後の動詞と結びつかず非文。", "が": "「観点が」は主語になり文が成立しない。", "へ": "方向の「へ」では観点を根拠として表せない。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "へ": "source_vs_goal"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36099, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "装飾", "is_correct": true, "explanation": "正解。「装飾（そうしょく）」。"}, {"text": "夕食", "is_correct": false, "explanation": "「夕食（ゆうしょく）」。一拍目「そ」が「ゆ」に変わる一モーラ差。"}, {"text": "昼食", "is_correct": false, "explanation": "「昼食（ちゅうしょく）」。一拍目「そ」が「ちゅ」に変わる一モーラ差。"}, {"text": "就職", "is_correct": false, "explanation": "「就職（しゅうしょく）」。一拍目「そ」が「しゅ」に変わる一モーラ差。"}], "explanations": {"装飾": "正解。「装飾（そうしょく）」。", "夕食": "「夕食（ゆうしょく）」。一拍目「そ」が「ゆ」に変わる一モーラ差。", "昼食": "「昼食（ちゅうしょく）」。一拍目「そ」が「ちゅ」に変わる一モーラ差。", "就職": "「就職（しゅうしょく）」。一拍目「そ」が「しゅ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "装飾"}, "level_3": {"options": [{"text": "装飾", "is_correct": true, "explanation": "正解。文脈に合うのは「装飾」。"}, {"text": "返事", "is_correct": false, "explanation": "意味：窓に返事はつけられない。"}, {"text": "宿題", "is_correct": false, "explanation": "意味：花の宿題を窓につけるのは意味をなさない。"}, {"text": "値段", "is_correct": false, "explanation": "連語：「花の値段を窓につけた」は不自然。"}], "explanations": {"装飾": "正解。文脈に合うのは「装飾」。", "返事": "意味：窓に返事はつけられない。", "宿題": "意味：花の宿題を窓につけるのは意味をなさない。", "値段": "連語：「花の値段を窓につけた」は不自然。"}, "sentence_index": 6, "correct_answer": "装飾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "派手な装飾は飲みたくないと思う。", "explanation": "意味の不一致：「装飾」は飲むものではない。"}, {"text": "派手な装飾にいらないと思う。", "explanation": "助詞の誤り：「いらない」の対象は「は／が」で示し、「に」は不可。"}, {"text": "派手な装飾はいらないに思う。", "explanation": "助詞の誤り：思う内容を引用するには「と」が必要。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36099, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "装飾の少ない部屋に好きです。", "corrected_sentence": "装飾の少ない部屋が好きです。", "error_description": "「好きです」の対象は「が」で示す。「に」は不可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36099, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。この位置には「に」が必要。"}, {"text": "を", "is_correct": false, "explanation": "「感動する」は自動詞で「を」を取らない。"}, {"text": "が", "is_correct": false, "explanation": "「装飾が感動した」では装飾が感動する意味になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は感動の対象を示せない。"}], "correct_answer": "に", "explanations": {"に": "正解。この位置には「に」が必要。", "を": "「感動する」は自動詞で「を」を取らない。", "が": "「装飾が感動した」では装飾が感動する意味になる。", "へ": "方向の「へ」は感動の対象を示せない。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51856, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "独自", "is_correct": true, "explanation": "正解。「独自（どくじ）」。"}, {"text": "毒蛇", "is_correct": false, "explanation": "「毒蛇（どくじゃ）」。三拍目「じ」が「じゃ」に変わる一モーラ差。"}, {"text": "読者", "is_correct": false, "explanation": "「読者（どくしゃ）」。三拍目「じ」が「しゃ」に変わる一モーラ差。"}, {"text": "六時", "is_correct": false, "explanation": "「六時（ろくじ）」。一拍目「ど」が「ろ」に変わる一モーラ差。"}, {"text": "同時", "is_correct": false, "explanation": "「同時（どうじ）」。二拍目「く」が「う」に変わる一モーラ差。"}], "explanations": {"独自": "正解。「独自（どくじ）」。", "毒蛇": "「毒蛇（どくじゃ）」。三拍目「じ」が「じゃ」に変わる一モーラ差。", "読者": "「読者（どくしゃ）」。三拍目「じ」が「しゃ」に変わる一モーラ差。", "六時": "「六時（ろくじ）」。一拍目「ど」が「ろ」に変わる一モーラ差。", "同時": "「同時（どうじ）」。二拍目「く」が「う」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "独自"}, "level_3": {"options": [{"text": "独自", "is_correct": true, "explanation": "正解。文脈に合うのは「独自」。"}, {"text": "満腹", "is_correct": false, "explanation": "意味：「満腹のプロット」は意味をなさない。"}, {"text": "真冬", "is_correct": false, "explanation": "意味：プロットに季節の語は合わない。"}, {"text": "無料", "is_correct": false, "explanation": "連語：「無料のプロットを紡ぎ出す」は不自然。"}], "explanations": {"独自": "正解。文脈に合うのは「独自」。", "満腹": "意味：「満腹のプロット」は意味をなさない。", "真冬": "意味：プロットに季節の語は合わない。", "無料": "連語：「無料のプロットを紡ぎ出す」は不自然。"}, "sentence_index": 0, "correct_answer": "独自"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町には独自を祭りがある。", "explanation": "助詞の混同：名詞を修飾するには「の」が必要。"}, {"text": "この町には独自に祭りがある。", "explanation": "形の誤り：名詞を修飾するのは「独自の」。「独自に」は動詞を修飾する形。"}, {"text": "この町には独自の祭りがあっている。", "explanation": "活用の誤り：「ある」に「ている」は付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51856, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私たちは独自を調べてみた。", "corrected_sentence": "私たちは独自に調べてみた。", "error_description": "動詞を修飾するときは「独自に」。「独自を」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "独自", "is_correct": true, "explanation": "後ろの「の」に続くのは語幹「独自」。"}, {"text": "独自に", "is_correct": false, "explanation": "「独自にの」は非文。"}, {"text": "独自だ", "is_correct": false, "explanation": "終止形「独自だ」は「の」に続かない。"}, {"text": "独自な", "is_correct": false, "explanation": "「独自なの工芸」は非文。"}], "correct_form": "独自", "base_form": "独自", "form_label": "語幹（「の」接続）", "sentence_index": 1, "explanations": {"独自": "後ろの「の」に続くのは語幹「独自」。", "独自に": "「独自にの」は非文。", "独自だ": "終止形「独自だ」は「の」に続かない。", "独自な": "「独自なの工芸」は非文。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51856, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "共通", "is_correct": true, "explanation": "他と同じであることを表し、「独自」の対義。"}, {"text": "固有", "is_correct": false, "explanation": "そのものだけにあることで、むしろ類義。"}, {"text": "特有", "is_correct": false, "explanation": "そのものに特にあることで、類義に近い。"}, {"text": "新鮮", "is_correct": false, "explanation": "新しさを表し、対義関係にない。"}], "correct_answer": "共通", "explanations": {"共通": "他と同じであることを表し、「独自」の対義。", "固有": "そのものだけにあることで、むしろ類義。", "特有": "そのものに特にあることで、類義に近い。", "新鮮": "新しさを表し、対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51856, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "独自", "is_correct": true, "explanation": "正解。「独自（どくじ）」。"}, {"text": "食事", "is_correct": false, "explanation": "「食事（しょくじ）」。一拍目「ど」が「しょ」に変わる一モーラ差。"}, {"text": "読書", "is_correct": false, "explanation": "「読書（どくしょ）」。三拍目「じ」が「しょ」に変わる一モーラ差。"}, {"text": "毒死", "is_correct": false, "explanation": "「毒死（どくし）」。三拍目「じ」が清音「し」になる清濁の対立。"}], "explanations": {"独自": "正解。「独自（どくじ）」。", "食事": "「食事（しょくじ）」。一拍目「ど」が「しょ」に変わる一モーラ差。", "読書": "「読書（どくしょ）」。三拍目「じ」が「しょ」に変わる一モーラ差。", "毒死": "「毒死（どくし）」。三拍目「じ」が清音「し」になる清濁の対立。"}, "sentence_index": null, "correct_answer": "独自"}, "level_3": {"options": [{"text": "独自", "is_correct": true, "explanation": "正解。文脈に合うのは「独自」。"}, {"text": "空腹", "is_correct": false, "explanation": "意味：「空腹のルール」は意味をなさない。"}, {"text": "満席", "is_correct": false, "explanation": "意味：「満席のルール」は意味をなさない。"}, {"text": "雨天", "is_correct": false, "explanation": "連語：「雨天のルールで遊ぶ」は不自然。"}], "explanations": {"独自": "正解。文脈に合うのは「独自」。", "空腹": "意味：「空腹のルール」は意味をなさない。", "満席": "意味：「満席のルール」は意味をなさない。", "雨天": "連語：「雨天のルールで遊ぶ」は不自然。"}, "sentence_index": 6, "correct_answer": "独自"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この国には独自が文化がある。", "explanation": "助詞の混同：名詞を修飾するには「の」。"}, {"text": "この国には独自だ文化がある。", "explanation": "形の誤り：終止形「独自だ」は名詞を修飾できない。「独自の」が正しい。"}, {"text": "ある独自の文化がこの国には。", "explanation": "語順の誤り：述語が文頭に来て文が成立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51856, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その店は独自だメニューが人気だ。", "corrected_sentence": "その店は独自のメニューが人気だ。", "error_description": "名詞を修飾するのは「独自の」。終止形「独自だ」では名詞に続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "独自", "is_correct": true, "explanation": "「の」に続くのは語幹「独自」。"}, {"text": "独自に", "is_correct": false, "explanation": "「独自にの考え」は非文。"}, {"text": "独自な", "is_correct": false, "explanation": "「独自なの考え」は非文。"}, {"text": "独自だ", "is_correct": false, "explanation": "終止形は名詞を修飾できない。"}], "correct_form": "独自", "base_form": "独自", "form_label": "語幹（「の」接続）", "sentence_index": 7, "explanations": {"独自": "「の」に続くのは語幹「独自」。", "独自に": "「独自にの考え」は非文。", "独自な": "「独自なの考え」は非文。", "独自だ": "終止形は名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51856, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "共通", "is_correct": true, "explanation": "多くのものに同じようにあることで、「独自」の対義。"}, {"text": "独特", "is_correct": false, "explanation": "そのものだけの特徴で、類義。"}, {"text": "有名", "is_correct": false, "explanation": "知られていることで、対義関係にない。"}, {"text": "伝統", "is_correct": false, "explanation": "昔から続くことで、対義関係にない。"}], "correct_answer": "共通", "explanations": {"共通": "多くのものに同じようにあることで、「独自」の対義。", "独特": "そのものだけの特徴で、類義。", "有名": "知られていることで、対義関係にない。", "伝統": "昔から続くことで、対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37267, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "確認", "is_correct": true, "explanation": "正解。「確認（かくにん）」。"}, {"text": "確信", "is_correct": false, "explanation": "「確信（かくしん）」。三拍目「に」が「し」に変わる一モーラ差。"}, {"text": "各人", "is_correct": false, "explanation": "「各人（かくじん）」。三拍目「に」が「じ」に変わる一モーラ差。"}, {"text": "各員", "is_correct": false, "explanation": "「各員（かくいん）」。三拍目「に」が「い」に変わる一モーラ差。"}], "explanations": {"確認": "正解。「確認（かくにん）」。", "確信": "「確信（かくしん）」。三拍目「に」が「し」に変わる一モーラ差。", "各人": "「各人（かくじん）」。三拍目「に」が「じ」に変わる一モーラ差。", "各員": "「各員（かくいん）」。三拍目「に」が「い」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "確認"}, "level_3": {"options": [{"text": "確認", "is_correct": true, "explanation": "正解。文脈に合うのは「確認」。"}, {"text": "放送", "is_correct": false, "explanation": "連語：「自己効力感の再放送」は意味をなさない。"}, {"text": "婚", "is_correct": false, "explanation": "意味：「再婚」は結婚のことで、感覚には使えない。"}, {"text": "来日", "is_correct": false, "explanation": "意味：「再来日」は人の移動で、自己効力感とは結びつかない。"}], "explanations": {"確認": "正解。文脈に合うのは「確認」。", "放送": "連語：「自己効力感の再放送」は意味をなさない。", "婚": "意味：「再婚」は結婚のことで、感覚には使えない。", "来日": "意味：「再来日」は人の移動で、自己効力感とは結びつかない。"}, "sentence_index": 0, "correct_answer": "確認"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "答えがもう一度確認してください。", "explanation": "助詞の混同：「確認する」の対象は「を」で示す。"}, {"text": "答えをもう一度確認するてください。", "explanation": "活用の誤り：「てください」は連用形に付く。「確認して」が正しい。"}, {"text": "もう一度してください答えを確認。", "explanation": "語順の誤り：文が成立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
