INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37267, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。この位置には「に」が必要。"}, {"text": "が", "is_correct": false, "explanation": "「湿度が合わせて」では誰が合わせるのか分からず非文。"}, {"text": "で", "is_correct": false, "explanation": "「湿度で合わせて」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "「湿度から合わせて」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "正解。この位置には「に」が必要。", "が": "「湿度が合わせて」では誰が合わせるのか分からず非文。", "で": "「湿度で合わせて」は不自然。", "から": "「湿度から合わせて」は意味が通らない。"}, "error_tags": {"が": "topic_vs_subject", "で": "instrument", "から": "source_vs_goal"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37267, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "確認", "is_correct": true, "explanation": "正解。「確認（かくにん）」。"}, {"text": "解任", "is_correct": false, "explanation": "「解任（かいにん）」。二拍目「く」が「い」に変わる一モーラ差。"}, {"text": "堪忍", "is_correct": false, "explanation": "「堪忍（かんにん）」。二拍目「く」が「ん」に変わる一モーラ差。"}, {"text": "革新", "is_correct": false, "explanation": "「革新（かくしん）」。三拍目「に」が「し」に変わる一モーラ差。"}], "explanations": {"確認": "正解。「確認（かくにん）」。", "解任": "「解任（かいにん）」。二拍目「く」が「い」に変わる一モーラ差。", "堪忍": "「堪忍（かんにん）」。二拍目「く」が「ん」に変わる一モーラ差。", "革新": "「革新（かくしん）」。三拍目「に」が「し」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "確認"}, "level_3": {"options": [{"text": "確認", "is_correct": true, "explanation": "正解。文脈に合うのは「確認」。"}, {"text": "出発", "is_correct": false, "explanation": "項構造：「内容を出発する」は非文。"}, {"text": "到着", "is_correct": false, "explanation": "項構造：「内容を到着する」は非文。"}, {"text": "入院", "is_correct": false, "explanation": "項構造：「内容を入院する」は非文。"}], "explanations": {"確認": "正解。文脈に合うのは「確認」。", "出発": "項構造：「内容を出発する」は非文。", "到着": "項構造：「内容を到着する」は非文。", "入院": "項構造：「内容を入院する」は非文。"}, "sentence_index": 6, "correct_answer": "確認"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地図が道を確認しながら歩いた。", "explanation": "助詞の混同：手段は「で」で示す。"}, {"text": "地図で道を確認したながら歩いた。", "explanation": "活用の誤り：「ながら」は連用形に付く。"}, {"text": "歩いた地図で道を確認しながら。", "explanation": "語順の誤り：述語が文頭に来ている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
