INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52382, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "個性", "is_correct": true, "explanation": "正解。「個性（こせい）」。"}, {"text": "規制", "is_correct": false, "explanation": "「規制（きせい）」。一拍目「こ」が「き」に変わる一モーラ差。"}, {"text": "威勢", "is_correct": false, "explanation": "「威勢（いせい）」。一拍目「こ」が「い」に変わる一モーラ差。"}, {"text": "公正", "is_correct": false, "explanation": "「公正（こうせい）」。一拍目が長音「こう」になる長短の対立。"}], "explanations": {"個性": "正解。「個性（こせい）」。", "規制": "「規制（きせい）」。一拍目「こ」が「き」に変わる一モーラ差。", "威勢": "「威勢（いせい）」。一拍目「こ」が「い」に変わる一モーラ差。", "公正": "「公正（こうせい）」。一拍目が長音「こう」になる長短の対立。"}, "sentence_index": null, "correct_answer": "個性"}, "level_3": {"options": [{"text": "個性", "is_correct": true, "explanation": "正解。文脈に合うのは「個性」。"}, {"text": "天井", "is_correct": false, "explanation": "意味：「一人一人の天井が違う」は意味をなさない。"}, {"text": "曜日", "is_correct": false, "explanation": "意味：曜日は一人一人で違うものではない。"}, {"text": "天気", "is_correct": false, "explanation": "意味：「一人一人の天気」は意味をなさない。"}], "explanations": {"個性": "正解。文脈に合うのは「個性」。", "天井": "意味：「一人一人の天井が違う」は意味をなさない。", "曜日": "意味：曜日は一人一人で違うものではない。", "天気": "意味：「一人一人の天気」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "個性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "犬にもそれぞれ個性をある。", "explanation": "助詞の混同：「ある」の主語は「が」。"}, {"text": "犬にもそれぞれ個性がいる。", "explanation": "語の誤り：「個性」は無生物なので「ある」を使う。「いる」は不可。"}, {"text": "犬にもそれぞれ個性があっている。", "explanation": "活用の誤り：「ある」に「ている」は付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5959d2fe-4c1d-45a2-bb12-4cdc279b455b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
