INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52412, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "液体を容器に流し入れる。また、視線や心をある対象に集中させる。", "primary_collocate": null, "pronunciation": "そそぐ", "ipa": "sosoɡɯ", "syllable_count": 3, "sentences": [{"text": "陽だまりの縁側にて、幼き童子は陶器の鉢に植えられた一株の植物へと、無心なる眼差しを注いでいる。", "target_word": "注い", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "彼は畏敬の念にも似た慎ましやかな所作で、乾いた土の表面へとそれを静かに注ぎ下ろす。", "target_word": "注ぎ", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "しかし、窓辺に佇む幼き我が子の瞳は、白銀に覆われた庭先へと注がれ、抑えきれない生命の衝動に駆られていた。", "target_word": "注が", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "コップにお茶を注ぐ。", "target_word": "注ぐ", "complexity_tier": "T3", "furigana": "そそぐ", "sentence_source": "generated"}, {"text": "母がスープを皿に注いだ。", "target_word": "注い", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "花に水を注いでいる。", "target_word": "注い", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "みんなの目が彼に注がれた。", "target_word": "注が", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "熱いお湯を注ぐと危ない。", "target_word": "注ぐ", "complexity_tier": "T3", "furigana": "そそぐ", "sentence_source": "generated"}, {"text": "彼は勉強に力を注いでいる。", "target_word": "注い", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "注いだ牛乳がこぼれた。", "target_word": "注い", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [{"form": "注いだ", "label": "活用"}, {"form": "注いで", "label": "活用"}, {"form": "注がない", "label": "活用"}, {"form": "注がれる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 液体や視線を対象へ流し向ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for thi