INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52850, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "永続", "is_correct": true, "explanation": "音声は「えいぞく」。"}, {"text": "映像", "is_correct": false, "explanation": "「えいぞう」と読み、一拍だけ違う別の語。"}, {"text": "海賊", "is_correct": false, "explanation": "「かいぞく」と読み、一拍だけ違う別の語。"}, {"text": "隷属", "is_correct": false, "explanation": "「れいぞく」と読み、一拍だけ違う別の語。"}, {"text": "配属", "is_correct": false, "explanation": "「はいぞく」と読み、一拍だけ違う別の語。"}], "explanations": {"永続": "音声は「えいぞく」。", "映像": "「えいぞう」と読み、一拍だけ違う別の語。", "海賊": "「かいぞく」と読み、一拍だけ違う別の語。", "隷属": "「れいぞく」と読み、一拍だけ違う別の語。", "配属": "「はいぞく」と読み、一拍だけ違う別の語。"}, "sentence_index": null, "correct_answer": "永続"}, "level_3": {"options": [{"text": "永続", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "一時", "is_correct": false, "explanation": "意味：一時的では記憶を強固にする文脈と矛盾する。"}, {"text": "偶発", "is_correct": false, "explanation": "意味：偶然起こる意で、記憶を変える方向として不自然。"}, {"text": "表面", "is_correct": false, "explanation": "連語：表面的なものでは昇華させる文脈に合わない。"}], "explanations": {"永続": "文脈に合う正しい語。", "一時": "意味：一時的では記憶を強固にする文脈と矛盾する。", "偶発": "意味：偶然起こる意で、記憶を変える方向として不自然。", "表面": "連語：表面的なものでは昇華させる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "永続"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "平和が永続を願っている。", "explanation": "助詞の混同：願う対象は「を」で示し、主語は人である。"}, {"text": "永続な関係を作りたい。", "explanation": "形の誤り：連体修飾には「永続的な」を使い、「永続な」とは言わない。"}, {"text": "この効果は永続したないそうだ。", "explanation": "活用の誤り：「永続しない」が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f37743ce-4f94-4965-b024-409a6e64b655') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_