INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36147, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "目に映る。視覚で認識できる状態にある。", "primary_collocate": null, "pronunciation": "みえる", "ipa": "mieɾɯ", "syllable_count": 3, "sentences": [{"text": "水は瞬く間に闇色の大地へと吸い込まれ、やがて目に見えぬ根の網目へと伝わっていくだろう。", "target_word": "見え", "complexity_tier": "T3", "furigana": "み", "sentence_source": "mined"}, {"text": "指先を通じて伝わる生地の微妙な弾力や発酵の進行具合を唯一の羅針盤とし、彼は温度と湿度という変数を緻密に制御することで、微生物という目に見えぬパートナーとの静かなる対話を試みる。", "target_word": "見え", "complexity_tier": "T3", "furigana": "み", "sentence_source": "mined"}, {"text": "窓から富士山がよく見える。", "target_word": "見える", "complexity_tier": "T3", "furigana": "まど ふじさん み", "sentence_source": "generated"}, {"text": "暗くて前が何も見えない。", "target_word": "見え", "complexity_tier": "T3", "furigana": "くら まえ なに み", "sentence_source": "generated"}, {"text": "遠くに小さな島が見えてきた。", "target_word": "見え", "complexity_tier": "T3", "furigana": "とお ちい しま み", "sentence_source": "generated"}, {"text": "ここから見える海はとてもきれいだ。", "target_word": "見える", "complexity_tier": "T3", "furigana": "み うみ", "sentence_source": "generated"}, {"text": "眼鏡をかけると字がはっきり見える。", "target_word": "見える", "complexity_tier": "T3", "furigana": "めがね じ み", "sentence_source": "generated"}, {"text": "霧で山の頂上が見えなかった。", "target_word": "見え", "complexity_tier": "T3", "furigana": "きり やま ちょうじょう み", "sentence_source": "generated"}, {"text": "星が見える夜に散歩した。", "target_word": "見える", "complexity_tier": "T3", "furigana": "ほし み よる さんぽ", "sentence_source": "generated"}, {"text": "教室の後ろからでも黒板が見えます。", "target_word": "見え", "complexity_tier": "T3", "furigana": "きょうしつ うし こくばん み", "sentence_source": "generated"}], "morphological_forms": [{"form": "見えた", "label": "活用"}, {"form": "見えて", "label": "活用"}, {"form": "見えない", "label": "活用"}, {"form": "見え方", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 物が目に映り視覚で認識できる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 瞬く (Zipf 3.21), 吸い込ま (Zipf 3.35), 網目 (Zipf 2.67)','sentence 1 above tier T1: 10 words above tier T1 (max 2): 指先 (Zipf 3.6), 生地 (Zipf 3.93), 弾力 (Zipf 3.23), 発酵 (Zipf 3.73), 羅針盤 (Zipf 3.09), 湿度 (Zipf 3.81)']::text[], '37890ce6-5c8d-466c-9024-e7b599e72d5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39227, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "植物の根を土の中に入れて、そこから成長させること。", "primary_collocate": null, "pronunciation": "うえる", "ipa": "ɯeɾɯ", "syllable_count": 3, "sentences": [{"text": "陽だまりの縁側にて、幼き童子は陶器の鉢に植えられた一株の植物へと、無心なる眼差しを注いでいる。", "target_word": "植え", "complexity_tier": "T3", "furigana": "う", "sentence_source": "mined"}, {"text": "経験豊富な農家は、広大な畑の土壌を丁寧に耕し、野菜の種を植える。", "target_word": "植える", "complexity_tier": "T3", "furigana": "う", "sentence_source": "mined"}, {"text": "春になったら庭に花を植えよう。", "target_word": "植え", "complexity_tier": "T3", "furigana": "はる にわ はな う", "sentence_source": "generated"}, {"text": "祖父と一緒に桜の木を植えた。", "target_word": "植え", "complexity_tier": "T3", "furigana": "そふ いっしょ さくら き う", "sentence_source": "generated"}, {"text": "学校の花壇にチューリップを植えている。", "target_word": "植え", "complexity_tier": "T3", "furigana": "がっこう かだん う", "sentence_source": "generated"}, {"text": "植えたばかりの苗に水をやる。", "target_word": "植え", "complexity_tier": "T3", "furigana": "う なえ みず", "sentence_source": "generated"}, {"text": "この木は十年前に父が植えたものだ。", "target_word": "植え", "complexity_tier": "T3", "furigana": "き じゅうねんまえ ちち う", "sentence_source": "generated"}, {"text": "トマトを植える時期はいつですか。", "target_word": "植える", "complexity_tier": "T3", "furigana": "う じき", "sentence_source": "generated"}, {"text": "道に沿って木が植えられている。", "target_word": "植え", "complexity_tier": "T3", "furigana": "みち そ き う", "sentence_source": "generated"}, {"text": "鉢に植えた種から芽が出た。", "target_word": "植え", "complexity_tier": "T3", "furigana": "はち う たね め で", "sentence_source": "generated"}], "morphological_forms": [{"form": "植えた", "label": "活用"}, {"form": "植えて", "label": "活用"}, {"form": "植えられる", "label": "活用"}, {"form": "植木", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 植物の根や種を土に入れて育てる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37890ce6-5c8d-466c-9024-e7b599e72d5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35159, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "情報や気持ち、振動などが、人や物の間を移って相手や先に届くこと。また、受け継がれること。", "primary_collocate": null, "pronunciation": "つたわる", "ipa": "tsɯtawaɾɯ", "syllable_count": 4, "sentences": [{"text": "水は瞬く間に闇色の大地へと吸い込まれ、やがて目に見えぬ根の網目へと伝わっていくだろう。", "target_word": "伝わっ", "complexity_tier": "T3", "furigana": "つた", "sentence_source": "mined"}, {"text": "指先を通じて伝わる生地の微妙な弾力や発酵の進行具合を唯一の羅針盤とし、彼は温度と湿度という変数を緻密に制御することで、微生物という目に見えぬパートナーとの静かなる対話を試みる。", "target_word": "伝わる", "complexity_tier": "T3", "furigana": "つた", "sentence_source": "mined"}, {"text": "彼の気持ちがみんなに伝わった。", "target_word": "伝わっ", "complexity_tier": "T3", "furigana": "かれ きも つた", "sentence_source": "generated"}, {"text": "このお祭りは昔から村に伝わっている。", "target_word": "伝わっ", "complexity_tier": "T3", "furigana": "まつ むかし むら つた", "sentence_source": "generated"}, {"text": "言いたいことがうまく伝わらない。", "target_word": "伝わ", "complexity_tier": "T3", "furigana": "い つた", "sentence_source": "generated"}, {"text": "ニュースはすぐに町中に伝わった。", "target_word": "伝わっ", "complexity_tier": "T3", "furigana": "まちじゅう つた", "sentence_source": "generated"}, {"text": "床から電車の振動が伝わってくる。", "target_word": "伝わっ", "complexity_tier": "T3", "furigana": "ゆか でんしゃ しんどう つた", "sentence_source": "generated"}, {"text": "音は空気を通して伝わる。", "target_word": "伝わる", "complexity_tier": "T3", "furigana": "おと くうき とお つた", "sentence_source": "generated"}, {"text": "先生の熱意が生徒に伝わる授業だった。", "target_word": "伝わる", "complexity_tier": "T3", "furigana": "せんせい ねつい せいと つた じゅぎょう", "sentence_source": "generated"}, {"text": "手紙で感謝が伝わるといいな。", "target_word": "伝わる", "complexity_tier": "T3", "furigana": "てがみ かんしゃ つた", "sentence_source": "generated"}], "morphological_forms": [{"form": "伝わった", "label": "活用"}, {"form": "伝わって", "label": "活用"}, {"form": "伝わらない", "label": "活用"}, {"form": "伝える", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 物事や気持ちが移って相手や先に届く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37890ce6-5c8d-466c-9024-e7b599e72d5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52568, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "気高くて立派で、普通の人の考えや行いよりもずっとすぐれていること。また、そのさま。", "primary_collocate": null, "pronunciation": "すうこう", "ipa": "sɯːkoː", "syllable_count": 4, "sentences": [{"text": "童子の行為は、単なる日常的な営みの模倣を超え、生命の循環に対する原初的な祈りにも似た、崇高な儀式としてそこに刻まれるのである。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "すうこう", "sentence_source": "mined"}, {"text": "この製作の全工程は、まさに宇宙の理を机の上に縮図として描き出す、崇高な知的探究なのである。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "すうこう", "sentence_source": "mined"}, {"text": "彼は人を助けるという崇高な目標を持っている。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "かれ ひと たす すうこう もくひょう も", "sentence_source": "generated"}, {"text": "夜明けの山は崇高な美しさに満ちていた。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "よあ やま すうこう うつく み", "sentence_source": "generated"}, {"text": "その医師の生き方は崇高だと思う。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "いし い かた すうこう おも", "sentence_source": "generated"}, {"text": "平和を願う崇高な気持ちを忘れない。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "へいわ ねが すうこう きも わす", "sentence_source": "generated"}, {"text": "音楽の崇高さに心を打たれた。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "おんがく すうこう こころ う", "sentence_source": "generated"}, {"text": "自分を犠牲にする姿は崇高に見えた。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "じぶん ぎせい すがた すうこう み", "sentence_source": "generated"}, {"text": "彼女の理想はとても崇高だ。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "かのじょ りそう すうこう", "sentence_source": "generated"}, {"text": "教育は崇高な仕事だと言われる。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "きょういく すうこう しごと い", "sentence_source": "generated"}], "morphological_forms": [{"form": "崇高な", "label": "活用"}, {"form": "崇高だ", "label": "活用"}, {"form": "崇高さ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 気高く立派で尊いさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37890ce6-5c8d-466c-9024-e7b599e72d5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52066, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "日本の伝統的な家屋で、部屋と庭の間に設けられた細長い板敷きの廊下。", "primary_collocate": null, "pronunciation": "えんがわ", "ipa": "eŋɡawa", "syllable_count": 4, "sentences": [{"text": "陽だまりの縁側にて、幼き童子は陶器の鉢に植えられた一株の植物へと、無心なる眼差しを注いでいる。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "えんがわ", "sentence_source": "mined"}, {"text": "秋の気配が色濃く漂う古びた縁側にて、一人の幼子が無心なる眼差しを向けているのは、掌に収められた一つの赤い果物である。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "えんがわ", "sentence_source": "mined"}, {"text": "祖母は縁側でお茶を飲んでいる。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "そぼ えんがわ ちゃ の", "sentence_source": "generated"}, {"text": "夏は縁側に座ってスイカを食べた。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "なつ えんがわ すわ た", "sentence_source": "generated"}, {"text": "縁側から庭の花がよく見える。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "えんがわ にわ はな み", "sentence_source": "generated"}, {"text": "猫が縁側で昼寝をしている。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "ねこ えんがわ ひるね", "sentence_source": "generated"}, {"text": "この家には広い縁側がある。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "いえ ひろ えんがわ", "sentence_source": "generated"}, {"text": "雨の日は縁側で本を読む。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "あめ ひ えんがわ ほん よ", "sentence_source": "generated"}, {"text": "縁側の床をぞうきんでふいた。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "えんがわ ゆか", "sentence_source": "generated"}, {"text": "古い縁側に秋の日が差している。", "target_word": "縁側", "complexity_tier": "T3", "furigana": "ふる えんがわ あき ひ さ", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 和室と庭の間の細長い板敷き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37890ce6-5c8d-466c-9024-e7b599e72d5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52072, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を見るときの、目の表情や視線。", "primary_collocate": null, "pronunciation": "まなざし", "ipa": "manazaɕi", "syllable_count": 4, "sentences": [{"text": "陽だまりの縁側にて、幼き童子は陶器の鉢に植えられた一株の植物へと、無心なる眼差しを注いでいる。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "まなざ", "sentence_source": "mined"}, {"text": "秋の気配が色濃く漂う古びた縁側にて、一人の幼子が無心なる眼差しを向けているのは、掌に収められた一つの赤い果物である。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "まなざ", "sentence_source": "mined"}, {"text": "母はやさしい眼差しで子どもを見た。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "はは まなざ こ み", "sentence_source": "generated"}, {"text": "彼の真剣な眼差しに驚いた。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "かれ しんけん まなざ おどろ", "sentence_source": "generated"}, {"text": "観客は熱い眼差しを舞台に向けた。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "かんきゃく あつ まなざ ぶたい む", "sentence_source": "generated"}, {"text": "その眼差しには不安が見えた。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "まなざ ふあん み", "sentence_source": "generated"}, {"text": "先生の温かい眼差しがうれしかった。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "せんせい あたた まなざ", "sentence_source": "generated"}, {"text": "少年は空に眼差しを向けている。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "しょうねん そら まなざ む", "sentence_source": "generated"}, {"text": "冷たい眼差しを感じて振り返った。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "つめ まなざ かん ふ かえ", "sentence_source": "generated"}, {"text": "祖父の眼差しはいつも穏やかだ。", "target_word": "眼差し", "complexity_tier": "T3", "furigana": "そふ まなざ おだ", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 物を見るときの目の表情や視線", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37890ce6-5c8d-466c-9024-e7b599e72d5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36147, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "見える", "is_correct": true, "explanation": "正解：「みえる」と読む対象語。"}, {"text": "消える", "is_correct": false, "explanation": "「きえる」と読む。一モーラ目「み」が「き」に変わる。"}, {"text": "冷える", "is_correct": false, "explanation": "「ひえる」と読む。一モーラ目「み」が「ひ」に変わる。"}, {"text": "見せる", "is_correct": false, "explanation": "「みせる」と読む。二モーラ目「え」が「せ」に変わる。"}, {"text": "生える", "is_correct": false, "explanation": "「はえる」と読む。一モーラ目「み」が「は」に変わる。"}], "explanations": {"見える": "正解：「みえる」と読む対象語。", "消える": "「きえる」と読む。一モーラ目「み」が「き」に変わる。", "冷える": "「ひえる」と読む。一モーラ目「み」が「ひ」に変わる。", "見せる": "「みせる」と読む。二モーラ目「え」が「せ」に変わる。", "生える": "「はえる」と読む。一モーラ目「み」が「は」に変わる。"}, "sentence_index": null, "correct_answer": "見える"}, "level_3": {"options": [{"text": "見え", "is_correct": true, "explanation": "目で認識できないという意味で「目に見えぬ」となる。"}, {"text": "聞こえ", "is_correct": false, "explanation": "連語：「目に聞こえぬ」とは言わない。聞こえるのは耳である。"}, {"text": "生え", "is_correct": false, "explanation": "意味：根の網目が目に生えるのではない。"}, {"text": "冷え", "is_correct": false, "explanation": "意味：「目に冷えぬ」は意味をなさない。"}], "explanations": {"見え": "目で認識できないという意味で「目に見えぬ」となる。", "聞こえ": "連語：「目に聞こえぬ」とは言わない。聞こえるのは耳である。", "生え": "意味：根の網目が目に生えるのではない。", "冷え": "意味：「目に冷えぬ」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "見え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暗くて前を何も見えない。", "explanation": "助詞の混同：「見える」は自動詞なので対象は「が」で示す。"}, {"text": "暗くて前が何も見えている。", "explanation": "呼応の誤り：「何も」は否定と呼応するので「見えない」が必要。"}, {"text": "前が暗くて何も見えないだった。", "explanation": "活用の誤り：「見えない」に「だった」は付かない。「見えなかった」とする。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36147, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓から富士山をよく見える。", "corrected_sentence": "窓から富士山がよく見える。", "error_description": "「見える」は自動詞なので、見える対象は「を」ではなく「が」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "見え", "is_correct": true, "explanation": "打消の「ぬ」は未然形「見え」に付く。"}, {"text": "見える", "is_correct": false, "explanation": "辞書形には「ぬ」が付かない。"}, {"text": "見えた", "is_correct": false, "explanation": "た形の後に「ぬ」は続かない。"}, {"text": "見えて", "is_correct": false, "explanation": "て形の後に「ぬ」は続かない。"}], "correct_form": "見え", "base_form": "見える", "form_label": "未然形（ぬ接続）", "sentence_index": 1, "explanations": {"見え": "打消の「ぬ」は未然形「見え」に付く。", "見える": "辞書形には「ぬ」が付かない。", "見えた": "た形の後に「ぬ」は続かない。", "見えて": "て形の後に「ぬ」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36147, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「試みる」の目的語「対話」を示す。"}, {"text": "が", "is_correct": false, "explanation": "「対話が試みる」では対話が主語になり意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「試みる」は「に」で対象を取らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表し、ここでは非文になる。"}], "correct_answer": "を", "explanations": {"を": "他動詞「試みる」の目的語「対話」を示す。", "が": "「対話が試みる」では対話が主語になり意味が通らない。", "に": "「試みる」は「に」で対象を取らない。", "で": "手段や場所を表し、ここでは非文になる。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36147, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "見える", "is_correct": true, "explanation": "正解：「みえる」と読む対象語。"}, {"text": "燃える", "is_correct": false, "explanation": "「もえる」と読む。一モーラ目「み」が「も」に変わる。"}, {"text": "吠える", "is_correct": false, "explanation": "「ほえる」と読む。一モーラ目「み」が「ほ」に変わる。"}, {"text": "増える", "is_correct": false, "explanation": "「ふえる」と読む。一モーラ目「み」が「ふ」に変わる。"}, {"text": "見せる", "is_correct": false, "explanation": "「みせる」と読む。二モーラ目「え」が「せ」に変わる。"}], "explanations": {"見える": "正解：「みえる」と読む対象語。", "燃える": "「もえる」と読む。一モーラ目「み」が「も」に変わる。", "吠える": "「ほえる」と読む。一モーラ目「み」が「ほ」に変わる。", "増える": "「ふえる」と読む。一モーラ目「み」が「ふ」に変わる。", "見せる": "「みせる」と読む。二モーラ目「え」が「せ」に変わる。"}, "sentence_index": null, "correct_answer": "見える"}, "level_3": {"options": [{"text": "見える", "is_correct": true, "explanation": "眼鏡で字が目にはっきり映るので「見える」。"}, {"text": "聞こえる", "is_correct": false, "explanation": "連語：字は耳で聞くものではない。"}, {"text": "消える", "is_correct": false, "explanation": "意味：眼鏡をかけて字が消えるのは不自然。"}, {"text": "増える", "is_correct": false, "explanation": "意味：眼鏡で字の数が増えることはない。"}], "explanations": {"見える": "眼鏡で字が目にはっきり映るので「見える」。", "聞こえる": "連語：字は耳で聞くものではない。", "消える": "意味：眼鏡をかけて字が消えるのは不自然。", "増える": "意味：眼鏡で字の数が増えることはない。"}, "sentence_index": 6, "correct_answer": "見える"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室の後ろからでも黒板を見えます。", "explanation": "助詞の混同：自動詞「見える」の対象は「が」で示す。"}, {"text": "教室の後ろからでも黒板が見えてあります。", "explanation": "アスペクトの誤り：「てある」は他動詞に付く形で、「見える」には使えない。"}, {"text": "黒板が教室の後ろからでも見えますでした。", "explanation": "活用の誤り：「見えます」の過去は「見えました」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36147, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "霧で山の頂上を見えなかった。", "corrected_sentence": "霧で山の頂上が見えなかった。", "error_description": "自動詞「見える」の主語は「を」ではなく「が」で示す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "見え", "is_correct": true, "explanation": "否定の「なかった」は未然形「見え」に付く。"}, {"text": "見えろ", "is_correct": false, "explanation": "命令形の後に「なかった」は続かない。"}, {"text": "見えよう", "is_correct": false, "explanation": "意向形の後に「なかった」は続かない。"}, {"text": "見えれば", "is_correct": false, "explanation": "仮定形の後に「なかった」は続かない。"}], "correct_form": "見え", "base_form": "見える", "form_label": "未然形（ない接続）", "sentence_index": 7, "explanations": {"見え": "否定の「なかった」は未然形「見え」に付く。", "見えろ": "命令形の後に「なかった」は続かない。", "見えよう": "意向形の後に「なかった」は続かない。", "見えれば": "仮定形の後に「なかった」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36147, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "自動詞「見える」の主語（見える物）を示す。"}, {"text": "を", "is_correct": false, "explanation": "「見える」は自動詞なので「を」は取れない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、見える対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「頂上に見えなかった」は見える物を示さず不自然。"}], "correct_answer": "が", "explanations": {"が": "自動詞「見える」の主語（見える物）を示す。", "を": "「見える」は自動詞なので「を」は取れない。", "へ": "方向を表し、見える対象を示せない。", "に": "「頂上に見えなかった」は見える物を示さず不自然。"}, "error_tags": {"を": "object_marking", "へ": "direction", "に": "location_vs_target"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39227, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "植える", "is_correct": true, "explanation": "正解：「うえる」と読む対象語。"}, {"text": "終える", "is_correct": false, "explanation": "「おえる」と読む。一モーラ目「う」が「お」に変わる。"}, {"text": "受ける", "is_correct": false, "explanation": "「うける」と読む。二モーラ目「え」が「け」に変わる。"}, {"text": "埋める", "is_correct": false, "explanation": "「うめる」と読む。二モーラ目「え」が「め」に変わる。"}, {"text": "消える", "is_correct": false, "explanation": "「きえる」と読む。一モーラ目「う」が「き」に変わる。"}], "explanations": {"植える": "正解：「うえる」と読む対象語。", "終える": "「おえる」と読む。一モーラ目「う」が「お」に変わる。", "受ける": "「うける」と読む。二モーラ目「え」が「け」に変わる。", "埋める": "「うめる」と読む。二モーラ目「え」が「め」に変わる。", "消える": "「きえる」と読む。一モーラ目「う」が「き」に変わる。"}, "sentence_index": null, "correct_answer": "植える"}, "level_3": {"options": [{"text": "植え", "is_correct": true, "explanation": "植物を鉢の土に入れたので「植えられた」。"}, {"text": "食べ", "is_correct": false, "explanation": "意味：鉢に食べられた植物は不自然。"}, {"text": "教え", "is_correct": false, "explanation": "項構造：植物は「教えられる」対象にならない。"}, {"text": "建て", "is_correct": false, "explanation": "連語：「建てる」は建物に使い、植物には使わない。"}], "explanations": {"植え": "植物を鉢の土に入れたので「植えられた」。", "食べ": "意味：鉢に食べられた植物は不自然。", "教え": "項構造：植物は「教えられる」対象にならない。", "建て": "連語：「建てる」は建物に使い、植物には使わない。"}, "sentence_index": 0, "correct_answer": "植え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父と一緒に桜の木が植えた。", "explanation": "助詞の混同：他動詞「植える」の対象は「を」で示す。"}, {"text": "祖父と一緒に桜の木を植えるた。", "explanation": "活用の誤り：過去形は「植えた」で、辞書形に「た」は付かない。"}, {"text": "一冊の桜の木を祖父と一緒に植えた。", "explanation": "助数詞の誤り：木は「冊」ではなく「本」で数える。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39227, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春になったら庭が花を植えよう。", "corrected_sentence": "春になったら庭に花を植えよう。", "error_description": "植える場所は「が」ではなく「に」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "植える", "is_correct": true, "explanation": "文末で習慣的な行為を述べる辞書形。"}, {"text": "植えて", "is_correct": false, "explanation": "て形では文が終わらない。"}, {"text": "植えれば", "is_correct": false, "explanation": "仮定形では文が完結しない。"}, {"text": "植えろ", "is_correct": false, "explanation": "命令形は農家の行為の描写に合わない。"}], "correct_form": "植える", "base_form": "植える", "form_label": "辞書形（終止形）", "sentence_index": 1, "explanations": {"植える": "文末で習慣的な行為を述べる辞書形。", "植えて": "て形では文が終わらない。", "植えれば": "仮定形では文が完結しない。", "植えろ": "命令形は農家の行為の描写に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39227, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「植える」の目的語「種」を示す。"}, {"text": "が", "is_correct": false, "explanation": "「種が植える」では種が動作主になり誤り。"}, {"text": "に", "is_correct": false, "explanation": "「種に植える」は植える物を示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では植える物を示せない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「植える」の目的語「種」を示す。", "が": "「種が植える」では種が動作主になり誤り。", "に": "「種に植える」は植える物を示せない。", "で": "手段の「で」では植える物を示せない。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "抜く", "is_correct": true, "explanation": "植えた植物を土から取り出すことで、植えるの反対。"}, {"text": "耕す", "is_correct": false, "explanation": "植える前に土を掘り返すことで、反対ではない。"}, {"text": "育てる", "is_correct": false, "explanation": "植えた後の世話で、反対ではない。"}, {"text": "埋める", "is_correct": false, "explanation": "土に入れる点で近く、反対ではない。"}], "correct_answer": "抜く", "explanations": {"抜く": "植えた植物を土から取り出すことで、植えるの反対。", "耕す": "植える前に土を掘り返すことで、反対ではない。", "育てる": "植えた後の世話で、反対ではない。", "埋める": "土に入れる点で近く、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39227, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "植える", "is_correct": true, "explanation": "正解：「うえる」と読む対象語。"}, {"text": "売れる", "is_correct": false, "explanation": "「うれる」と読む。二モーラ目「え」が「れ」に変わる。"}, {"text": "増える", "is_correct": false, "explanation": "「ふえる」と読む。一モーラ目「う」が「ふ」に変わる。"}, {"text": "生える", "is_correct": false, "explanation": "「はえる」と読む。一モーラ目「う」が「は」に変わる。"}, {"text": "冷える", "is_correct": false, "explanation": "「ひえる」と読む。一モーラ目「う」が「ひ」に変わる。"}], "explanations": {"植える": "正解：「うえる」と読む対象語。", "売れる": "「うれる」と読む。二モーラ目「え」が「れ」に変わる。", "増える": "「ふえる」と読む。一モーラ目「う」が「ふ」に変わる。", "生える": "「はえる」と読む。一モーラ目「う」が「は」に変わる。", "冷える": "「ひえる」と読む。一モーラ目「う」が「ひ」に変わる。"}, "sentence_index": null, "correct_answer": "植える"}, "level_3": {"options": [{"text": "植え", "is_correct": true, "explanation": "父が木を土に入れたので「植えた」。"}, {"text": "見え", "is_correct": false, "explanation": "項構造：「父が見えた」では木を植えた意味にならない。"}, {"text": "生え", "is_correct": false, "explanation": "項構造：「生える」は自動詞で「父が」と合わない。"}, {"text": "枯れ", "is_correct": false, "explanation": "意味：父が枯れたのではない。"}], "explanations": {"植え": "父が木を土に入れたので「植えた」。", "見え": "項構造：「父が見えた」では木を植えた意味にならない。", "生え": "項構造：「生える」は自動詞で「父が」と合わない。", "枯れ": "意味：父が枯れたのではない。"}, "sentence_index": 6, "correct_answer": "植え"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鉢を植えた種から芽が出た。", "explanation": "助詞の混同：植える場所は「を」ではなく「に」で示す。"}, {"text": "鉢に植えった種から芽が出た。", "explanation": "活用の誤り：一段動詞「植える」のた形は「植えた」で、促音は入らない。"}, {"text": "芽が出た鉢に種から植えた。", "explanation": "語順・係り受けの誤り：因果関係が崩れ意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39227, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この木は十年前に父を植えたものだ。", "corrected_sentence": "この木は十年前に父が植えたものだ。", "error_description": "植えた人（動作主）は「を」ではなく「が」で示す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "植える", "is_correct": true, "explanation": "名詞「時期」を修飾する連体形。"}, {"text": "植えよう", "is_correct": false, "explanation": "意向形は名詞を直接修飾できない。"}, {"text": "植えます", "is_correct": false, "explanation": "丁寧形は通常名詞を修飾しない。"}, {"text": "植えなさい", "is_correct": false, "explanation": "命令の形は名詞を修飾できない。"}], "correct_form": "植える", "base_form": "植える", "form_label": "連体形（辞書形）", "sentence_index": 7, "explanations": {"植える": "名詞「時期」を修飾する連体形。", "植えよう": "意向形は名詞を直接修飾できない。", "植えます": "丁寧形は通常名詞を修飾しない。", "植えなさい": "命令の形は名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39227, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「植える」の目的語「トマト」を示す。"}, {"text": "に", "is_correct": false, "explanation": "「トマトに植える」では植える物を示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」は目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「植える」の目的語「トマト」を示す。", "に": "「トマトに植える」では植える物を示せない。", "で": "手段・場所の「で」は目的語にならない。", "へ": "方向を表し、目的語にならない。"}, "error_tags": {"に": "location_vs_target", "で": "instrument", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "引き抜く", "is_correct": true, "explanation": "土に植わったものを引っぱって取り出すことで、植えるの反対。"}, {"text": "撒く", "is_correct": false, "explanation": "種を散らすことで、反対ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移すことで、反対関係にない。"}, {"text": "掘る", "is_correct": false, "explanation": "土に穴をあけることで、反対ではない。"}], "correct_answer": "引き抜く", "explanations": {"引き抜く": "土に植わったものを引っぱって取り出すことで、植えるの反対。", "撒く": "種を散らすことで、反対ではない。", "運ぶ": "物を移すことで、反対関係にない。", "掘る": "土に穴をあけることで、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35159, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "伝わる", "is_correct": true, "explanation": "正解：「つたわる」と読む対象語。"}, {"text": "いたわる", "is_correct": false, "explanation": "「いたわる」と読む。一モーラ目「つ」が「い」に変わる。労る：大切に扱うこと。"}, {"text": "伝える", "is_correct": false, "explanation": "「つたえる」と読む。三モーラ目「わ」が「え」に変わる。他動詞の別語。"}, {"text": "こだわる", "is_correct": false, "explanation": "「こだわる」と読む。「つ」が「こ」、「た」が「だ」に変わる近い音。"}], "explanations": {"伝わる": "正解：「つたわる」と読む対象語。", "いたわる": "「いたわる」と読む。一モーラ目「つ」が「い」に変わる。労る：大切に扱うこと。", "伝える": "「つたえる」と読む。三モーラ目「わ」が「え」に変わる。他動詞の別語。", "こだわる": "「こだわる」と読む。「つ」が「こ」、「た」が「だ」に変わる近い音。"}, "sentence_index": null, "correct_answer": "伝わる"}, "level_3": {"options": [{"text": "伝わっ", "is_correct": true, "explanation": "水が根の網目まで移って届いていくので「伝わっていく」。"}, {"text": "座っ", "is_correct": false, "explanation": "意味：水が座ることはない。"}, {"text": "習っ", "is_correct": false, "explanation": "項構造：「習う」は対象を必要とし、水は習わない。"}, {"text": "怒っ", "is_correct": false, "explanation": "意味：水が怒るのは不自然。"}], "explanations": {"伝わっ": "水が根の網目まで移って届いていくので「伝わっていく」。", "座っ": "意味：水が座ることはない。", "習っ": "項構造：「習う」は対象を必要とし、水は習わない。", "怒っ": "意味：水が怒るのは不自然。"}, "sentence_index": 0, "correct_answer": "伝わっ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このお祭りは昔から村を伝わっている。", "explanation": "助詞の混同：伝わる先は「を」ではなく「に」で示す。"}, {"text": "このお祭りは昔から村に伝わりている。", "explanation": "活用の誤り：「ている」はて形に付くので「伝わっている」とする。"}, {"text": "村に昔からこのお祭りは伝わってある。", "explanation": "アスペクトの誤り：「てある」は自動詞「伝わる」に付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35159, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の気持ちがみんなを伝わった。", "corrected_sentence": "彼の気持ちがみんなに伝わった。", "error_description": "伝わる相手は「を」ではなく「に」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "伝わる", "is_correct": true, "explanation": "名詞「生地の…」を修飾し、今伝わってくる感覚を表す。"}, {"text": "伝われ", "is_correct": false, "explanation": "命令形は名詞を修飾できない。"}, {"text": "伝わろう", "is_correct": false, "explanation": "意向形は名詞を修飾できない。"}, {"text": "伝わって", "is_correct": false, "explanation": "て形は名詞に直接かからない。"}], "correct_form": "伝わる", "base_form": "伝わる", "form_label": "連体形（辞書形）", "sentence_index": 1, "explanations": {"伝わる": "名詞「生地の…」を修飾し、今伝わってくる感覚を表す。", "伝われ": "命令形は名詞を修飾できない。", "伝わろう": "意向形は名詞を修飾できない。", "伝わって": "て形は名詞に直接かからない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35159, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「〜を通じて」の形で経由するものを示す。"}, {"text": "が", "is_correct": false, "explanation": "「指先が通じて」では経由の意味にならない。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手の「と」は経由を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点の「より」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「〜を通じて」の形で経由するものを示す。", "が": "「指先が通じて」では経由の意味にならない。", "と": "並列・相手の「と」は経由を示せない。", "より": "比較・起点の「より」は不自然。"}, "error_tags": {"が": "object_marking", "と": "other", "より": "source_vs_goal"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35159, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "伝わる", "is_correct": true, "explanation": "正解：「つたわる」と読む対象語。"}, {"text": "伝える", "is_correct": false, "explanation": "「つたえる」と読む。三モーラ目「わ」が「え」に変わる。他動詞の別語。"}, {"text": "かかわる", "is_correct": false, "explanation": "「かかわる」と読む。関わる：関係をもつこと。一・二モーラ目が異なる近い音。"}, {"text": "くわわる", "is_correct": false, "explanation": "「くわわる」と読む。加わる：仲間に入ること。一・二モーラ目が異なる近い音。"}], "explanations": {"伝わる": "正解：「つたわる」と読む対象語。", "伝える": "「つたえる」と読む。三モーラ目「わ」が「え」に変わる。他動詞の別語。", "かかわる": "「かかわる」と読む。関わる：関係をもつこと。一・二モーラ目が異なる近い音。", "くわわる": "「くわわる」と読む。加わる：仲間に入ること。一・二モーラ目が異なる近い音。"}, "sentence_index": null, "correct_answer": "伝わる"}, "level_3": {"options": [{"text": "伝わっ", "is_correct": true, "explanation": "振動が床を通して届くので「伝わってくる」。"}, {"text": "太っ", "is_correct": false, "explanation": "意味：振動が太るのは不自然。"}, {"text": "謝っ", "is_correct": false, "explanation": "意味：振動は謝らない。"}, {"text": "笑っ", "is_correct": false, "explanation": "意味：振動は笑わない。"}], "explanations": {"伝わっ": "振動が床を通して届くので「伝わってくる」。", "太っ": "意味：振動が太るのは不自然。", "謝っ": "意味：振動は謝らない。", "笑っ": "意味：振動は笑わない。"}, "sentence_index": 6, "correct_answer": "伝わっ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手紙で感謝を伝わるといいな。", "explanation": "助詞の混同：自動詞「伝わる」の主語は「が」で示す。"}, {"text": "手紙で感謝が伝わっるといいな。", "explanation": "活用の誤り：辞書形は「伝わる」で、促音は入らない。"}, {"text": "感謝が手紙で伝わってあるといいな。", "explanation": "アスペクトの誤り：「てある」は自動詞に付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35159, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "音は空気を通して伝える。", "corrected_sentence": "音は空気を通して伝わる。", "error_description": "音が主語の自動詞文なので、他動詞「伝える」ではなく「伝わる」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "伝わる", "is_correct": true, "explanation": "一般的な事実を述べる文末の辞書形。"}, {"text": "伝わり", "is_correct": false, "explanation": "連用形だけでは文が終わらない。"}, {"text": "伝われば", "is_correct": false, "explanation": "仮定形では文が完結しない。"}, {"text": "伝わりながら", "is_correct": false, "explanation": "「ながら」の形では文が終わらない。"}], "correct_form": "伝わる", "base_form": "伝わる", "form_label": "辞書形（終止形）", "sentence_index": 7, "explanations": {"伝わる": "一般的な事実を述べる文末の辞書形。", "伝わり": "連用形だけでは文が終わらない。", "伝われば": "仮定形では文が完結しない。", "伝わりながら": "「ながら」の形では文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35159, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「〜を通して」の形で経由するものを示す。"}, {"text": "が", "is_correct": false, "explanation": "「空気が通して」では経由の意味にならない。"}, {"text": "に", "is_correct": false, "explanation": "「空気に通して」は経由を表さず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「空気で通して」は非文。"}], "correct_answer": "を", "explanations": {"を": "「〜を通して」の形で経由するものを示す。", "が": "「空気が通して」では経由の意味にならない。", "に": "「空気に通して」は経由を表さず不自然。", "で": "「空気で通して」は非文。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52568, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "崇高", "is_correct": true, "explanation": "正解：「すうこう」と読む対象語。"}, {"text": "遂行", "is_correct": false, "explanation": "「すいこう」と読む。二モーラ目「う」が「い」に変わる。"}, {"text": "空港", "is_correct": false, "explanation": "「くうこう」と読む。一モーラ目「す」が「く」に変わる。"}, {"text": "通行", "is_correct": false, "explanation": "「つうこう」と読む。一モーラ目「す」が「つ」に変わる。"}, {"text": "走行", "is_correct": false, "explanation": "「そうこう」と読む。一モーラ目「す」が「そ」に変わる。"}], "explanations": {"崇高": "正解：「すうこう」と読む対象語。", "遂行": "「すいこう」と読む。二モーラ目「う」が「い」に変わる。", "空港": "「くうこう」と読む。一モーラ目「す」が「く」に変わる。", "通行": "「つうこう」と読む。一モーラ目「す」が「つ」に変わる。", "走行": "「そうこう」と読む。一モーラ目「す」が「そ」に変わる。"}, "sentence_index": null, "correct_answer": "崇高"}, "level_3": {"options": [{"text": "崇高", "is_correct": true, "explanation": "生命への祈りに似た気高い儀式なので「崇高な」。"}, {"text": "便利", "is_correct": false, "explanation": "意味：儀式の気高さを表さない。"}, {"text": "安価", "is_correct": false, "explanation": "意味：値段の話で文脈に合わない。"}, {"text": "新鮮", "is_correct": false, "explanation": "連語：儀式を「新鮮な」と形容するのは不自然。"}], "explanations": {"崇高": "生命への祈りに似た気高い儀式なので「崇高な」。", "便利": "意味：儀式の気高さを表さない。", "安価": "意味：値段の話で文脈に合わない。", "新鮮": "連語：儀式を「新鮮な」と形容するのは不自然。"}, "sentence_index": 0, "correct_answer": "崇高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜明けの山は崇高の美しさに満ちていた。", "explanation": "活用の誤り：形状詞は名詞を修飾するとき「の」ではなく「な」を使う。"}, {"text": "夜明けの山を崇高な美しさに満ちていた。", "explanation": "助詞の混同：主題は「を」ではなく「は」で示す。"}, {"text": "夜明けの山は崇高だ美しさに満ちていた。", "explanation": "活用の誤り：名詞を修飾するときは「崇高だ」ではなく「崇高な」とする。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52568, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は人を助けるという崇高い目標を持っている。", "corrected_sentence": "彼は人を助けるという崇高な目標を持っている。", "error_description": "「崇高」は形状詞なので「崇高い」ではなく「崇高な」とする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "崇高", "is_correct": true, "explanation": "形状詞は語幹に「な」を付けて名詞を修飾する。"}, {"text": "崇高さ", "is_correct": false, "explanation": "名詞形で、後に「な」は続かない。"}, {"text": "崇高だ", "is_correct": false, "explanation": "終止形で、後に「な」は続かない。"}, {"text": "崇高に", "is_correct": false, "explanation": "連用形で、後に「な」は続かない。"}], "correct_form": "崇高", "base_form": "崇高", "form_label": "語幹（な接続）", "sentence_index": 1, "explanations": {"崇高": "形状詞は語幹に「な」を付けて名詞を修飾する。", "崇高さ": "名詞形で、後に「な」は続かない。", "崇高だ": "終止形で、後に「な」は続かない。", "崇高に": "連用形で、後に「な」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52568, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "卑俗", "is_correct": true, "explanation": "下品で俗っぽいことで、崇高の対義語。"}, {"text": "高尚", "is_correct": false, "explanation": "気高く上品なことで、類義であり反対ではない。"}, {"text": "偉大", "is_correct": false, "explanation": "すぐれて大きいことで、反対ではない。"}, {"text": "神聖", "is_correct": false, "explanation": "清らかで尊いことで、反対ではない。"}], "correct_answer": "卑俗", "explanations": {"卑俗": "下品で俗っぽいことで、崇高の対義語。", "高尚": "気高く上品なことで、類義であり反対ではない。", "偉大": "すぐれて大きいことで、反対ではない。", "神聖": "清らかで尊いことで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52568, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "崇高", "is_correct": true, "explanation": "正解：「すうこう」と読む対象語。"}, {"text": "就航", "is_correct": false, "explanation": "「しゅうこう」と読む。一モーラ目「す」が「しゅ」に変わる。"}, {"text": "推敲", "is_correct": false, "explanation": "「すいこう」と読む。二モーラ目「う」が「い」に変わる。"}, {"text": "草稿", "is_correct": false, "explanation": "「そうこう」と読む。一モーラ目「す」が「そ」に変わる。"}, {"text": "空港", "is_correct": false, "explanation": "「くうこう」と読む。一モーラ目「す」が「く」に変わる。"}], "explanations": {"崇高": "正解：「すうこう」と読む対象語。", "就航": "「しゅうこう」と読む。一モーラ目「す」が「しゅ」に変わる。", "推敲": "「すいこう」と読む。二モーラ目「う」が「い」に変わる。", "草稿": "「そうこう」と読む。一モーラ目「す」が「そ」に変わる。", "空港": "「くうこう」と読む。一モーラ目「す」が「く」に変わる。"}, "sentence_index": null, "correct_answer": "崇高"}, "level_3": {"options": [{"text": "崇高", "is_correct": true, "explanation": "心を打つ気高さなので「崇高さ」。"}, {"text": "不便", "is_correct": false, "explanation": "意味：音楽の不便さに感動するのは不自然。"}, {"text": "安価", "is_correct": false, "explanation": "意味：値段の話で文脈に合わない。"}, {"text": "乱雑", "is_correct": false, "explanation": "連語：「心を打たれた」と合わない。"}], "explanations": {"崇高": "心を打つ気高さなので「崇高さ」。", "不便": "意味：音楽の不便さに感動するのは不自然。", "安価": "意味：値段の話で文脈に合わない。", "乱雑": "連語：「心を打たれた」と合わない。"}, "sentence_index": 6, "correct_answer": "崇高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教育は崇高の仕事だと言われる。", "explanation": "活用の誤り：形状詞は名詞の前で「な」になる。"}, {"text": "教育は崇高に仕事だと言われる。", "explanation": "活用の誤り：名詞「仕事」を修飾するときは「崇高に」ではなく「崇高な」とする。"}, {"text": "教育は崇高だ仕事と言われる。", "explanation": "活用の誤り：「崇高だ」は名詞を直接修飾できない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52568, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その医師の生き方は崇高なだと思う。", "corrected_sentence": "その医師の生き方は崇高だと思う。", "error_description": "述語では「崇高な」ではなく「崇高だ」となる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "崇高", "is_correct": true, "explanation": "語幹に「に」が付き「崇高に見えた」となる。"}, {"text": "崇高な", "is_correct": false, "explanation": "「崇高なに」は非文。"}, {"text": "崇高だ", "is_correct": false, "explanation": "「崇高だに」は非文。"}, {"text": "崇高さ", "is_correct": false, "explanation": "名詞形で「崇高さに見えた」は不自然。"}], "correct_form": "崇高", "base_form": "崇高", "form_label": "語幹（に接続・連用）", "sentence_index": 7, "explanations": {"崇高": "語幹に「に」が付き「崇高に見えた」となる。", "崇高な": "「崇高なに」は非文。", "崇高だ": "「崇高だに」は非文。", "崇高さ": "名詞形で「崇高さに見えた」は不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
