INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52066, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "縁側", "is_correct": true, "explanation": "正解：「えんがわ」と読む対象語。"}, {"text": "沿岸", "is_correct": false, "explanation": "「えんがん」と読む。四モーラ目「わ」が「ん」に変わる。"}, {"text": "塩害", "is_correct": false, "explanation": "「えんがい」と読む。四モーラ目「わ」が「い」に変わる。"}, {"text": "沿革", "is_correct": false, "explanation": "「えんかく」と読む。「が」が「か」、「わ」が「く」に変わる。"}], "explanations": {"縁側": "正解：「えんがわ」と読む対象語。", "沿岸": "「えんがん」と読む。四モーラ目「わ」が「ん」に変わる。", "塩害": "「えんがい」と読む。四モーラ目「わ」が「い」に変わる。", "沿革": "「えんかく」と読む。「が」が「か」、「わ」が「く」に変わる。"}, "sentence_index": null, "correct_answer": "縁側"}, "level_3": {"options": [{"text": "縁側", "is_correct": true, "explanation": "日の当たる家の板敷きで子どもが座る場所。"}, {"text": "地下室", "is_correct": false, "explanation": "意味：地下室は陽だまりにならない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "意味：子どもが中で植物を見る場所ではない。"}, {"text": "洞窟", "is_correct": false, "explanation": "語域：伝統家屋の情景に合わず、陽も当たらない。"}], "explanations": {"縁側": "日の当たる家の板敷きで子どもが座る場所。", "地下室": "意味：地下室は陽だまりにならない。", "冷蔵庫": "意味：子どもが中で植物を見る場所ではない。", "洞窟": "語域：伝統家屋の情景に合わず、陽も当たらない。"}, "sentence_index": 0, "correct_answer": "縁側"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏は縁側を座ってスイカを食べた。", "explanation": "助詞の混同：座る場所は「を」ではなく「に」で示す。"}, {"text": "夏は一匹の縁側に座ってスイカを食べた。", "explanation": "助数詞の誤り：縁側を「匹」で数えることはない。"}, {"text": "夏は縁側の座ってスイカを食べた。", "explanation": "助詞の混同：座る場所は「の」ではなく「に」で示す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
