INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52244, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "唯一", "is_correct": true, "explanation": "ゆいいつ。正解。"}, {"text": "唯物", "is_correct": false, "explanation": "ゆいぶつ：三つ目の「い」が「ぶ」に変わる一モーラ差。"}, {"text": "随一", "is_correct": false, "explanation": "ずいいち：近い音。"}, {"text": "唯心", "is_correct": false, "explanation": "ゆいしん：近い音。"}], "explanations": {"唯一": "ゆいいつ。正解。", "唯物": "ゆいぶつ：三つ目の「い」が「ぶ」に変わる一モーラ差。", "随一": "ずいいち：近い音。", "唯心": "ゆいしん：近い音。"}, "sentence_index": null, "correct_answer": "唯一"}, "level_3": {"options": [{"text": "唯一", "is_correct": true, "explanation": "ただ一人だけ答えられた意味で自然。"}, {"text": "反対", "is_correct": false, "explanation": "意味：答えた様子を表さない。"}, {"text": "安心", "is_correct": false, "explanation": "意味：答えるの修飾にならない。"}, {"text": "失敗", "is_correct": false, "explanation": "意味：答えられたことと矛盾する。"}], "explanations": {"唯一": "ただ一人だけ答えられた意味で自然。", "反対": "意味：答えた様子を表さない。", "安心": "意味：答えるの修飾にならない。", "失敗": "意味：答えられたことと矛盾する。"}, "sentence_index": 6, "correct_answer": "唯一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "唯一わかったのが三つある。", "explanation": "意味の誤り：唯一なのに三つは矛盾。"}, {"text": "唯一にわかったのは彼の名前だ。", "explanation": "語形の誤り：「唯一に」とは言わない。"}, {"text": "唯一なわかったのは彼の名前だ。", "explanation": "語形の誤り：「唯一」は「な」をとらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dbef9f-d21a-483e-a767-e6ed239a2667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
