INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52180, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "その次に。続いて。順序を表すときに使う。", "primary_collocate": null, "pronunciation": "ついで", "ipa": "tsɯide", "syllable_count": 3, "sentences": [{"text": "次いで、分岐や終点といった特徴点の配列を精密に分析する。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "次いで、ラズベリー等のジャムを対になる片割れ、あるいは同一の切片上に重ね合わせる。\n\n甘味と塩気、滑らかさと顆粒感が口腔内で織りなす対照的なハーモニーは、単なる栄養補給の域を超え、短時間での認知機能回復をもたらし、合理性と美学が融合した食の営みとして完成する。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "まず手を洗い、次いで顔を洗う。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "て あら つ かお あら", "sentence_source": "generated"}, {"text": "まず駅に行き、次いで店に行く。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "えき い つ みせ い", "sentence_source": "generated"}, {"text": "次いで、野菜を切ります。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "つ やさい き", "sentence_source": "generated"}, {"text": "社長が話し、次いで部長が話した。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "しゃちょう はな つ ぶちょう はな", "sentence_source": "generated"}, {"text": "一位は兄、次いで弟だった。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "いちい あに つ おとうと", "sentence_source": "generated"}, {"text": "次いで、皿に料理を並べる。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "つ さら りょうり なら", "sentence_source": "generated"}, {"text": "雨が降り、次いで雪になった。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "あめ ふ つ ゆき", "sentence_source": "generated"}, {"text": "次いで、二つ目の問題に進む。", "target_word": "次いで", "complexity_tier": "T3", "furigana": "つ ふた め もんだい すす", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "副詞 | 前の事柄に続いて次に", "collocate_grounding": {"status": "no_source", "reason": "no collocate a