INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52458, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "程度が非常に激しく、厳しいさま。", "primary_collocate": null, "pronunciation": "かれつ", "ipa": "kaɾetsɯ", "syllable_count": 3, "sentences": [{"text": "犯罪現場という苛烈な情報の奔流の中から、科学捜査の担い手は微細な痕跡を拾い上げる。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "苛烈な寒風が頬を打つ外の世界へと、無垢な好奇心を携えて駆け出していくその背中には、人間が本来備えている、過酷な環境をも楽しみへと変貌させる逞しさが凝縮されていたのである。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "試合は苛烈な戦いになった。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "しあい かれつ たたか", "sentence_source": "generated"}, {"text": "競争がますます苛烈になる。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "きょうそう かれつ", "sentence_source": "generated"}, {"text": "その批判はとても苛烈だった。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "ひはん かれつ", "sentence_source": "generated"}, {"text": "苛烈な暑さが続いている。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "かれつ あつ つづ", "sentence_source": "generated"}, {"text": "戦場の様子は苛烈だった。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "せんじょう ようす かれつ", "sentence_source": "generated"}, {"text": "彼は苛烈な訓練に耐えた。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "かれ かれつ くんれん た", "sentence_source": "generated"}, {"text": "市場の争いは苛烈を極める。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "しじょう あらそ かれつ きわ", "sentence_source": "generated"}, {"text": "苛烈さを増す嵐に驚いた。", "target_word": "苛烈", "complexity_tier": "T3", "furigana": "かれつ ま あらし おどろ", "sentence_source": "generated"}], "morphological_forms": [{"form": "苛烈な", "label": "活用"}, {"form": "苛烈に", "label": "活用"}, {"form": "苛烈だ", "label": "活用"}, {"form": "苛烈さ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 程度が非常に激しく厳しいさま", "col