INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36751, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "刃物などで物を分けたり、断ったりする。", "primary_collocate": null, "pronunciation": "きる", "ipa": "kiɾɯ", "syllable_count": 2, "sentences": [{"text": "グローバルな金融市場やサプライチェーンといった社会経済的文脈において、個々の企業や投資家といったミクロな主体による局所的な意思決定は、決して単純な線形モデルでは捉えきれない。", "target_word": "きれ", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "しかし、窓辺に佇む幼き我が子の瞳は、白銀に覆われた庭先へと注がれ、抑えきれない生命の衝動に駆られていた。", "target_word": "きれ", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "母がりんごを切っている。", "target_word": "切", "complexity_tier": "T3", "furigana": "はは き", "sentence_source": "generated"}, {"text": "はさみで紙を切った。", "target_word": "切", "complexity_tier": "T3", "furigana": "かみ き", "sentence_source": "generated"}, {"text": "包丁で指を切ってしまった。", "target_word": "切", "complexity_tier": "T3", "furigana": "ほうちょう ゆび き", "sentence_source": "generated"}, {"text": "髪を短く切りたい。", "target_word": "切", "complexity_tier": "T3", "furigana": "かみ みじか き", "sentence_source": "generated"}, {"text": "パンを切るのは難しい。", "target_word": "切", "complexity_tier": "T3", "furigana": "き むずか", "sentence_source": "generated"}, {"text": "この肉は硬くて切れない。", "target_word": "切", "complexity_tier": "T3", "furigana": "にく かた き", "sentence_source": "generated"}, {"text": "ケーキを八つに切ろう。", "target_word": "切", "complexity_tier": "T3", "furigana": "やっ き", "sentence_source": "generated"}, {"text": "野菜の切り方を習った。", "target_word": "切", "complexity_tier": "T3", "furigana": "やさい き かた なら", "sentence_source": "generated"}], "morphological_forms": [{"form": "切った", "label": "活用"}, {"form": "切って", "label": "活用"}, {"form": "切らない", "label": "活用"}, {"form": "切れる", "label": "活用"}, {"form": "切り方", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 刃物などで物を分ける", "collocate_grounding": {"