INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41337, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "ベンチャー", "is_correct": true, "explanation": "「べんちゃー」。新しい事業。"}, {"text": "ベンダー", "is_correct": false, "explanation": "「べんだー」。製品を売る業者。"}, {"text": "ランチャー", "is_correct": false, "explanation": "「らんちゃー」。発射装置。"}, {"text": "パンチャー", "is_correct": false, "explanation": "「ぱんちゃー」。パンチの強い選手。"}], "explanations": {"ベンチャー": "「べんちゃー」。新しい事業。", "ベンダー": "「べんだー」。製品を売る業者。", "ランチャー": "「らんちゃー」。発射装置。", "パンチャー": "「ぱんちゃー」。パンチの強い選手。"}, "sentence_index": null, "correct_answer": "ベンチャー"}, "level_3": {"options": [{"text": "ベンチャー", "is_correct": true, "explanation": "「ベンチャーキャピタル」は新事業に投資する会社。"}, {"text": "ホーム", "is_correct": false, "explanation": "「ホームキャピタル」は投資機関の名前ではない。"}, {"text": "スポーツ", "is_correct": false, "explanation": "意味が通らない。"}, {"text": "ドリンク", "is_correct": false, "explanation": "意味が通らない。"}], "explanations": {"ベンチャー": "「ベンチャーキャピタル」は新事業に投資する会社。", "ホーム": "「ホームキャピタル」は投資機関の名前ではない。", "スポーツ": "意味が通らない。", "ドリンク": "意味が通らない。"}, "sentence_index": 0, "correct_answer": "ベンチャー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ベンチャーで足を洗った。", "explanation": "水や容器の意味ではない。"}, {"text": "公園のベンチャーに座った。", "explanation": "ベンチ（いす）と混同している。"}, {"text": "ベンチャーを一杯飲んだ。", "explanation": "飲み物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '189b8605-8f53-4079-9c03-27dd2cfed871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
