INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35303, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「貸し出し」が「期間」を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "目的語の印で、名詞の修飾にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の印で、ここでは非文。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の印で、ここでは非文。"}], "correct_answer": "の", "explanations": {"の": "「貸し出し」が「期間」を修飾する。", "を": "目的語の印で、名詞の修飾にならない。", "へ": "方向の印で、ここでは非文。", "で": "手段・場所の印で、ここでは非文。"}, "error_tags": {"を": "object_marking", "へ": "direction", "で": "instrument"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35303, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "期間", "is_correct": true, "explanation": "正しい音。"}, {"text": "規格", "is_correct": false, "explanation": "「きかく」。最後の「ん」が「く」になる一モーラ差。"}, {"text": "季節", "is_correct": false, "explanation": "「きせつ」。後半が「せつ」になる。"}, {"text": "交換", "is_correct": false, "explanation": "「こうかん」。一拍目「き」が「こう」になる。"}], "explanations": {"期間": "正しい音。", "規格": "「きかく」。最後の「ん」が「く」になる一モーラ差。", "季節": "「きせつ」。後半が「せつ」になる。", "交換": "「こうかん」。一拍目「き」が「こう」になる。"}, "sentence_index": null, "correct_answer": "期間"}, "level_3": {"options": [{"text": "期間", "is_correct": true, "explanation": "意味：決められた長さが過ぎると使えなくなる。"}, {"text": "名前", "is_correct": false, "explanation": "意味：名前が過ぎることはない。"}, {"text": "気持ち", "is_correct": false, "explanation": "意味：文脈に合わない。"}, {"text": "道", "is_correct": false, "explanation": "意味：道が過ぎるでは使えなくなる理由にならない。"}], "explanations": {"期間": "意味：決められた長さが過ぎると使えなくなる。", "名前": "意味：名前が過ぎることはない。", "気持ち": "意味：文脈に合わない。", "道": "意味：道が過ぎるでは使えなくなる理由にならない。"}, "sentence_index": 6, "correct_answer": "期間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "募集の期間は今月末までなので、来月も応募できる。", "explanation": "意味の誤り：期間が今月末までなら来月は応募できない。"}, {"text": "募集の期間を今月末までだ。", "explanation": "助詞の誤り：主題は「は」で示す。"}, {"text": "一匹の募集の期間は今月末までだ。", "explanation": "助数詞の誤り：期間は「匹」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
