INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35324, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "相乗", "is_correct": true, "explanation": "正しい語です。"}, {"text": "操縦", "is_correct": false, "explanation": "「操縦」はそうじゅう。「じょ」が「じゅ」に変わる一モーラ差。"}, {"text": "早朝", "is_correct": false, "explanation": "「早朝」はそうちょう。「じょ」が「ちょ」に変わる一モーラ差。"}, {"text": "総称", "is_correct": false, "explanation": "「総称」はそうしょう。「じょ」が「しょ」に変わる一モーラ差（清濁）。"}, {"text": "工場", "is_correct": false, "explanation": "「工場」はこうじょう。最初の「そ」が「こ」に変わる一モーラ差。"}, {"text": "想像", "is_correct": false, "explanation": "「想像」はそうぞう。「じょ」が「ぞ」に変わる一モーラ差。"}], "explanations": {"相乗": "正しい語です。", "操縦": "「操縦」はそうじゅう。「じょ」が「じゅ」に変わる一モーラ差。", "早朝": "「早朝」はそうちょう。「じょ」が「ちょ」に変わる一モーラ差。", "総称": "「総称」はそうしょう。「じょ」が「しょ」に変わる一モーラ差（清濁）。", "工場": "「工場」はこうじょう。最初の「そ」が「こ」に変わる一モーラ差。", "想像": "「想像」はそうぞう。「じょ」が「ぞ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "相乗"}, "level_3": {"options": [{"text": "相乗", "is_correct": true, "explanation": "二つの力が合わさって大きな効果になる「相乗効果」。"}, {"text": "逆", "is_correct": false, "explanation": "意味：「逆効果」では力を合わせて成果が出た文意と合わない。"}, {"text": "副", "is_correct": false, "explanation": "意味：「副効果」は本来の目的とは別の効果で、文意に合わない。"}, {"text": "無", "is_correct": false, "explanation": "連語：「無効果」とは言わず、文意とも合わない。"}], "explanations": {"相乗": "二つの力が合わさって大きな効果になる「相乗効果」。", "逆": "意味：「逆効果」では力を合わせて成果が出た文意と合わない。", "副": "意味：「副効果」は本来の目的とは別の効果で、文意に合わない。", "無": "連語：「無効果」とは言わず、文意とも合わない。"}, "sentence_index": 0, "correct_answer": "相乗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "相乗効果に期待して練習を三冊した。", "explanation": "助数詞の誤り：練習は「冊」で数えない。"}, {"text": "相乗効果を期待しているした。", "explanation": "活用の誤り：「している」と「した」が重なり非文。"}, {"text": "相乗効果で期待を練習した。", "explanation": "助詞の混同：「で」と「を」の位置が誤りで意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5665fc7-37dc-46b2-8a22-86e4c6de2204') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
