INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35328, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "進む", "is_correct": true, "explanation": "正しい語です。"}, {"text": "涼む", "is_correct": false, "explanation": "「涼む」はすずむ。二つ目の「す」が「ず」になる清濁の違い。"}, {"text": "濯ぐ", "is_correct": false, "explanation": "「濯ぐ」はすすぐ。最後の「む」が「ぐ」に変わる一モーラ差。"}, {"text": "荒む", "is_correct": false, "explanation": "「荒む」はすさむ。二つ目の「す」が「さ」に変わる一モーラ差。"}, {"text": "竦む", "is_correct": false, "explanation": "「竦む」はすくむ。二つ目の「す」が「く」に変わる一モーラ差。"}], "explanations": {"進む": "正しい語です。", "涼む": "「涼む」はすずむ。二つ目の「す」が「ず」になる清濁の違い。", "濯ぐ": "「濯ぐ」はすすぐ。最後の「む」が「ぐ」に変わる一モーラ差。", "荒む": "「荒む」はすさむ。二つ目の「す」が「さ」に変わる一モーラ差。", "竦む": "「竦む」はすくむ。二つ目の「す」が「く」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "進む"}, "level_3": {"options": [{"text": "進む", "is_correct": true, "explanation": "車が前へ動いていく様子に合う。"}, {"text": "座る", "is_correct": false, "explanation": "項構造：車は「座る」主体にならない。"}, {"text": "眠る", "is_correct": false, "explanation": "意味：車が眠ることはなく「前に」とも合わない。"}, {"text": "笑う", "is_correct": false, "explanation": "意味：車は笑わない。"}], "explanations": {"進む": "車が前へ動いていく様子に合う。", "座る": "項構造：車は「座る」主体にならない。", "眠る": "意味：車が眠ることはなく「前に」とも合わない。", "笑う": "意味：車は笑わない。"}, "sentence_index": 0, "correct_answer": "進む"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雪を前に進めなかった。", "explanation": "助詞の混同：原因は「で」で表し、「を」は使えない。"}, {"text": "雪で前に進めているなかった。", "explanation": "活用の誤り：「ている」と「なかった」が混ざって非文。"}, {"text": "前に雪で一冊進めなかった。", "explanation": "助数詞の誤り：進む距離を「冊」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5665fc7-37dc-46b2-8a22-86e4c6de2204') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35328, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "車がゆっくり前に進むた。", "corrected_sentence": "車がゆっくり前に進む。", "error_description": "活用の誤り：「進むた」という形はない。辞書形「進む」にする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "進ん", "is_correct": true, "explanation": "過去の「進んだ」になるので「進ん」が入る。"}, {"text": "進む", "is_correct": false, "explanation": "辞書形では「だ」に続かない。"}, {"text": "進め", "is_correct": false, "explanation": "「進めだ」という形はない。"}, {"text": "進ま", "is_correct": false, "explanation": "「進まだ」という形はない。"}], "correct_form": "進ん", "base_form": "進む", "form_label": "活用", "sentence_index": 1, "explanations": {"進ん": "過去の「進んだ」になるので「進ん」が入る。", "進む": "辞書形では「だ」に続かない。", "進め": "「進めだ」という形はない。", "進ま": "「進まだ」という形はない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5665fc7-37dc-46b2-8a22-86e4c6de2204') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35328, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "通過する場所「道」を「を」で示す。"}, {"text": "が", "is_correct": false, "explanation": "「道が進んだ」だと道が動くことになる。"}, {"text": "で", "is_correct": false, "explanation": "通る道そのものは「で」ではなく「を」で示す。"}, {"text": "から", "is_correct": false, "explanation": "「道から進んだ」は不自然。"}], "correct_answer": "を", "explanations": {"を": "通過する場所「道」を「を」で示す。", "が": "「道が進んだ」だと道が動くことになる。", "で": "通る道そのものは「で」ではなく「を」で示す。", "から": "「道から進んだ」は不自然。"}, "error_tags": {"が": "object_marking", "で": "location_vs_target", "から": "source_vs_goal"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "戻る", "is_correct": true, "explanation": "後ろへ帰る「戻る」は進むの対義。"}, {"text": "走る", "is_correct": false, "explanation": "速く動くことで、対義ではない。"}, {"text": "歩く", "is_correct": false, "explanation": "足で動くことで、対義ではない。"}, {"text": "急ぐ", "is_correct": false, "explanation": "早くしようとすることで、対義ではない。"}], "correct_answer": "戻る", "explanations": {"戻る": "後ろへ帰る「戻る」は進むの対義。", "走る": "速く動くことで、対義ではない。", "歩く": "足で動くことで、対義ではない。", "急ぐ": "早くしようとすることで、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5665fc7-37dc-46b2-8a22-86e4c6de2204') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35328, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "進む", "is_correct": true, "explanation": "正しい語です。"}, {"text": "窄む", "is_correct": false, "explanation": "「窄む」はすぼむ。二つ目の「す」が「ぼ」に変わる一モーラ差。"}, {"text": "包む", "is_correct": false, "explanation": "「包む」はつつむ。「すす」が「つつ」に変わる。"}, {"text": "沈む", "is_correct": false, "explanation": "「沈む」はしずむ。「すす」が「しず」に変わる。"}, {"text": "住む", "is_correct": false, "explanation": "「住む」はすむ。「す」が一つ少ない。"}], "explanations": {"進む": "正しい語です。", "窄む": "「窄む」はすぼむ。二つ目の「す」が「ぼ」に変わる一モーラ差。", "包む": "「包む」はつつむ。「すす」が「つつ」に変わる。", "沈む": "「沈む」はしずむ。「すす」が「しず」に変わる。", "住む": "「住む」はすむ。「す」が一つ少ない。"}, "sentence_index": null, "correct_answer": "進む"}, "level_3": {"options": [{"text": "進ん", "is_correct": true, "explanation": "「〜でください」につながるて形。前へ行く意味。"}, {"text": "座っ", "is_correct": false, "explanation": "意味：曲がらずに座るでは指示として意味が通らない。"}, {"text": "寝", "is_correct": false, "explanation": "意味：曲がらずに寝るは文脈に合わない。"}, {"text": "泣い", "is_correct": false, "explanation": "意味：道の指示として泣くは合わない。"}], "explanations": {"進ん": "「〜でください」につながるて形。前へ行く意味。", "座っ": "意味：曲がらずに座るでは指示として意味が通らない。", "寝": "意味：曲がらずに寝るは文脈に合わない。", "泣い": "意味：道の指示として泣くは合わない。"}, "sentence_index": 6, "correct_answer": "進ん"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボートを川が進む様子を見た。", "explanation": "助詞の混同：主語と場所の助詞が入れ替わっている。"}, {"text": "ボートが川を進んでいる様子を見たている。", "explanation": "活用の誤り：「見たている」は非文。"}, {"text": "ボートが一冊川を進む様子を見た。", "explanation": "助数詞の誤り：ボートは「冊」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5665fc7-37dc-46b2-8a22-86e4c6de2204') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35328, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "前に進む人に後ろを歩いた。", "corrected_sentence": "前に進む人の後ろを歩いた。", "error_description": "助詞の混同：「人の後ろ」は「の」でつなぐ。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "進む", "is_correct": true, "explanation": "名詞「人」を修飾するので辞書形。"}, {"text": "進んで", "is_correct": false, "explanation": "て形は名詞を直接修飾しない。"}, {"text": "進みます", "is_correct": false, "explanation": "丁寧形は連体修飾に使わない。"}, {"text": "進もう", "is_correct": false, "explanation": "意向形は名詞の修飾に合わない。"}], "correct_form": "進む", "base_form": "進む", "form_label": "活用", "sentence_index": 7, "explanations": {"進む": "名詞「人」を修飾するので辞書形。", "進んで": "て形は名詞を直接修飾しない。", "進みます": "丁寧形は連体修飾に使わない。", "進もう": "意向形は名詞の修飾に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5665fc7-37dc-46b2-8a22-86e4c6de2204') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
