INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35330, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "特に", "is_correct": true, "explanation": "正しい語です。"}, {"text": "得意", "is_correct": false, "explanation": "「得意」はとくい。最後の「に」が「い」に変わる一モーラ差。"}, {"text": "とっくに", "is_correct": false, "explanation": "「とっくに」はとっくに。促音が入る違い。"}, {"text": "特技", "is_correct": false, "explanation": "「特技」はとくぎ。「に」が「ぎ」に変わる一モーラ差。"}, {"text": "時に", "is_correct": false, "explanation": "「時に」はときに。「く」が「き」に変わる一モーラ差。"}], "explanations": {"特に": "正しい語です。", "得意": "「得意」はとくい。最後の「に」が「い」に変わる一モーラ差。", "とっくに": "「とっくに」はとっくに。促音が入る違い。", "特技": "「特技」はとくぎ。「に」が「ぎ」に変わる一モーラ差。", "時に": "「時に」はときに。「く」が「き」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "特に"}, "level_3": {"options": [{"text": "特に", "is_correct": true, "explanation": "果物の中でりんごがとりわけ好きだと示す。"}, {"text": "全然", "is_correct": false, "explanation": "意味：「全然」は否定と使い、「好きだ」と合わない。"}, {"text": "決して", "is_correct": false, "explanation": "意味：「決して」も否定と一緒に使う。"}, {"text": "もう", "is_correct": false, "explanation": "意味：比べてとりわけ、の意味にならない。"}], "explanations": {"特に": "果物の中でりんごがとりわけ好きだと示す。", "全然": "意味：「全然」は否定と使い、「好きだ」と合わない。", "決して": "意味：「決して」も否定と一緒に使う。", "もう": "意味：比べてとりわけ、の意味にならない。"}, "sentence_index": 0, "correct_answer": "特に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "数学を特に難しかった。", "explanation": "助詞の混同：形容詞の主語は「が」で「を」ではない。"}, {"text": "数学が特に難しいでした。", "explanation": "活用の誤り：「難しいでした」ではなく「難しかったです」。"}, {"text": "特に数学が一匹難しかった。", "explanation": "助数詞の誤り：数学を「匹」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5665fc7-37dc-46b2-8a22-86e4c6de2204') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
