INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35339, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある事柄について書かれ、研究の資料となる文書や本。", "primary_collocate": null, "pronunciation": "ぶんけん", "ipa": "bɯŋkeɴ", "syllable_count": 4, "sentences": [{"text": "レポートのために文献を読んだ。", "target_word": "文献", "complexity_tier": "T3", "furigana": "ぶんけん よ", "sentence_source": "generated"}, {"text": "研究に必要な文献を集めた。", "target_word": "文献", "complexity_tier": "T3", "furigana": "けんきゅう ひつよう ぶんけん あつ", "sentence_source": "generated"}, {"text": "この文献は研究に役立つ。", "target_word": "文献", "complexity_tier": "T3", "furigana": "ぶんけん けんきゅう やくだ", "sentence_source": "generated"}, {"text": "文献のリストを先生に出した。", "target_word": "文献", "complexity_tier": "T3", "furigana": "ぶんけん せんせい だ", "sentence_source": "generated"}, {"text": "兄は英語の文献を調べている。", "target_word": "文献", "complexity_tier": "T3", "furigana": "あに えいご ぶんけん しら", "sentence_source": "generated"}, {"text": "環境についての文献は多い。", "target_word": "文献", "complexity_tier": "T3", "furigana": "かんきょう ぶんけん おお", "sentence_source": "generated"}, {"text": "文献を使って意見を書いた。", "target_word": "文献", "complexity_tier": "T3", "furigana": "ぶんけん つか いけん か", "sentence_source": "generated"}, {"text": "大切な文献が見つからない。", "target_word": "文献", "complexity_tier": "T3", "furigana": "たいせつ ぶんけん み", "sentence_source": "generated"}, {"text": "文献から新しいことを学んだ。", "target_word": "文献", "complexity_tier": "T3", "furigana": "ぶんけん あたら まな", "sentence_source": "generated"}, {"text": "最後に参考にした文献を書く。", "target_word": "文献", "complexity_tier": "T3", "furigana": "さいご さんこう ぶんけん か", "sentence_source": "generated"}], "morphological_forms": [{"form": "冊", "label": "助数詞"}, {"form": "参考文献", "label": "派生"}, {"form": "文献リスト", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 研究の資料になる文書や本", "collocate_grounding": {"status": "no_source", "reason": "no collocate assert