INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35356, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "空にある星や月、太陽などについて研究する学問。", "primary_collocate": null, "pronunciation": "てんもん", "ipa": "temmoɴ", "syllable_count": 4, "sentences": [{"text": "兄は天文に興味を持っている。", "target_word": "天文", "complexity_tier": "T3", "furigana": "あに てんもん きょうみ も", "sentence_source": "generated"}, {"text": "天文の本を図書館で借りた。", "target_word": "天文", "complexity_tier": "T3", "furigana": "てんもん ほん としょかん か", "sentence_source": "generated"}, {"text": "天文が好きで星をよく見る。", "target_word": "天文", "complexity_tier": "T3", "furigana": "てんもん す ほし み", "sentence_source": "generated"}, {"text": "学校に天文クラブがある。", "target_word": "天文", "complexity_tier": "T3", "furigana": "がっこう てんもん", "sentence_source": "generated"}, {"text": "天文の先生に月の話を聞いた。", "target_word": "天文", "complexity_tier": "T3", "furigana": "てんもん せんせい つき はなし き", "sentence_source": "generated"}, {"text": "将来は天文を学びたい。", "target_word": "天文", "complexity_tier": "T3", "furigana": "しょうらい てんもん まな", "sentence_source": "generated"}, {"text": "天文の知識で星座が分かる。", "target_word": "天文", "complexity_tier": "T3", "furigana": "てんもん ちしき せいざ わ", "sentence_source": "generated"}, {"text": "父と天文の番組を見た。", "target_word": "天文", "complexity_tier": "T3", "furigana": "ちち てんもん ばんぐみ み", "sentence_source": "generated"}, {"text": "天文はとても古い学問だ。", "target_word": "天文", "complexity_tier": "T3", "furigana": "てんもん ふる がくもん", "sentence_source": "generated"}, {"text": "彼女は天文に詳しい。", "target_word": "天文", "complexity_tier": "T3", "furigana": "かのじょ てんもん くわ", "sentence_source": "generated"}], "morphological_forms": [{"form": "天文学", "label": "派生"}, {"form": "天文台", "label": "派生"}, {"form": "天文学者", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 星や月を研究する学問", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this