INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35364, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "共有", "is_correct": true, "explanation": "正解。読みは「きょうゆう」。"}, {"text": "きょうぐう", "is_correct": false, "explanation": "読みは「境遇」。「ゆ」が「ぐ」に変わる一モーラ差。"}, {"text": "きょうぼう", "is_correct": false, "explanation": "読みは「共謀」。「ゆ」が「ぼ」に変わる一モーラ差。"}, {"text": "きょうゆ", "is_correct": false, "explanation": "読みは「教諭」。最後の長音「う」がない長短の差。"}], "explanations": {"共有": "正解。読みは「きょうゆう」。", "きょうぐう": "読みは「境遇」。「ゆ」が「ぐ」に変わる一モーラ差。", "きょうぼう": "読みは「共謀」。「ゆ」が「ぼ」に変わる一モーラ差。", "きょうゆ": "読みは「教諭」。最後の長音「う」がない長短の差。"}, "sentence_index": null, "correct_answer": "共有"}, "level_3": {"options": [{"text": "共有", "is_correct": true, "explanation": "家族で一台を一緒に使っている。"}, {"text": "勉強", "is_correct": false, "explanation": "車を勉強しているとは言わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "車を洗濯するとは言わない。"}, {"text": "料理", "is_correct": false, "explanation": "車を料理することはできない。"}], "explanations": {"共有": "家族で一台を一緒に使っている。", "勉強": "車を勉強しているとは言わない。", "洗濯": "車を洗濯するとは言わない。", "料理": "車を料理することはできない。"}, "sentence_index": 0, "correct_answer": "共有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "共有を飲んでのどが渇いた。", "explanation": "共有は行為で、飲み物ではない。"}, {"text": "一人だけで共有している。", "explanation": "共有は複数の人で使うことで、一人では成り立たない。"}, {"text": "共有が泣いている。", "explanation": "共有は行為で、泣かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df5712f-33d8-4848-b7bb-e9f929eb3bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
