INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35365, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の人で、情報や物を同じように持つこと。", "primary_collocate": null, "pronunciation": "きょうゆう", "ipa": "kʲoːjuː", "syllable_count": 4, "sentences": [{"text": "写真を友達と共有した。", "target_word": "共有", "complexity_tier": "T3", "furigana": "共有（きょうゆう）", "sentence_source": "generated"}, {"text": "情報の共有はとても大切だ。", "target_word": "共有", "complexity_tier": "T3", "furigana": "共有（きょうゆう）", "sentence_source": "generated"}, {"text": "この部屋は兄と共有している。", "target_word": "共有", "complexity_tier": "T3", "furigana": "共有（きょうゆう）", "sentence_source": "generated"}, {"text": "共有のパソコンを使っている。", "target_word": "共有", "complexity_tier": "T3", "furigana": "共有（きょうゆう）", "sentence_source": "generated"}, {"text": "予定をみんなで共有しよう。", "target_word": "共有", "complexity_tier": "T3", "furigana": "共有（きょうゆう）", "sentence_source": "generated"}, {"text": "共有されたファイルを開いた。", "target_word": "共有", "complexity_tier": "T3", "furigana": "共有（きょうゆう）", "sentence_source": "generated"}, {"text": "クラスで意見を共有した。", "target_word": "共有", "complexity_tier": "T3", "furigana": "共有（きょうゆう）", "sentence_source": "generated"}, {"text": "共有の冷蔵庫に名前を書く。", "target_word": "共有", "complexity_tier": "T3", "furigana": "共有（きょうゆう）", "sentence_source": "generated"}, {"text": "秘密を共有するのは難しい。", "target_word": "共有", "complexity_tier": "T3", "furigana": "共有（きょうゆう）", "sentence_source": "generated"}, {"text": "家族で車を共有している。", "target_word": "共有", "complexity_tier": "T3", "furigana": "共有（きょうゆう）", "sentence_source": "generated"}], "morphological_forms": [{"form": "共有する", "label": "派生"}, {"form": "共有者", "label": "派生"}, {"form": "情報共有", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 情報や物をみんなで持つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:f