INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35365, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。この位置には「に」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「冷蔵庫を名前を書く」と「を」が重なり非文。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」では書く場所を表せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」はこの文に合わない。"}], "correct_answer": "に", "explanations": {"に": "正解。この位置には「に」が入る。", "を": "「冷蔵庫を名前を書く」と「を」が重なり非文。", "が": "主格の「が」では書く場所を表せない。", "より": "比較の「より」はこの文に合わない。"}, "error_tags": {"を": "location_vs_target", "が": "topic_vs_subject", "より": "other"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "専有", "is_correct": true, "explanation": "自分だけのものとして持つことで、「共有」の反対。"}, {"text": "協力", "is_correct": false, "explanation": "力を合わせることで、反対ではない。"}, {"text": "提供", "is_correct": false, "explanation": "相手に出すことで、反対ではない。"}, {"text": "配信", "is_correct": false, "explanation": "情報を送ることで、反対ではない。"}], "correct_answer": "専有", "explanations": {"専有": "自分だけのものとして持つことで、「共有」の反対。", "協力": "力を合わせることで、反対ではない。", "提供": "相手に出すことで、反対ではない。", "配信": "情報を送ることで、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeaaebd-38df-4ff1-af83-08e2166ad7d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35370, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "加速", "is_correct": true, "explanation": "正解。「加速」（かそく）。"}, {"text": "家族", "is_correct": false, "explanation": "「家族」（かぞく）。「そ」が「ぞ」になる清濁の違い。"}, {"text": "仮装", "is_correct": false, "explanation": "「仮装」（かそう）。「く」が「う」になる一モーラ差。"}, {"text": "過食", "is_correct": false, "explanation": "「過食」（かしょく）。「そ」が「しょ」になる一モーラ差。"}], "explanations": {"加速": "正解。「加速」（かそく）。", "家族": "「家族」（かぞく）。「そ」が「ぞ」になる清濁の違い。", "仮装": "「仮装」（かそう）。「く」が「う」になる一モーラ差。", "過食": "「過食」（かしょく）。「そ」が「しょ」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "加速"}, "level_3": {"options": [{"text": "加速", "is_correct": true, "explanation": "正解。文脈に合うのは「加速」。"}, {"text": "卒業", "is_correct": false, "explanation": "意味：車は卒業しない。"}, {"text": "勉強", "is_correct": false, "explanation": "意味：車は勉強しない。"}, {"text": "結婚", "is_correct": false, "explanation": "項構造：車は結婚の主語にならない。"}], "explanations": {"加速": "正解。文脈に合うのは「加速」。", "卒業": "意味：車は卒業しない。", "勉強": "意味：車は勉強しない。", "結婚": "項構造：車は結婚の主語にならない。"}, "sentence_index": 0, "correct_answer": "加速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "加速を二本買った。", "explanation": "助数詞の誤り：「加速」は物ではなく買えない。"}, {"text": "車を急に加速が出た。", "explanation": "助詞の混同：「車が急に加速した」が正しい。"}, {"text": "加速な車に乗った。", "explanation": "品詞の誤り：名詞「加速」は「の」で修飾する。「な」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeaaebd-38df-4ff1-af83-08e2166ad7d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
