INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35370, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。この位置には「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「駅が出て」では電車が主語にならず非文。"}, {"text": "で", "is_correct": false, "explanation": "「駅で出て」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「駅と出て」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "正解。この位置には「を」が入る。", "が": "「駅が出て」では電車が主語にならず非文。", "で": "「駅で出て」は不自然。", "と": "「駅と出て」は意味が通らない。"}, "error_tags": {"が": "object_marking", "で": "location_vs_target", "と": "other"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "減速", "is_correct": true, "explanation": "速さが落ちることで、「加速」の反対。"}, {"text": "発進", "is_correct": false, "explanation": "動き出すことで、反対ではない。"}, {"text": "前進", "is_correct": false, "explanation": "前へ進むことで、反対ではない。"}, {"text": "回転", "is_correct": false, "explanation": "回ることで、反対ではない。"}], "correct_answer": "減速", "explanations": {"減速": "速さが落ちることで、「加速」の反対。", "発進": "動き出すことで、反対ではない。", "前進": "前へ進むことで、反対ではない。", "回転": "回ることで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeaaebd-38df-4ff1-af83-08e2166ad7d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35370, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "加速", "is_correct": true, "explanation": "正解。「加速」（かそく）。"}, {"text": "家族", "is_correct": false, "explanation": "「家族」（かぞく）。清濁の違い（そ／ぞ）。"}, {"text": "火葬", "is_correct": false, "explanation": "「火葬」（かそう）。最後のモーラ「く」が「う」。"}, {"text": "佳作", "is_correct": false, "explanation": "「佳作」（かさく）。「そ」が「さ」になる一モーラ差。"}], "explanations": {"加速": "正解。「加速」（かそく）。", "家族": "「家族」（かぞく）。清濁の違い（そ／ぞ）。", "火葬": "「火葬」（かそう）。最後のモーラ「く」が「う」。", "佳作": "「佳作」（かさく）。「そ」が「さ」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "加速"}, "level_3": {"options": [{"text": "加速", "is_correct": true, "explanation": "正解。文脈に合うのは「加速」。"}, {"text": "卒業", "is_correct": false, "explanation": "意味：「卒業すると危ない」は文脈に合わない。"}, {"text": "注意", "is_correct": false, "explanation": "意味：注意すると危ないは逆の意味になる。"}, {"text": "用心", "is_correct": false, "explanation": "意味：用心すると危ないは不自然。"}], "explanations": {"加速": "正解。文脈に合うのは「加速」。", "卒業": "意味：「卒業すると危ない」は文脈に合わない。", "注意": "意味：注意すると危ないは逆の意味になる。", "用心": "意味：用心すると危ないは不自然。"}, "sentence_index": 6, "correct_answer": "加速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は最後に加速を三冊した。", "explanation": "助数詞の誤り：「加速」は「冊」で数えない。"}, {"text": "最後に彼を加速して勝った。", "explanation": "助詞の混同：走る本人は「は／が」で示す。"}, {"text": "彼は最後に加速がして勝った。", "explanation": "語法の誤り：「加速する」はサ変動詞で、「加速がする」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeaaebd-38df-4ff1-af83-08e2166ad7d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
