INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35372, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。この位置には「を」が入る。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「話せる」の対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「言語と話せる」は意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「言語に話せる」は非文。"}], "correct_answer": "を", "explanations": {"を": "正解。この位置には「を」が入る。", "へ": "方向の「へ」は「話せる」の対象を示せない。", "と": "「言語と話せる」は意味が通らない。", "に": "「言語に話せる」は非文。"}, "error_tags": {"へ": "direction", "と": "other", "に": "location_vs_target"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeaaebd-38df-4ff1-af83-08e2166ad7d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35372, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "言語", "is_correct": true, "explanation": "正解。「言語」（げんご）。"}, {"text": "元気", "is_correct": false, "explanation": "「元気」（げんき）。「ご」が「き」になる一モーラ差。"}, {"text": "言動", "is_correct": false, "explanation": "「言動」（げんどう）。「ご」が「どう」になる違い。"}, {"text": "原稿", "is_correct": false, "explanation": "「原稿」（げんこう）。「ご」が「こう」になる清濁と長音の違い。"}], "explanations": {"言語": "正解。「言語」（げんご）。", "元気": "「元気」（げんき）。「ご」が「き」になる一モーラ差。", "言動": "「言動」（げんどう）。「ご」が「どう」になる違い。", "原稿": "「原稿」（げんこう）。「ご」が「こう」になる清濁と長音の違い。"}, "sentence_index": null, "correct_answer": "言語"}, "level_3": {"options": [{"text": "言語", "is_correct": true, "explanation": "正解。文脈に合うのは「言語」。"}, {"text": "天気", "is_correct": false, "explanation": "意味：天気の違いは友達になる話と合わない。"}, {"text": "時計", "is_correct": false, "explanation": "意味：時計が違うことは関係がない。"}, {"text": "机", "is_correct": false, "explanation": "意味：机が違っても、は不自然。"}], "explanations": {"言語": "正解。文脈に合うのは「言語」。", "天気": "意味：天気の違いは友達になる話と合わない。", "時計": "意味：時計が違うことは関係がない。", "机": "意味：机が違っても、は不自然。"}, "sentence_index": 6, "correct_answer": "言語"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は言語を二台持っている。", "explanation": "助数詞の誤り：言語は「台」で数えない。"}, {"text": "言語に彼女は先生だ。", "explanation": "助詞の混同：「彼女は言語の先生だ」が正しい。"}, {"text": "好きなは言語英語です。", "explanation": "語順の誤り：語の並びが壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeaaebd-38df-4ff1-af83-08e2166ad7d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
