INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35382, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人や物がそこにあること、いること。", "primary_collocate": null, "pronunciation": "そんざい", "ipa": "sonzai", "syllable_count": 4, "sentences": [{"text": "宇宙人の存在を信じますか。", "target_word": "存在", "complexity_tier": "T3", "furigana": "うちゅうじん そんざい しん", "sentence_source": "generated"}, {"text": "彼の存在に気づかなかった。", "target_word": "存在", "complexity_tier": "T3", "furigana": "かれ そんざい き", "sentence_source": "generated"}, {"text": "その島の存在は知られていない。", "target_word": "存在", "complexity_tier": "T3", "furigana": "しま そんざい し", "sentence_source": "generated"}, {"text": "昔ここに村が存在していた。", "target_word": "存在", "complexity_tier": "T3", "furigana": "むかし むら そんざい", "sentence_source": "generated"}, {"text": "幽霊の存在を信じない人も多い。", "target_word": "存在", "complexity_tier": "T3", "furigana": "ゆうれい そんざい しん ひと おお", "sentence_source": "generated"}, {"text": "森には多くの生き物が存在する。", "target_word": "存在", "complexity_tier": "T3", "furigana": "もり おお い もの そんざい", "sentence_source": "generated"}, {"text": "この問題の存在を忘れていた。", "target_word": "存在", "complexity_tier": "T3", "furigana": "もんだい そんざい わす", "sentence_source": "generated"}, {"text": "存在しない店を探してしまった。", "target_word": "存在", "complexity_tier": "T3", "furigana": "そんざい みせ さが", "sentence_source": "generated"}, {"text": "地下に水の存在が見つかった。", "target_word": "存在", "complexity_tier": "T3", "furigana": "ちか みず そんざい み", "sentence_source": "generated"}, {"text": "水の存在が命には大切だ。", "target_word": "存在", "complexity_tier": "T3", "furigana": "みず そんざい いのち たいせつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "存在する", "label": "派生"}, {"form": "存在感", "label": "派生"}, {"form": "存在した", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 人や物がそこにある・いること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted