INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35384, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある場所だけで使われる特別な言葉。", "primary_collocate": null, "pronunciation": "ほうげん", "ipa": "hoːɡeɴ", "syllable_count": 4, "sentences": [{"text": "祖母は方言で話す。", "target_word": "方言", "complexity_tier": "T3", "furigana": "そぼ ほうげん はな", "sentence_source": "generated"}, {"text": "この町の方言はおもしろい。", "target_word": "方言", "complexity_tier": "T3", "furigana": "まち ほうげん", "sentence_source": "generated"}, {"text": "方言がわからなくて困った。", "target_word": "方言", "complexity_tier": "T3", "furigana": "ほうげん こま", "sentence_source": "generated"}, {"text": "友達に大阪の方言を教わった。", "target_word": "方言", "complexity_tier": "T3", "furigana": "ともだち おおさか ほうげん おそ", "sentence_source": "generated"}, {"text": "方言を聞くと故郷を思い出す。", "target_word": "方言", "complexity_tier": "T3", "furigana": "ほうげん き ふるさと おも だ", "sentence_source": "generated"}, {"text": "彼は方言を使わないで話した。", "target_word": "方言", "complexity_tier": "T3", "furigana": "かれ ほうげん つか はな", "sentence_source": "generated"}, {"text": "村の人たちの方言は優しい。", "target_word": "方言", "complexity_tier": "T3", "furigana": "むら ひと ほうげん やさ", "sentence_source": "generated"}, {"text": "方言の言葉を一つ覚えた。", "target_word": "方言", "complexity_tier": "T3", "furigana": "ほうげん ことば ひと おぼ", "sentence_source": "generated"}, {"text": "テレビで東北の方言を聞いた。", "target_word": "方言", "complexity_tier": "T3", "furigana": "とうほく ほうげん き", "sentence_source": "generated"}, {"text": "方言で書かれた手紙が届いた。", "target_word": "方言", "complexity_tier": "T3", "furigana": "ほうげん か てがみ とど", "sentence_source": "generated"}], "morphological_forms": [{"form": "方言学", "label": "派生"}, {"form": "関西方言", "label": "派生"}, {"form": "方言話者", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | ある土地だけで使う言葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}