INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35880, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在の場所は「に」で表す。"}, {"text": "で", "is_correct": false, "explanation": "「いる」の場所に「で」は使わない。"}, {"text": "を", "is_correct": false, "explanation": "「いる」は目的語をとらない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向で、「いる」には合わない。"}], "correct_answer": "に", "explanations": {"に": "存在の場所は「に」で表す。", "で": "「いる」の場所に「で」は使わない。", "を": "「いる」は目的語をとらない。", "へ": "「へ」は移動の方向で、「いる」には合わない。"}, "error_tags": {"で": "location_vs_target", "を": "object_marking", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "昔", "is_correct": true, "explanation": "「今」の反対で、ずっと前の時。"}, {"text": "毎日", "is_correct": false, "explanation": "くり返しを表し、反対ではない。"}, {"text": "朝", "is_correct": false, "explanation": "一日の時間帯で、反対の関係にない。"}, {"text": "週末", "is_correct": false, "explanation": "週の終わりで、反対ではない。"}], "correct_answer": "昔", "explanations": {"昔": "「今」の反対で、ずっと前の時。", "毎日": "くり返しを表し、反対ではない。", "朝": "一日の時間帯で、反対の関係にない。", "週末": "週の終わりで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab670d18-ab6f-4e45-acad-d88e89f55e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
