INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35884, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "仕方", "is_correct": true, "explanation": "正解。「しかた」と読む対象語。"}, {"text": "味方", "is_correct": false, "explanation": "「みかた」と読む。最初のモーラ「し」が「み」に変わる一モーラ差。"}, {"text": "四角", "is_correct": false, "explanation": "「しかく」と読む。三番目のモーラ「た」が「く」に変わる一モーラ差。"}, {"text": "館", "is_correct": false, "explanation": "「やかた」と読む。最初のモーラ「し」が「や」に変わる一モーラ差。"}, {"text": "司会", "is_correct": false, "explanation": "「しかい」と読む。三番目のモーラ「た」が「い」に変わる一モーラ差。"}, {"text": "しかし", "is_correct": false, "explanation": "「しかし」と読む。三番目のモーラ「た」が「し」に変わる一モーラ差。"}], "explanations": {"仕方": "正解。「しかた」と読む対象語。", "味方": "「みかた」と読む。最初のモーラ「し」が「み」に変わる一モーラ差。", "四角": "「しかく」と読む。三番目のモーラ「た」が「く」に変わる一モーラ差。", "館": "「やかた」と読む。最初のモーラ「し」が「や」に変わる一モーラ差。", "司会": "「しかい」と読む。三番目のモーラ「た」が「い」に変わる一モーラ差。", "しかし": "「しかし」と読む。三番目のモーラ「た」が「し」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "仕方"}, "level_3": {"options": [{"text": "仕方", "is_correct": true, "explanation": "正解。文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "意味：勉強に天気はないので意味が通らない。"}, {"text": "雨", "is_correct": false, "explanation": "意味：「勉強の雨」では意味をなさない。"}, {"text": "値段", "is_correct": false, "explanation": "連語：「勉強の値段を教えて」は結びつきが不自然。"}], "explanations": {"仕方": "正解。文脈に合う。", "天気": "意味：勉強に天気はないので意味が通らない。", "雨": "意味：「勉強の雨」では意味をなさない。", "値段": "連語：「勉強の値段を教えて」は結びつきが不自然。"}, "sentence_index": 0, "correct_answer": "仕方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仕方が変えたら、うまくいった。", "explanation": "助詞の混同：変えるものは「を」で表す。"}, {"text": "仕方の変えたら、うまくいった。", "explanation": "助詞の誤り：「仕方」は「変える」の対象なので「を」で表す。"}, {"text": "うまくいった、変えたら仕方を。", "explanation": "語順の誤り：文の順序がこわれている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab670d18-ab6f-4e45-acad-d88e89f55e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
