INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35885, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を行う方法や手段。", "primary_collocate": null, "pronunciation": "しかた", "ipa": "ɕikata", "syllable_count": 3, "sentences": [{"text": "料理の仕方を母に教わった。", "target_word": "仕方", "complexity_tier": "T3", "furigana": "しかた", "sentence_source": "generated"}, {"text": "勉強の仕方を変えてみた。", "target_word": "仕方", "complexity_tier": "T3", "furigana": "しかた", "sentence_source": "generated"}, {"text": "仕方がわからなくて困っている。", "target_word": "仕方", "complexity_tier": "T3", "furigana": "しかた", "sentence_source": "generated"}, {"text": "正しい仕方で練習しよう。", "target_word": "仕方", "complexity_tier": "T3", "furigana": "しかた", "sentence_source": "generated"}, {"text": "その仕方では時間がかかる。", "target_word": "仕方", "complexity_tier": "T3", "furigana": "しかた", "sentence_source": "generated"}, {"text": "彼女の挨拶の仕方はとても丁寧だ。", "target_word": "仕方", "complexity_tier": "T3", "furigana": "しかた", "sentence_source": "generated"}, {"text": "掃除の仕方は人によって違う。", "target_word": "仕方", "complexity_tier": "T3", "furigana": "しかた", "sentence_source": "generated"}, {"text": "新しい仕方を考えている。", "target_word": "仕方", "complexity_tier": "T3", "furigana": "しかた", "sentence_source": "generated"}, {"text": "運転の仕方を兄に教えてもらった。", "target_word": "仕方", "complexity_tier": "T3", "furigana": "しかた", "sentence_source": "generated"}, {"text": "仕方を間違えると失敗する。", "target_word": "仕方", "complexity_tier": "T3", "furigana": "しかた", "sentence_source": "generated"}], "morphological_forms": [{"form": "仕方ない", "label": "派生"}, {"form": "やり方", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事をするやり方・方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcf59757-caf5-4a24-91f4-95eaf1948046') ON CONFLICT (sense_id, asse