INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35892, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "時間がすぎること。", "primary_collocate": null, "pronunciation": "たつ", "ipa": "tatsɯ", "syllable_count": 2, "sentences": [{"text": "時間が経つのは早い。", "target_word": "経つ", "complexity_tier": "T3", "furigana": "たつ", "sentence_source": "generated"}, {"text": "三年が経った。", "target_word": "経った", "complexity_tier": "T3", "furigana": "たった", "sentence_source": "generated"}, {"text": "一時間経っても彼は来なかった。", "target_word": "経って", "complexity_tier": "T3", "furigana": "たって", "sentence_source": "generated"}, {"text": "日本に来てから一年が経つ。", "target_word": "経つ", "complexity_tier": "T3", "furigana": "たつ", "sentence_source": "generated"}, {"text": "経った時間を数えてみた。", "target_word": "経った", "complexity_tier": "T3", "furigana": "たった", "sentence_source": "generated"}, {"text": "夏休みはあっという間に経った。", "target_word": "経った", "complexity_tier": "T3", "furigana": "たった", "sentence_source": "generated"}, {"text": "卒業して五年経ちました。", "target_word": "経ち", "complexity_tier": "T3", "furigana": "たち", "sentence_source": "generated"}, {"text": "何日経っても返事がない。", "target_word": "経って", "complexity_tier": "T3", "furigana": "たって", "sentence_source": "generated"}, {"text": "時が経つにつれて、町は変わった。", "target_word": "経つ", "complexity_tier": "T3", "furigana": "たつ", "sentence_source": "generated"}, {"text": "楽しい時間はすぐ経つ。", "target_word": "経つ", "complexity_tier": "T3", "furigana": "たつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "経った", "label": "活用"}, {"form": "経って", "label": "活用"}, {"form": "経たない", "label": "活用"}, {"form": "経ちます", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 時間が過ぎて流れていくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcf59757-caf5-4a24