INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35893, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かが起こってから、ある時間が過ぎること。", "primary_collocate": null, "pronunciation": "たつ", "ipa": "tatsɯ", "syllable_count": 2, "sentences": [{"text": "引っ越してから半年が経った。", "target_word": "経った", "complexity_tier": "T3", "furigana": "たった", "sentence_source": "generated"}, {"text": "事故から十年が経つ。", "target_word": "経つ", "complexity_tier": "T3", "furigana": "たつ", "sentence_source": "generated"}, {"text": "彼と会ってから二週間経っている。", "target_word": "経って", "complexity_tier": "T3", "furigana": "たって", "sentence_source": "generated"}, {"text": "雨がやんで少し時間が経った。", "target_word": "経った", "complexity_tier": "T3", "furigana": "たった", "sentence_source": "generated"}, {"text": "始まってから三十分経った。", "target_word": "経った", "complexity_tier": "T3", "furigana": "たった", "sentence_source": "generated"}, {"text": "手紙を出して一か月経つが、返事はない。", "target_word": "経つ", "complexity_tier": "T3", "furigana": "たつ", "sentence_source": "generated"}, {"text": "経った年月を思い出す。", "target_word": "経った", "complexity_tier": "T3", "furigana": "たった", "sentence_source": "generated"}, {"text": "習い始めて二年経ったころ、上手になった。", "target_word": "経った", "complexity_tier": "T3", "furigana": "たった", "sentence_source": "generated"}, {"text": "長い時間が経って、やっと答えが出た。", "target_word": "経って", "complexity_tier": "T3", "furigana": "たって", "sentence_source": "generated"}, {"text": "時間が経つのを忘れて遊んだ。", "target_word": "経つ", "complexity_tier": "T3", "furigana": "たつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "経った", "label": "活用"}, {"form": "経って", "label": "活用"}, {"form": "経たない", "label": "活用"}, {"form": "経ちます", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | ある出来事から時間が流れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed',