INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35896, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが起きた理由のこと。", "primary_collocate": null, "pronunciation": "せい", "ipa": "seː", "syllable_count": 2, "sentences": [{"text": "雨の所為で試合が中止になった。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "寝不足の所為で頭が痛い。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "人の所為にしてはいけない。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "年の所為か、すぐ疲れる。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "彼は失敗を私の所為にした。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "停電の所為で店が閉まった。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "風邪の所為で声が出ない。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "誰の所為でもない。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "暑さの所為で食欲がない。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "自分の所為だと泣いていた。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 物事が起きた理由・原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcf59757-caf5-4a24-91f4-95eaf1948046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prom