INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35904, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "気持ちや考えを、ほかの人にわかるように示すこと。", "primary_collocate": null, "pronunciation": "あらわす", "ipa": "aɾawasɯ", "syllable_count": 4, "sentences": [{"text": "気持ちを言葉で表わす。", "target_word": "表わす", "complexity_tier": "T3", "furigana": "あらわす", "sentence_source": "generated"}, {"text": "感謝の気持ちを手紙で表わした。", "target_word": "表わした", "complexity_tier": "T3", "furigana": "あらわした", "sentence_source": "generated"}, {"text": "彼は喜びを顔に表わした。", "target_word": "表わした", "complexity_tier": "T3", "furigana": "あらわした", "sentence_source": "generated"}, {"text": "この絵は春を表わしている。", "target_word": "表わして", "complexity_tier": "T3", "furigana": "あらわして", "sentence_source": "generated"}, {"text": "赤い色は危険を表わす。", "target_word": "表わす", "complexity_tier": "T3", "furigana": "あらわす", "sentence_source": "generated"}, {"text": "怒りを表わさないようにした。", "target_word": "表わさ", "complexity_tier": "T3", "furigana": "あらわさ", "sentence_source": "generated"}, {"text": "考えをうまく表わせない。", "target_word": "表わせ", "complexity_tier": "T3", "furigana": "あらわせ", "sentence_source": "generated"}, {"text": "数字で結果を表わしてください。", "target_word": "表わして", "complexity_tier": "T3", "furigana": "あらわして", "sentence_source": "generated"}, {"text": "心を表わす言葉を探している。", "target_word": "表わす", "complexity_tier": "T3", "furigana": "あらわす", "sentence_source": "generated"}, {"text": "地図の記号は学校を表わしている。", "target_word": "表わして", "complexity_tier": "T3", "furigana": "あらわして", "sentence_source": "generated"}], "morphological_forms": [{"form": "表わした", "label": "活用"}, {"form": "表わして", "label": "活用"}, {"form": "表わさない", "label": "活用"}, {"form": "表わせる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 気持ちや意味を外に示すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'clau