INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35885, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "仕方", "is_correct": true, "explanation": "正解：「しかた」と読む対象語。"}, {"text": "味方", "is_correct": false, "explanation": "「みかた」と読み、第一モーラ「し」が「み」に替わる一モーラ差。"}, {"text": "資格", "is_correct": false, "explanation": "「しかく」と読み、第三モーラ「た」が「く」に替わる一モーラ差。"}, {"text": "仕掛け", "is_correct": false, "explanation": "「しかけ」と読み、第三モーラ「た」が「け」に替わる一モーラ差。"}, {"text": "しかし", "is_correct": false, "explanation": "「しかし」と読み、第三モーラ「た」が「し」に替わる一モーラ差。"}], "explanations": {"仕方": "正解：「しかた」と読む対象語。", "味方": "「みかた」と読み、第一モーラ「し」が「み」に替わる一モーラ差。", "資格": "「しかく」と読み、第三モーラ「た」が「く」に替わる一モーラ差。", "仕掛け": "「しかけ」と読み、第三モーラ「た」が「け」に替わる一モーラ差。", "しかし": "「しかし」と読み、第三モーラ「た」が「し」に替わる一モーラ差。"}, "sentence_index": null, "correct_answer": "仕方"}, "level_3": {"options": [{"text": "仕方", "is_correct": true, "explanation": "「料理の仕方」で料理のやり方を表す。"}, {"text": "天気", "is_correct": false, "explanation": "意味：料理に天気はなく、教わる内容にならない。"}, {"text": "窓", "is_correct": false, "explanation": "意味：窓は物で、料理と結びつかない。"}, {"text": "音楽", "is_correct": false, "explanation": "連語：「料理の音楽を教わる」は不自然。"}], "explanations": {"仕方": "「料理の仕方」で料理のやり方を表す。", "天気": "意味：料理に天気はなく、教わる内容にならない。", "窓": "意味：窓は物で、料理と結びつかない。", "音楽": "連語：「料理の音楽を教わる」は不自然。"}, "sentence_index": 0, "correct_answer": "仕方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一冊の仕方を覚えた。", "explanation": "助数詞の誤り：「仕方」は「冊」で数えない。"}, {"text": "仕方が料理を母に教わった。", "explanation": "助詞の混同：教わる内容は「を」で示し、仕方は主語にならない。"}, {"text": "料理の仕方を明日教わった。", "explanation": "アスペクトの誤り：「明日」と過去形「教わった」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
