INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35885, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「変える」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」では「変えてみた」の目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を表し、変える対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、ここでは非文になる。"}], "correct_answer": "を", "explanations": {"を": "他動詞「変える」の目的語を示す。", "が": "「が」では「変えてみた」の目的語にならない。", "で": "「で」は手段を表し、変える対象を示せない。", "へ": "「へ」は方向を表し、ここでは非文になる。"}, "error_tags": {"が": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35885, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "仕方", "is_correct": true, "explanation": "正解：「しかた」と読む対象語。"}, {"text": "司会", "is_correct": false, "explanation": "「しかい」と読み、第三モーラ「た」が「い」に替わる一モーラ差。"}, {"text": "四角", "is_correct": false, "explanation": "「しかく」と読み、第三モーラ「た」が「く」に替わる一モーラ差。"}, {"text": "死活", "is_correct": false, "explanation": "「しかつ」と読み、第三モーラ「た」が「つ」に替わる一モーラ差。"}], "explanations": {"仕方": "正解：「しかた」と読む対象語。", "司会": "「しかい」と読み、第三モーラ「た」が「い」に替わる一モーラ差。", "四角": "「しかく」と読み、第三モーラ「た」が「く」に替わる一モーラ差。", "死活": "「しかつ」と読み、第三モーラ「た」が「つ」に替わる一モーラ差。"}, "sentence_index": null, "correct_answer": "仕方"}, "level_3": {"options": [{"text": "仕方", "is_correct": true, "explanation": "「掃除の仕方」は掃除のやり方で、人によって違う。"}, {"text": "雨", "is_correct": false, "explanation": "意味：掃除の雨というものはない。"}, {"text": "犬", "is_correct": false, "explanation": "意味：犬は掃除のやり方ではない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "連語：「掃除の鉛筆」は結びつかない。"}], "explanations": {"仕方": "「掃除の仕方」は掃除のやり方で、人によって違う。", "雨": "意味：掃除の雨というものはない。", "犬": "意味：犬は掃除のやり方ではない。", "鉛筆": "連語：「掃除の鉛筆」は結びつかない。"}, "sentence_index": 6, "correct_answer": "仕方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "仕方に間違えると失敗する。", "explanation": "助詞の混同：間違える対象は「を」で示す。"}, {"text": "三本の仕方を間違えた。", "explanation": "助数詞の誤り：「仕方」を「本」で数えない。"}, {"text": "明日、仕方を間違えて失敗した。", "explanation": "時制の誤り：「明日」と過去形「失敗した」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
