INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35892, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "何日経ちても返事がない。", "corrected_sentence": "何日経っても返事がない。", "error_description": "活用の誤り：「経つ」のて形は「経って」で、「経ちて」とは言わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "経って", "is_correct": true, "explanation": "て形＋「も」で逆接の条件を作る。"}, {"text": "経った", "is_correct": false, "explanation": "た形に直接「も」は付かない。"}, {"text": "経つ", "is_correct": false, "explanation": "辞書形＋「も」はこの文では不自然。"}, {"text": "経ちます", "is_correct": false, "explanation": "ます形は「も」の前に置けない。"}], "correct_form": "経って", "base_form": "経つ", "form_label": "て形", "sentence_index": 7, "explanations": {"経って": "て形＋「も」で逆接の条件を作る。", "経った": "た形に直接「も」は付かない。", "経つ": "辞書形＋「も」はこの文では不自然。", "経ちます": "ます形は「も」の前に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
