INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35905, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "表わす", "is_correct": true, "explanation": "正解：あらわす。気持ちを示すという意味。"}, {"text": "習わす", "is_correct": false, "explanation": "ならわす：最初の「あ」が「な」に変わった一モーラ差。習わせる、という意味。"}, {"text": "笑わす", "is_correct": false, "explanation": "わらわす：最初の「あ」が「わ」に変わった一モーラ差。人を笑わせる、という意味。"}, {"text": "荒らす", "is_correct": false, "explanation": "あらす：「わ」が一つ少ない語。場所をめちゃくちゃにする、という意味。"}], "explanations": {"表わす": "正解：あらわす。気持ちを示すという意味。", "習わす": "ならわす：最初の「あ」が「な」に変わった一モーラ差。習わせる、という意味。", "笑わす": "わらわす：最初の「あ」が「わ」に変わった一モーラ差。人を笑わせる、という意味。", "荒らす": "あらす：「わ」が一つ少ない語。場所をめちゃくちゃにする、という意味。"}, "sentence_index": null, "correct_answer": "表わす"}, "level_3": {"options": [{"text": "表わした", "is_correct": true, "explanation": "喜びの気持ちを顔に示した、という意味で自然。"}, {"text": "売った", "is_correct": false, "explanation": "意味：喜びは売るものではない。"}, {"text": "閉めた", "is_correct": false, "explanation": "連語：「喜びを閉める」とは言わない。"}, {"text": "忘れた", "is_correct": false, "explanation": "項構造：「顔に忘れた」は格の取り方が不自然。"}], "explanations": {"表わした": "喜びの気持ちを顔に示した、という意味で自然。", "売った": "意味：喜びは売るものではない。", "閉めた": "連語：「喜びを閉める」とは言わない。", "忘れた": "項構造：「顔に忘れた」は格の取り方が不自然。"}, "sentence_index": 0, "correct_answer": "表わした"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "感謝の気持ちが手紙を表わした。", "explanation": "助詞の混同：主語と目的語が逆になっている。「気持ちを手紙で表わした」が正しい。"}, {"text": "明日、感謝の気持ちを手紙で表わした。", "explanation": "活用・アスペクトの誤り：「明日」と過去形「た」が合わない。"}, {"text": "手紙で感謝の表わした気持ちを。", "explanation": "語順の誤り：文の形がこわれている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EX