INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35915, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "比べる", "is_correct": true, "explanation": "正解：くらべる。"}, {"text": "調べる", "is_correct": false, "explanation": "しらべる：「く」が「し」の一モーラ差。"}, {"text": "並べる", "is_correct": false, "explanation": "ならべる：「く」が「な」の一モーラ差。"}, {"text": "暮らせる", "is_correct": false, "explanation": "くらせる：「べ」が「せ」の一モーラ差。"}], "explanations": {"比べる": "正解：くらべる。", "調べる": "しらべる：「く」が「し」の一モーラ差。", "並べる": "ならべる：「く」が「な」の一モーラ差。", "暮らせる": "くらせる：「べ」が「せ」の一モーラ差。"}, "sentence_index": null, "correct_answer": "比べる"}, "level_3": {"options": [{"text": "比べて", "is_correct": true, "explanation": "文化の違いを調べて発表した、で自然。"}, {"text": "飲んで", "is_correct": false, "explanation": "意味：文化は飲めない。"}, {"text": "寝て", "is_correct": false, "explanation": "項構造：「寝る」は目的語を取らない。"}, {"text": "泳いで", "is_correct": false, "explanation": "項構造：「文化を泳ぐ」は不自然。"}], "explanations": {"比べて": "文化の違いを調べて発表した、で自然。", "飲んで": "意味：文化は飲めない。", "寝て": "項構造：「寝る」は目的語を取らない。", "泳いで": "項構造：「文化を泳ぐ」は不自然。"}, "sentence_index": 0, "correct_answer": "比べて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昔と今の生活が比べてみよう。", "explanation": "助詞の混同：「生活を」が正しい。"}, {"text": "昔と今の生活を比べたみよう。", "explanation": "活用の誤り：「〜てみよう」の形が正しい。"}, {"text": "生活を昔と比べて今のみよう。", "explanation": "語順の誤り：文の形がこわれている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35915, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三つの国の文化が比べて発表した。", "corrected_sentence": "三つの国の文化を比べて発表した。", "error_description": "助詞の混同：比べる対象には「を」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "比べる", "is_correct": true, "explanation": "「と」の前で条件を表すので辞書形。"}, {"text": "比べた", "is_correct": false, "explanation": "過去形。「〜と」の条件には合わない。"}, {"text": "比べて", "is_correct": false, "explanation": "て形。「と」の前に入らない。"}, {"text": "比べない", "is_correct": false, "explanation": "否定形。違いが分かる理由にならない。"}], "correct_form": "比べる", "base_form": "比べる", "form_label": "活用", "sentence_index": 1, "explanations": {"比べる": "「と」の前で条件を表すので辞書形。", "比べた": "過去形。「〜と」の条件には合わない。", "比べて": "て形。「と」の前に入らない。", "比べない": "否定形。違いが分かる理由にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35915, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "比べる対象を表す「を」。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は対象を表せない。"}, {"text": "が", "is_correct": false, "explanation": "「データが比べる」ではデータが比べることになり非文。"}, {"text": "より", "is_correct": false, "explanation": "「データより比べる」は不自然。"}], "correct_answer": "を", "explanations": {"を": "比べる対象を表す「を」。", "へ": "方向の「へ」は対象を表せない。", "が": "「データが比べる」ではデータが比べることになり非文。", "より": "「データより比べる」は不自然。"}, "error_tags": {"へ": "direction", "が": "topic_vs_subject", "より": "other"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35915, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "比べる", "is_correct": true, "explanation": "正解：くらべる（比べる）。"}, {"text": "選べる", "is_correct": false, "explanation": "えらべる：「く」が「え」になった近い音の語。"}, {"text": "呼べる", "is_correct": false, "explanation": "よべる：「べる」が同じ近い音の語。"}, {"text": "曇る", "is_correct": false, "explanation": "くもる：「く」で始まる近い音の語。"}], "explanations": {"比べる": "正解：くらべる（比べる）。", "選べる": "えらべる：「く」が「え」になった近い音の語。", "呼べる": "よべる：「べる」が同じ近い音の語。", "曇る": "くもる：「く」で始まる近い音の語。"}, "sentence_index": null, "correct_answer": "比べる"}, "level_3": {"options": [{"text": "比べて", "is_correct": true, "explanation": "二つの文の同じ点を探すために比べた、で自然。"}, {"text": "食べて", "is_correct": false, "explanation": "意味：文は食べられない。"}, {"text": "走って", "is_correct": false, "explanation": "項構造：「文を走る」は不自然。"}, {"text": "眠って", "is_correct": false, "explanation": "項構造：「眠る」は目的語を取らない。"}], "explanations": {"比べて": "二つの文の同じ点を探すために比べた、で自然。", "食べて": "意味：文は食べられない。", "走って": "項構造：「文を走る」は不自然。", "眠って": "項構造：「眠る」は目的語を取らない。"}, "sentence_index": 6, "correct_answer": "比べて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "日本と外国の学校が比べた本を読んだ。", "explanation": "助詞の混同：「学校を」が正しい。"}, {"text": "日本と外国の学校を比べるた本を読んだ。", "explanation": "活用の誤り：「比べた」が正しい。"}, {"text": "本を日本と比べた外国の学校を読んだ。", "explanation": "語順の誤り：修飾の関係がこわれている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35915, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生はクラスの成績を比べるいた。", "corrected_sentence": "先生はクラスの成績を比べていた。", "error_description": "活用の誤り：「〜ている」の過去は「比べていた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "比べられる", "is_correct": true, "explanation": "受身形。他の人と比べられることが嫌だ、という意味。"}, {"text": "比べて", "is_correct": false, "explanation": "て形。「のは」の前には入らない。"}, {"text": "比べた", "is_correct": false, "explanation": "過去形。「のは嫌だ」の一般的な気持ちに合わない。"}, {"text": "比べさせる", "is_correct": false, "explanation": "使役形。意味が合わない。"}], "correct_form": "比べられる", "base_form": "比べる", "form_label": "活用", "sentence_index": 7, "explanations": {"比べられる": "受身形。他の人と比べられることが嫌だ、という意味。", "比べて": "て形。「のは」の前には入らない。", "比べた": "過去形。「のは嫌だ」の一般的な気持ちに合わない。", "比べさせる": "使役形。意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
