INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35916, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大きい", "is_correct": true, "explanation": "正解：おおきい。"}, {"text": "雄々しい", "is_correct": false, "explanation": "おおしい：「き」が「し」に変わった一モーラ差。"}, {"text": "大君", "is_correct": false, "explanation": "おおきみ：最後の「い」が「み」に変わった一モーラ差。"}, {"text": "覆い", "is_correct": false, "explanation": "おおい：「き」がない語。かぶせるもの。"}], "explanations": {"大きい": "正解：おおきい。", "雄々しい": "おおしい：「き」が「し」に変わった一モーラ差。", "大君": "おおきみ：最後の「い」が「み」に変わった一モーラ差。", "覆い": "おおい：「き」がない語。かぶせるもの。"}, "sentence_index": null, "correct_answer": "大きい"}, "level_3": {"options": [{"text": "大きい", "is_correct": true, "explanation": "犬の体のサイズが大きい、で自然。"}, {"text": "四角い", "is_correct": false, "explanation": "意味：犬は四角くない。"}, {"text": "辛い", "is_correct": false, "explanation": "意味：犬に味はない。"}, {"text": "酸っぱい", "is_correct": false, "explanation": "意味：犬は酸っぱくない。"}], "explanations": {"大きい": "犬の体のサイズが大きい、で自然。", "四角い": "意味：犬は四角くない。", "辛い": "意味：犬に味はない。", "酸っぱい": "意味：犬は酸っぱくない。"}, "sentence_index": 0, "correct_answer": "大きい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の家を大きくて、庭も広い。", "explanation": "助詞の混同：「家は」が正しい。"}, {"text": "彼の家は大きいくて、庭も広い。", "explanation": "活用の誤り：て形は「大きくて」。"}, {"text": "庭も彼の大きくて家は広い。", "explanation": "語順の誤り：文の形がこわれている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
