INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35918, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ほかの場所から、話し手のいる所へ近づいて着くこと。", "primary_collocate": null, "pronunciation": "くる", "ipa": "kɯɾɯ", "syllable_count": 2, "sentences": [{"text": "友だちが明日うちに来る。", "target_word": "来る", "complexity_tier": "T3", "furigana": "ともだち あした く", "sentence_source": "generated"}, {"text": "バスがもうすぐ来る。", "target_word": "来る", "complexity_tier": "T3", "furigana": "く", "sentence_source": "generated"}, {"text": "先生が教室に来た。", "target_word": "来", "complexity_tier": "T3", "furigana": "せんせい きょうしつ き", "sentence_source": "generated"}, {"text": "犬がこっちに来ると、子どもが笑う。", "target_word": "来る", "complexity_tier": "T3", "furigana": "いぬ く こ わら", "sentence_source": "generated"}, {"text": "姉は駅まで車で来ている。", "target_word": "来", "complexity_tier": "T3", "furigana": "あね えき くるま き", "sentence_source": "generated"}, {"text": "早く来てくれてうれしかった。", "target_word": "来", "complexity_tier": "T3", "furigana": "はや き", "sentence_source": "generated"}, {"text": "彼は今日学校に来ない。", "target_word": "来", "complexity_tier": "T3", "furigana": "かれ きょう がっこう こ", "sentence_source": "generated"}, {"text": "来る人はみんな笑顔だった。", "target_word": "来る", "complexity_tier": "T3", "furigana": "く ひと えがお", "sentence_source": "generated"}, {"text": "祖母が毎年夏に来る。", "target_word": "来る", "complexity_tier": "T3", "furigana": "そぼ まいとし なつ く", "sentence_source": "generated"}, {"text": "一人でここまで来られる？", "target_word": "来", "complexity_tier": "T3", "furigana": "ひとり こ", "sentence_source": "generated"}], "morphological_forms": [{"form": "来た", "label": "活用"}, {"form": "来て", "label": "活用"}, {"form": "来ない", "label": "活用"}, {"form": "来られる", "label": "活用"}, {"form": "いらっしゃる", "label": "敬語形"}], "register": "plain", "sense_fingerprint": "動詞 | ほかの所から話し手の方へ移動する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asser