INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35936, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「上を歩く」で通る場所を表す。"}, {"text": "が", "is_correct": false, "explanation": "「上が歩く」では上が歩く主体になり、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「上と歩いて」は非文。"}, {"text": "から", "is_correct": false, "explanation": "「上から歩く」では起点になり、文意に合わない。"}], "correct_answer": "を", "explanations": {"を": "「上を歩く」で通る場所を表す。", "が": "「上が歩く」では上が歩く主体になり、意味が通らない。", "と": "「上と歩いて」は非文。", "から": "「上から歩く」では起点になり、文意に合わない。"}, "error_tags": {"が": "object_marking", "から": "source_vs_goal", "と": "other"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '202dfbf3-1409-471d-8608-d00230db9672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
