INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35937, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「線が上に向かう」で動く主体を表す。"}, {"text": "を", "is_correct": false, "explanation": "「線を上に向かう」は自動詞と合わない。"}, {"text": "で", "is_correct": false, "explanation": "「線で向かう」は手段になり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「線へ」は方向で、主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「線が上に向かう」で動く主体を表す。", "を": "「線を上に向かう」は自動詞と合わない。", "で": "「線で向かう」は手段になり不自然。", "へ": "「線へ」は方向で、主語にならない。"}, "error_tags": {"を": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '202dfbf3-1409-471d-8608-d00230db9672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35938, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "譜", "is_correct": true, "explanation": "正解。「ふ」と読む。"}, {"text": "歯", "is_correct": false, "explanation": "「は」と読み、口の中の歯。音が一拍だけ違う。"}, {"text": "火", "is_correct": false, "explanation": "「ひ」と読み、燃えるもの。音が一拍だけ違う。"}, {"text": "部", "is_correct": false, "explanation": "「ぶ」と読み、クラブや部分。音が一拍だけ違う。"}, {"text": "目", "is_correct": false, "explanation": "「め」と読み、ものを見る器官。音が一拍だけ違う。"}], "explanations": {"譜": "正解。「ふ」と読む。", "歯": "「は」と読み、口の中の歯。音が一拍だけ違う。", "火": "「ひ」と読み、燃えるもの。音が一拍だけ違う。", "部": "「ぶ」と読み、クラブや部分。音が一拍だけ違う。", "目": "「め」と読み、ものを見る器官。音が一拍だけ違う。"}, "sentence_index": null, "correct_answer": "譜"}, "level_3": {"options": [{"text": "譜", "is_correct": true, "explanation": "ピアノの上に置く楽譜のこと。"}, {"text": "声", "is_correct": false, "explanation": "声は置けない。"}, {"text": "音", "is_correct": false, "explanation": "音は物ではなく置けない。"}, {"text": "夢", "is_correct": false, "explanation": "夢は置けない。"}], "explanations": {"譜": "ピアノの上に置く楽譜のこと。", "声": "声は置けない。", "音": "音は物ではなく置けない。", "夢": "夢は置けない。"}, "sentence_index": 0, "correct_answer": "譜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "譜をフライパンで焼いて食べた。", "explanation": "譜は紙で、食べ物ではない。"}, {"text": "譜が庭を走り回っている。", "explanation": "譜は生き物ではない。"}, {"text": "暑いので譜を着て出かけた。", "explanation": "譜は服ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '202dfbf3-1409-471d-8608-d00230db9672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
