INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35939, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "譜", "is_correct": true, "explanation": "正解。「ふ」と読む。"}, {"text": "葉", "is_correct": false, "explanation": "「は」と読み、木の葉。音が一拍だけ違う。"}, {"text": "血", "is_correct": false, "explanation": "「ち」と読み、体の血。音が一拍だけ違う。"}, {"text": "戸", "is_correct": false, "explanation": "「と」と読み、家の出入り口。音が一拍だけ違う。"}, {"text": "毛", "is_correct": false, "explanation": "「け」と読み、体の毛。音が一拍だけ違う。"}], "explanations": {"譜": "正解。「ふ」と読む。", "葉": "「は」と読み、木の葉。音が一拍だけ違う。", "血": "「ち」と読み、体の血。音が一拍だけ違う。", "戸": "「と」と読み、家の出入り口。音が一拍だけ違う。", "毛": "「け」と読み、体の毛。音が一拍だけ違う。"}, "sentence_index": null, "correct_answer": "譜"}, "level_3": {"options": [{"text": "譜", "is_correct": true, "explanation": "譜を見ると音の長さや拍が分かる。"}, {"text": "空", "is_correct": false, "explanation": "空を見てもリズムは分からない。"}, {"text": "顔", "is_correct": false, "explanation": "顔を見てもリズムは分からない。"}, {"text": "花", "is_correct": false, "explanation": "花を見てもリズムは分からない。"}], "explanations": {"譜": "譜を見ると音の長さや拍が分かる。", "空": "空を見てもリズムは分からない。", "顔": "顔を見てもリズムは分からない。", "花": "花を見てもリズムは分からない。"}, "sentence_index": 6, "correct_answer": "譜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "譜がおなかをすかせて鳴いた。", "explanation": "譜は動物ではない。"}, {"text": "冬は譜を着ると暖かい。", "explanation": "譜は服ではない。"}, {"text": "譜に乗って海を渡った。", "explanation": "譜は船ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '202dfbf3-1409-471d-8608-d00230db9672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
