INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35960, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏休みの予定を決まった。", "corrected_sentence": "夏休みの予定を決めた。", "error_description": "「を」があるので他動詞「決める」を使う。「決まる」は自動詞。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "決める", "is_correct": true, "explanation": "辞書形で文を終えられ、これからのことを表す。"}, {"text": "決め", "is_correct": false, "explanation": "連用形だけでは文が終わらない。"}, {"text": "決めれば", "is_correct": false, "explanation": "条件形では文が終わらない。"}, {"text": "決めさせ", "is_correct": false, "explanation": "使役の連用形では文が終わらない。"}], "correct_form": "決める", "base_form": "決める", "form_label": "辞書形", "sentence_index": 1, "explanations": {"決める": "辞書形で文を終えられ、これからのことを表す。", "決め": "連用形だけでは文が終わらない。", "決めれば": "条件形では文が終わらない。", "決めさせ": "使役の連用形では文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '202dfbf3-1409-471d-8608-d00230db9672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
