INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35963, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "音楽の演奏方法を記号で書き表したもの。曲を再現するための情報が書かれている", "primary_collocate": null, "pronunciation": "がくふ", "ipa": "ɡakɯɸɯ", "syllable_count": 3, "sentences": [{"text": "作曲家は自分の曲を楽譜に書いた。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "さっきょくか じぶん きょく がくふ か", "sentence_source": "generated"}, {"text": "楽譜には音の長さも書いてある。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "がくふ おと なが か", "sentence_source": "generated"}, {"text": "古い楽譜から昔の曲を再現できる。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "ふる がくふ むかし きょく さいげん", "sentence_source": "generated"}, {"text": "この曲の楽譜は手に入らない。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "きょく がくふ て はい", "sentence_source": "generated"}, {"text": "楽譜の記号の意味を調べている。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "がくふ きごう いみ しら", "sentence_source": "generated"}, {"text": "彼は聞いた曲をすぐ楽譜にできる。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "かれ き きょく がくふ", "sentence_source": "generated"}, {"text": "図書館で楽譜を借りてきた。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "としょかん がくふ か", "sentence_source": "generated"}, {"text": "楽譜どおりに演奏するのは難しい。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "がくふ えんそう むずか", "sentence_source": "generated"}, {"text": "バンドの楽譜を自分で作った。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "がくふ じぶん つく", "sentence_source": "generated"}, {"text": "楽譜が読めると練習が楽になる。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "がくふ よ れんしゅう らく", "sentence_source": "generated"}], "morphological_forms": [{"form": "枚", "label": "助数詞"}, {"form": "冊", "label": "助数詞"}, {"form": "楽譜集", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 曲を記号で書き表した記録", "collocate_grounding": {"status": "no_source", "