INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35964, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "前のことが、あとにそのままうつって現れること", "primary_collocate": null, "pronunciation": "はんえい", "ipa": "haɴeː", "syllable_count": 4, "sentences": [{"text": "練習の成果が試合に反映された。", "target_word": "反映", "complexity_tier": "T3", "furigana": "れんしゅう せいか しあい はんえい", "sentence_source": "generated"}, {"text": "親の性格が子どもに反映する。", "target_word": "反映", "complexity_tier": "T3", "furigana": "おや せいかく こ はんえい", "sentence_source": "generated"}, {"text": "天気が気分に反映することもある。", "target_word": "反映", "complexity_tier": "T3", "furigana": "てんき きぶん はんえい", "sentence_source": "generated"}, {"text": "努力の反映が成績に出ている。", "target_word": "反映", "complexity_tier": "T3", "furigana": "どりょく はんえい せいせき で", "sentence_source": "generated"}, {"text": "失敗の経験が今の仕事に反映している。", "target_word": "反映", "complexity_tier": "T3", "furigana": "しっぱい けいけん いま しごと はんえい", "sentence_source": "generated"}, {"text": "子どもの考えが絵に反映している。", "target_word": "反映", "complexity_tier": "T3", "furigana": "こ かんが え はんえい", "sentence_source": "generated"}, {"text": "結果の反映には時間がかかる。", "target_word": "反映", "complexity_tier": "T3", "furigana": "けっか はんえい じかん", "sentence_source": "generated"}, {"text": "その努力は新しい作品に反映された。", "target_word": "反映", "complexity_tier": "T3", "furigana": "どりょく あたら さくひん はんえい", "sentence_source": "generated"}, {"text": "生活の変化が言葉に反映される。", "target_word": "反映", "complexity_tier": "T3", "furigana": "せいかつ へんか ことば はんえい", "sentence_source": "generated"}, {"text": "反映されたのは一部だけだった。", "target_word": "反映", "complexity_tier": "T3", "furigana": "はんえい いちぶ", "sentence_source": "generated"}], "morphological_forms": [{"form": "反映する", "label": "派生"}, {"form": "反映される", "label": "活用"}, {"form": "反映させる", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 前のことが後にそのまま現れること", "collocate_grounding": {"status":