INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35965, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "前の出来事や考え方を、あとのものにそのまま取り入れること", "primary_collocate": null, "pronunciation": "はんえい", "ipa": "haɴeː", "syllable_count": 4, "sentences": [{"text": "アンケートの結果を授業に反映する。", "target_word": "反映", "complexity_tier": "T3", "furigana": "けっか じゅぎょう はんえい", "sentence_source": "generated"}, {"text": "社会の考え方を映画に反映している。", "target_word": "反映", "complexity_tier": "T3", "furigana": "しゃかい かんが かた えいが はんえい", "sentence_source": "generated"}, {"text": "生徒の声を反映した校則ができた。", "target_word": "反映", "complexity_tier": "T3", "furigana": "せいと こえ はんえい こうそく", "sentence_source": "generated"}, {"text": "昔の出来事を今の町づくりに反映している。", "target_word": "反映", "complexity_tier": "T3", "furigana": "むかし できごと いま まち はんえい", "sentence_source": "generated"}, {"text": "意見の反映がまだ足りないと思う。", "target_word": "反映", "complexity_tier": "T3", "furigana": "いけん はんえい た おも", "sentence_source": "generated"}, {"text": "経験を反映して練習方法を変えた。", "target_word": "反映", "complexity_tier": "T3", "furigana": "けいけん はんえい れんしゅう ほうほう か", "sentence_source": "generated"}, {"text": "作者の気持ちが歌詞に反映されている。", "target_word": "反映", "complexity_tier": "T3", "furigana": "さくしゃ きも かし はんえい", "sentence_source": "generated"}, {"text": "変更はすぐに反映されない。", "target_word": "反映", "complexity_tier": "T3", "furigana": "へんこう はんえい", "sentence_source": "generated"}, {"text": "反映するかどうかは会議で決める。", "target_word": "反映", "complexity_tier": "T3", "furigana": "はんえい かいぎ き", "sentence_source": "generated"}, {"text": "生徒の意見の反映が求められている。", "target_word": "反映", "complexity_tier": "T3", "furigana": "せいと いけん はんえい もと", "sentence_source": "generated"}], "morphological_forms": [{"form": "反映する", "label": "派生"}, {"form": "反映される", "label": "活用"}, {"form": "反映させる", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 意見や考えを後のものに取り入れること", "colloca