INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36044, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものごとを文章に書いて伝えること。また、書かれた内容", "primary_collocate": null, "pronunciation": "きじゅつ", "ipa": "kidʑɯtsɯ", "syllable_count": 3, "sentences": [{"text": "教科書の記述をよく読んでください。", "target_word": "記述", "complexity_tier": "T3", "furigana": "きょうかしょ きじゅつ よ", "sentence_source": "generated"}, {"text": "見たことを正しく記述する。", "target_word": "記述", "complexity_tier": "T3", "furigana": "み ただ きじゅつ", "sentence_source": "generated"}, {"text": "この記述はまちがっている。", "target_word": "記述", "complexity_tier": "T3", "furigana": "きじゅつ", "sentence_source": "generated"}, {"text": "テストに記述の問題が出た。", "target_word": "記述", "complexity_tier": "T3", "furigana": "きじゅつ もんだい で", "sentence_source": "generated"}, {"text": "日記に一日の出来事を記述した。", "target_word": "記述", "complexity_tier": "T3", "furigana": "にっき いちにち できごと きじゅつ", "sentence_source": "generated"}, {"text": "記述が長すぎて分かりにくい。", "target_word": "記述", "complexity_tier": "T3", "furigana": "きじゅつ なが わ", "sentence_source": "generated"}, {"text": "事件について細かく記述している。", "target_word": "記述", "complexity_tier": "T3", "furigana": "じけん こま きじゅつ", "sentence_source": "generated"}, {"text": "本には古い町の記述がある。", "target_word": "記述", "complexity_tier": "T3", "furigana": "ほん ふる まち きじゅつ", "sentence_source": "generated"}, {"text": "記述された内容を確かめる。", "target_word": "記述", "complexity_tier": "T3", "furigana": "きじゅつ ないよう たし", "sentence_source": "generated"}, {"text": "記述の練習をして作文がうまくなった。", "target_word": "記述", "complexity_tier": "T3", "furigana": "きじゅつ れんしゅう さくぶん", "sentence_source": "generated"}], "morphological_forms": [{"form": "記述する", "label": "派生"}, {"form": "記述式", "label": "派生"}, {"form": "記述された", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 物事を文章に書き表すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a4d1b3-8c4b-4d8a-b78c-ca93729dc0b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35962, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "楽譜", "is_correct": true, "explanation": "正解。読みは「がくふ」。"}, {"text": "学部", "is_correct": false, "explanation": "読みは「がくぶ」。「ふ」が濁って「ぶ」になる（清濁）。"}, {"text": "学費", "is_correct": false, "explanation": "読みは「がくひ」。三つ目のモーラ「ふ」が「ひ」（一モーラ差）。"}, {"text": "学士", "is_correct": false, "explanation": "読みは「がくし」。三つ目のモーラ「ふ」が「し」（一モーラ差）。"}, {"text": "学徒", "is_correct": false, "explanation": "読みは「がくと」。三つ目のモーラ「ふ」が「と」（一モーラ差）。"}], "explanations": {"楽譜": "正解。読みは「がくふ」。", "学部": "読みは「がくぶ」。「ふ」が濁って「ぶ」になる（清濁）。", "学費": "読みは「がくひ」。三つ目のモーラ「ふ」が「ひ」（一モーラ差）。", "学士": "読みは「がくし」。三つ目のモーラ「ふ」が「し」（一モーラ差）。", "学徒": "読みは「がくと」。三つ目のモーラ「ふ」が「と」（一モーラ差）。"}, "sentence_index": null, "correct_answer": "楽譜"}, "level_3": {"options": [{"text": "楽譜", "is_correct": true, "explanation": "ピアノをひくときに見る、音楽の記号が書かれたもの。"}, {"text": "地図", "is_correct": false, "explanation": "意味：ピアノをひくときに見るものではない。"}, {"text": "野菜", "is_correct": false, "explanation": "意味：見ながらピアノをひくものではない。"}, {"text": "くつ", "is_correct": false, "explanation": "意味：見ながらピアノをひくものではない。"}], "explanations": {"楽譜": "ピアノをひくときに見る、音楽の記号が書かれたもの。", "地図": "意味：ピアノをひくときに見るものではない。", "野菜": "意味：見ながらピアノをひくものではない。", "くつ": "意味：見ながらピアノをひくものではない。"}, "sentence_index": 0, "correct_answer": "楽譜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "楽譜がおいしくて、全部食べた。", "explanation": "楽譜は食べ物ではない。"}, {"text": "楽譜に乗って駅まで行った。", "explanation": "楽譜は乗り物ではない。"}, {"text": "雨が降ったので楽譜をさした。", "explanation": "「さす」のは傘であり、楽譜ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e572d9e3-facd-4a81-943d-b2b5dc08b58c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validati