INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35963, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "楽譜", "is_correct": true, "explanation": "正解。読みは「がくふ」。"}, {"text": "学区", "is_correct": false, "explanation": "読みは「がっく」。促音が入り「ふ」がない。"}, {"text": "学帽", "is_correct": false, "explanation": "読みは「がくぼう」。三つ目以降が「ぼう」。"}, {"text": "学部", "is_correct": false, "explanation": "読みは「がくぶ」。「ふ」が濁って「ぶ」になる（清濁）。"}], "explanations": {"楽譜": "正解。読みは「がくふ」。", "学区": "読みは「がっく」。促音が入り「ふ」がない。", "学帽": "読みは「がくぼう」。三つ目以降が「ぼう」。", "学部": "読みは「がくぶ」。「ふ」が濁って「ぶ」になる（清濁）。"}, "sentence_index": null, "correct_answer": "楽譜"}, "level_3": {"options": [{"text": "楽譜", "is_correct": true, "explanation": "図書館で曲を記した楽譜を借りることができる。"}, {"text": "切手", "is_correct": false, "explanation": "意味：図書館で借りるものではない。"}, {"text": "野菜", "is_correct": false, "explanation": "意味：図書館にない。"}, {"text": "薬", "is_correct": false, "explanation": "意味：図書館で借りるものではない。"}], "explanations": {"楽譜": "図書館で曲を記した楽譜を借りることができる。", "切手": "意味：図書館で借りるものではない。", "野菜": "意味：図書館にない。", "薬": "意味：図書館で借りるものではない。"}, "sentence_index": 6, "correct_answer": "楽譜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "楽譜がかぜをひいて休んだ。", "explanation": "楽譜は人ではない。"}, {"text": "楽譜に水をやったら花がさいた。", "explanation": "楽譜は植物ではない。"}, {"text": "楽譜をはいて外へ出た。", "explanation": "楽譜はくつではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e572d9e3-facd-4a81-943d-b2b5dc08b58c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
