INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35947, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や場所との距離ができるように移動する。また、関係を絶つ。", "primary_collocate": null, "pronunciation": "はなれる", "ipa": "hanaɾeɾɯ", "syllable_count": 4, "sentences": [{"text": "親から離れて一人で暮らす。", "target_word": "離れて", "complexity_tier": "T3", "furigana": "おや はな ひとり く", "sentence_source": "generated"}, {"text": "友だちと離れるのはつらい。", "target_word": "離れる", "complexity_tier": "T3", "furigana": "とも はな", "sentence_source": "generated"}, {"text": "彼はチームを離れた。", "target_word": "離れた", "complexity_tier": "T3", "furigana": "かれ はな", "sentence_source": "generated"}, {"text": "母のそばを離れたくない。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "はは はな", "sentence_source": "generated"}, {"text": "家族と離れて働いている。", "target_word": "離れて", "complexity_tier": "T3", "furigana": "かぞく はな はたら", "sentence_source": "generated"}, {"text": "政治から離れた生活をする。", "target_word": "離れた", "complexity_tier": "T3", "furigana": "せいじ はな せいかつ", "sentence_source": "generated"}, {"text": "子どもが親から離れる時期だ。", "target_word": "離れる", "complexity_tier": "T3", "furigana": "こ おや はな じき", "sentence_source": "generated"}, {"text": "仲間から離れると不安になる。", "target_word": "離れる", "complexity_tier": "T3", "furigana": "なかま はな ふあん", "sentence_source": "generated"}, {"text": "彼女は町を離れて東京へ行った。", "target_word": "離れて", "complexity_tier": "T3", "furigana": "かのじょ まち はな とうきょう い", "sentence_source": "generated"}, {"text": "二人の心は離れてしまった。", "target_word": "離れて", "complexity_tier": "T3", "furigana": "ふたり こころ はな", "sentence_source": "generated"}], "morphological_forms": [{"form": "離れた", "label": "活用"}, {"form": "離れて", "label": "活用"}, {"form": "離れられない", "label": "活用"}, {"form": "離れ離れ", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 人や場所から遠ざかる、関係を絶つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c5d3c3-f104-44cb-8fd8-6df317c352b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35950, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いいほうに かわること", "primary_collocate": null, "pronunciation": "しんぽ", "ipa": "ɕimpo", "syllable_count": 3, "sentences": [{"text": "科学の進歩はとても速い。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "かがく しんぽ はや", "sentence_source": "generated"}, {"text": "君の日本語には進歩が見える。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "きみ にほんご しんぽ み", "sentence_source": "generated"}, {"text": "技術が大きく進歩した。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "ぎじゅつ おお しんぽ", "sentence_source": "generated"}, {"text": "毎日の練習で進歩できる。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "まいにち れんしゅう しんぽ", "sentence_source": "generated"}, {"text": "少しの進歩でもうれしい。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "すこ しんぽ", "sentence_source": "generated"}, {"text": "医学の進歩で病気が治る。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "いがく しんぽ びょうき なお", "sentence_source": "generated"}, {"text": "進歩のない練習はつまらない。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "しんぽ れんしゅう", "sentence_source": "generated"}, {"text": "先生は私の進歩をほめた。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "せんせい わたし しんぽ", "sentence_source": "generated"}, {"text": "ピアノが前より進歩している。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "まえ しんぽ", "sentence_source": "generated"}, {"text": "社会の進歩を考えよう。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "しゃかい しんぽ かんが", "sentence_source": "generated"}], "morphological_forms": [{"form": "進歩する", "label": "派生"}, {"form": "進歩した", "label": "活用"}, {"form": "進歩的", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事がよいほうへ進むこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46c5d3c3-f104-44cb-8fd8-6df317c352b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35942, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "変化", "is_correct": true, "explanation": "「へんか」で、前とちがうようになること。"}, {"text": "喧嘩", "is_correct": false, "explanation": "「けんか」。最初の音が「へ」でなく「け」。"}, {"text": "返事", "is_correct": false, "explanation": "「へんじ」。最後の音が「か」でなく「じ」。"}, {"text": "電化", "is_correct": false, "explanation": "「でんか」。最初の音が「で」。"}, {"text": "陛下", "is_correct": false, "explanation": "「へいか」。二つ目の音が「ん」でなく「い」。"}], "explanations": {"変化": "「へんか」で、前とちがうようになること。", "喧嘩": "「けんか」。最初の音が「へ」でなく「け」。", "返事": "「へんじ」。最後の音が「か」でなく「じ」。", "電化": "「でんか」。最初の音が「で」。", "陛下": "「へいか」。二つ目の音が「ん」でなく「い」。"}, "sentence_index": null, "correct_answer": "変化"}, "level_3": {"options": [{"text": "変化", "is_correct": true, "explanation": "「大きな変化があった」で、様子がちがってきたことを表す。"}, {"text": "机", "is_correct": false, "explanation": "物の名前で、「様子に〜があった」に合わない。"}, {"text": "名前", "is_correct": false, "explanation": "「町の様子に名前があった」は意味が通らない。"}, {"text": "時計", "is_correct": false, "explanation": "具体物で、様子のちがいを表せない。"}], "explanations": {"変化": "「大きな変化があった」で、様子がちがってきたことを表す。", "机": "物の名前で、「様子に〜があった」に合わない。", "名前": "「町の様子に名前があった」は意味が通らない。", "時計": "具体物で、様子のちがいを表せない。"}, "sentence_index": 0, "correct_answer": "変化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この変化はとてもおいしい。", "explanation": "変化は食べ物ではないので「おいしい」と言えない。"}, {"text": "変化を三つ買って帰った。", "explanation": "変化は物ではないので買えない。"}, {"text": "私の変化は田中です。", "explanation": "変化は名前を表す言葉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df07b0d9-658b-4580-b45a-fb08be1a8f28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
