INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35945, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "近い", "is_correct": true, "explanation": "間が小さいこと。「遠い」の反対。"}, {"text": "大きい", "is_correct": false, "explanation": "大きさの言葉で、反対語ではない。"}, {"text": "速い", "is_correct": false, "explanation": "速さの言葉で、反対語ではない。"}, {"text": "深い", "is_correct": false, "explanation": "深さの言葉で、反対語ではない。"}], "correct_answer": "近い", "explanations": {"近い": "間が小さいこと。「遠い」の反対。", "大きい": "大きさの言葉で、反対語ではない。", "速い": "速さの言葉で、反対語ではない。", "深い": "深さの言葉で、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df07b0d9-658b-4580-b45a-fb08be1a8f28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35945, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "遠い", "is_correct": true, "explanation": "「とおい」。距離・時間が大きい。"}, {"text": "問い", "is_correct": false, "explanation": "「とい」。長い「おお」が短い「お」。"}, {"text": "通し", "is_correct": false, "explanation": "「とおし」。最後の音が「し」。"}, {"text": "覆い", "is_correct": false, "explanation": "「おおい」。はじめの音が「お」。"}], "explanations": {"遠い": "「とおい」。距離・時間が大きい。", "問い": "「とい」。長い「おお」が短い「お」。", "通し": "「とおし」。最後の音が「し」。", "覆い": "「おおい」。はじめの音が「お」。"}, "sentence_index": null, "correct_answer": "遠い"}, "level_3": {"options": [{"text": "遠い", "is_correct": true, "explanation": "昔の、時間が大きく離れた記憶という意味。"}, {"text": "安い", "is_correct": false, "explanation": "値段の言葉で、記憶に合わない。"}, {"text": "丸い", "is_correct": false, "explanation": "形の言葉で、記憶に合わない。"}, {"text": "甘い", "is_correct": false, "explanation": "味の言葉で、記憶に合わない。"}], "explanations": {"遠い": "昔の、時間が大きく離れた記憶という意味。", "安い": "値段の言葉で、記憶に合わない。", "丸い": "形の言葉で、記憶に合わない。", "甘い": "味の言葉で、記憶に合わない。"}, "sentence_index": 6, "correct_answer": "遠い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このかばんは遠くて重い。", "explanation": "かばんの重さと「遠い」は合わない。"}, {"text": "お茶が遠いので冷ました。", "explanation": "温度は「熱い」で表す。"}, {"text": "遠い色の服を着た。", "explanation": "色に「遠い」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df07b0d9-658b-4580-b45a-fb08be1a8f28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
