INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35946, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "離れる", "is_correct": true, "explanation": "「はなれる」。場所から遠くなる。"}, {"text": "流れる", "is_correct": false, "explanation": "「ながれる」。はじめの音がちがう。"}, {"text": "話せる", "is_correct": false, "explanation": "「はなせる」。三つ目の音がちがう。"}, {"text": "晴れる", "is_correct": false, "explanation": "「はれる」。「な」の音がない。"}], "explanations": {"離れる": "「はなれる」。場所から遠くなる。", "流れる": "「ながれる」。はじめの音がちがう。", "話せる": "「はなせる」。三つ目の音がちがう。", "晴れる": "「はれる」。「な」の音がない。"}, "sentence_index": null, "correct_answer": "離れる"}, "level_3": {"options": [{"text": "離れる", "is_correct": true, "explanation": "危ないので線路から遠くへ移る、という意味。"}, {"text": "近づく", "is_correct": false, "explanation": "危ないのに線路に近づくのは意味が合わない。"}, {"text": "座る", "is_correct": false, "explanation": "「線路から座る」は言わない。"}, {"text": "食べる", "is_correct": false, "explanation": "「線路から食べる」は意味が通らない。"}], "explanations": {"離れる": "危ないので線路から遠くへ移る、という意味。", "近づく": "危ないのに線路に近づくのは意味が合わない。", "座る": "「線路から座る」は言わない。", "食べる": "「線路から食べる」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "離れる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝パンを離れて食べる。", "explanation": "パンを食べる動作に「離れる」は合わない。"}, {"text": "本を離れて読んだ。", "explanation": "読む対象に「離れる」は使えない。"}, {"text": "雨が離れて降ってきた。", "explanation": "雨が降る様子に「離れる」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df07b0d9-658b-4580-b45a-fb08be1a8f28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35946, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "危ないから線路に離れる。", "corrected_sentence": "危ないから線路から離れる。", "error_description": "「離れる」は起点を「から」か「を」で示し、「に」は使わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "離れて", "is_correct": true, "explanation": "「立って」につなぐて形。"}, {"text": "離れる", "is_correct": false, "explanation": "辞書形で、次の動詞につながらない。"}, {"text": "離れた", "is_correct": false, "explanation": "過去形で、お願いの文に合わない。"}, {"text": "離れない", "is_correct": false, "explanation": "否定形で、火から離れる意味にならない。"}], "correct_form": "離れて", "base_form": "離れる", "form_label": "て形", "sentence_index": 1, "explanations": {"離れて": "「立って」につなぐて形。", "離れる": "辞書形で、次の動詞につながらない。", "離れた": "過去形で、お願いの文に合わない。", "離れない": "否定形で、火から離れる意味にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df07b0d9-658b-4580-b45a-fb08be1a8f28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35946, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "離れる起点を示す。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、「離れる」と合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を表し、非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、「離れる」の起点にならない。"}], "correct_answer": "から", "explanations": {"から": "離れる起点を示す。", "に": "着点を表し、「離れる」と合わない。", "で": "場所・手段を表し、非文。", "へ": "方向を表し、「離れる」の起点にならない。"}, "error_tags": {"に": "source_vs_goal", "で": "instrument", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "近づく", "is_correct": true, "explanation": "距離が小さくなること。「離れる」の反対。"}, {"text": "走る", "is_correct": false, "explanation": "動き方の言葉で、反対語ではない。"}, {"text": "休む", "is_correct": false, "explanation": "反対の関係にない言葉。"}, {"text": "立つ", "is_correct": false, "explanation": "姿勢の言葉で、反対語ではない。"}], "correct_answer": "近づく", "explanations": {"近づく": "距離が小さくなること。「離れる」の反対。", "走る": "動き方の言葉で、反対語ではない。", "休む": "反対の関係にない言葉。", "立つ": "姿勢の言葉で、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df07b0d9-658b-4580-b45a-fb08be1a8f28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35946, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "離れる", "is_correct": true, "explanation": "「はなれる」。遠くへ移る。"}, {"text": "剥がれる", "is_correct": false, "explanation": "「はがれる」。二つ目の音がちがう。"}, {"text": "外れる", "is_correct": false, "explanation": "「はずれる」。二つ目の音がちがう。"}, {"text": "慣れる", "is_correct": false, "explanation": "「なれる」。はじめの「は」の音がない。"}], "explanations": {"離れる": "「はなれる」。遠くへ移る。", "剥がれる": "「はがれる」。二つ目の音がちがう。", "外れる": "「はずれる」。二つ目の音がちがう。", "慣れる": "「なれる」。はじめの「は」の音がない。"}, "sentence_index": null, "correct_answer": "離れる"}, "level_3": {"options": [{"text": "離れて", "is_correct": true, "explanation": "故郷から遠くへ移って三年、という意味。"}, {"text": "食べて", "is_correct": false, "explanation": "「故郷を食べて」は意味が通らない。"}, {"text": "書いて", "is_correct": false, "explanation": "「故郷を書いて三年」は不自然。"}, {"text": "洗って", "is_correct": false, "explanation": "「故郷を洗って」は意味が通らない。"}], "explanations": {"離れて": "故郷から遠くへ移って三年、という意味。", "食べて": "「故郷を食べて」は意味が通らない。", "書いて": "「故郷を書いて三年」は不自然。", "洗って": "「故郷を洗って」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "離れて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お湯を離れてお茶を作った。", "explanation": "お茶を作る材料に「離れる」は使えない。"}, {"text": "この花はいい匂いが離れる。", "explanation": "匂いの説明に「離れる」は合わない。"}, {"text": "宿題を離れて先生に出した。", "explanation": "宿題を出す動作に「離れる」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df07b0d9-658b-4580-b45a-fb08be1a8f28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
