INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35978, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "数が二つ以上あること。", "primary_collocate": null, "pronunciation": "ふくすう", "ipa": "ɸɯkɯsɯː", "syllable_count": 4, "sentences": [{"text": "答えは複数あります。", "target_word": "複数", "complexity_tier": "T3", "furigana": "こた ふくすう", "sentence_source": "generated"}, {"text": "複数の人がそう言った。", "target_word": "複数", "complexity_tier": "T3", "furigana": "ふくすう ひと い", "sentence_source": "generated"}, {"text": "この問題には複数の答えがある。", "target_word": "複数", "complexity_tier": "T3", "furigana": "もんだい ふくすう こた", "sentence_source": "generated"}, {"text": "英語の名詞には複数の形がある。", "target_word": "複数", "complexity_tier": "T3", "furigana": "えいご めいし ふくすう かたち", "sentence_source": "generated"}, {"text": "複数の店を見て比べた。", "target_word": "複数", "complexity_tier": "T3", "furigana": "ふくすう みせ み くら", "sentence_source": "generated"}, {"text": "参加者は複数でもいい。", "target_word": "複数", "complexity_tier": "T3", "furigana": "さんかしゃ ふくすう", "sentence_source": "generated"}, {"text": "彼は複数の言葉を話せる。", "target_word": "複数", "complexity_tier": "T3", "furigana": "かれ ふくすう ことば はな", "sentence_source": "generated"}, {"text": "複数選んでもかまいません。", "target_word": "複数", "complexity_tier": "T3", "furigana": "ふくすう えら", "sentence_source": "generated"}, {"text": "同じ意見が複数出た。", "target_word": "複数", "complexity_tier": "T3", "furigana": "おな いけん ふくすう で", "sentence_source": "generated"}, {"text": "複数の友達から手紙が来た。", "target_word": "複数", "complexity_tier": "T3", "furigana": "ふくすう ともだち てがみ き", "sentence_source": "generated"}], "morphological_forms": [{"form": "複数形", "label": "派生"}, {"form": "複数人", "label": "派生"}, {"form": "複数回", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 数が二つ以上あること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code: