INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51509, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "給食", "is_correct": true, "explanation": "正解。「きゅうしょく」と読む。"}, {"text": "休息", "is_correct": false, "explanation": "「きゅうそく」と読む。「しょ」が「そ」に変わる一モーラ差。"}, {"text": "教職", "is_correct": false, "explanation": "「きょうしょく」と読む。「きゅ」が「きょ」に変わる一モーラ差。"}, {"text": "昼食", "is_correct": false, "explanation": "「ちゅうしょく」と読む。「きゅ」が「ちゅ」に変わる一モーラ差。"}, {"text": "就職", "is_correct": false, "explanation": "「しゅうしょく」と読む。「きゅ」が「しゅ」に変わる一モーラ差。"}], "explanations": {"給食": "正解。「きゅうしょく」と読む。", "休息": "「きゅうそく」と読む。「しょ」が「そ」に変わる一モーラ差。", "教職": "「きょうしょく」と読む。「きゅ」が「きょ」に変わる一モーラ差。", "昼食": "「ちゅうしょく」と読む。「きゅ」が「ちゅ」に変わる一モーラ差。", "就職": "「しゅうしょく」と読む。「きゅ」が「しゅ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "給食"}, "level_3": {"options": [{"text": "給食", "is_correct": true, "explanation": "学校の昼ごはんの献立がカレーという文に合う。"}, {"text": "宿題", "is_correct": false, "explanation": "意味：宿題がカレーというのは意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "意味：天気がカレーではありえない。"}, {"text": "授業", "is_correct": false, "explanation": "意味：授業がカレーというのは不自然。"}], "explanations": {"給食": "学校の昼ごはんの献立がカレーという文に合う。", "宿題": "意味：宿題がカレーというのは意味が通らない。", "天気": "意味：天気がカレーではありえない。", "授業": "意味：授業がカレーというのは不自然。"}, "sentence_index": 0, "correct_answer": "給食"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "給食を牛乳が出る。", "explanation": "助詞の混同：場面を表すには「で」が必要で、「を」では非文。"}, {"text": "一冊の給食を食べた。", "explanation": "助数詞の誤り：給食は「冊」で数えない。"}, {"text": "給食で牛乳が出たている。", "explanation": "活用の誤り：「出たている」は誤った形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b098110-0885-40ef-b2ee-26dcaca0a304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_erro