INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35711, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "レート", "is_correct": true, "explanation": "正解。読みは「れーと」。"}, {"text": "ノート", "is_correct": false, "explanation": "読みは「のーと」。「れ」が「の」に変わる一モーラ差。"}, {"text": "ルート", "is_correct": false, "explanation": "読みは「るーと」。「れ」が「る」に変わる一モーラ差。"}, {"text": "ゲート", "is_correct": false, "explanation": "読みは「げーと」。「れ」が「げ」に変わる一モーラ差。"}, {"text": "レース", "is_correct": false, "explanation": "読みは「れーす」。「と」が「す」に変わる一モーラ差。"}, {"text": "デート", "is_correct": false, "explanation": "読みは「でーと」。「れ」が「で」に変わる一モーラ差。"}], "explanations": {"レート": "正解。読みは「れーと」。", "ノート": "読みは「のーと」。「れ」が「の」に変わる一モーラ差。", "ルート": "読みは「るーと」。「れ」が「る」に変わる一モーラ差。", "ゲート": "読みは「げーと」。「れ」が「げ」に変わる一モーラ差。", "レース": "読みは「れーす」。「と」が「す」に変わる一モーラ差。", "デート": "読みは「でーと」。「れ」が「で」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "レート"}, "level_3": {"options": [{"text": "レート", "is_correct": true, "explanation": "意味：ドルと他の通貨の交換比率を調べたという文。"}, {"text": "天気", "is_correct": false, "explanation": "意味：ドルの天気という概念はない。"}, {"text": "背中", "is_correct": false, "explanation": "意味：ドルの背中は存在しない。"}, {"text": "歌", "is_correct": false, "explanation": "連語：「ドルの歌を調べた」は文脈に合わない。"}], "explanations": {"レート": "意味：ドルと他の通貨の交換比率を調べたという文。", "天気": "意味：ドルの天気という概念はない。", "背中": "意味：ドルの背中は存在しない。", "歌": "連語：「ドルの歌を調べた」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "レート"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このレートはとても良いだった。", "explanation": "活用の誤り：形容詞「良い」に「だった」は付かず、「良かった」とする。"}, {"text": "このレートでとても良い。", "explanation": "助詞の混同：主題を示す「は」が必要で、「で」では文が成立しない。"}, {"text": "とても良いこのはレート。", "explanation": "語順の誤り：「この」と「は」の位置が崩れ、主題—解説構造が壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e965c7d-0d1a-48bb-add4-57cc2d6f6fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
