INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35711, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "自動詞「上がる」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「上がる」は自動詞なので目的語の「を」はとれない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表し、この位置では非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、主語の位置には入らない。"}], "correct_answer": "が", "explanations": {"が": "自動詞「上がる」の主語を示す。", "を": "「上がる」は自動詞なので目的語の「を」はとれない。", "で": "手段・場所を表し、この位置では非文。", "へ": "方向を表し、主語の位置には入らない。"}, "error_tags": {"を": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e965c7d-0d1a-48bb-add4-57cc2d6f6fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35711, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "レート", "is_correct": true, "explanation": "正解。読みは「れーと」。"}, {"text": "レーン", "is_correct": false, "explanation": "読みは「れーん」。「と」が「ん」に変わる一モーラ差。"}, {"text": "セット", "is_correct": false, "explanation": "読みは「せっと」。長音が促音に、「れ」が「せ」に変わる。"}, {"text": "テープ", "is_correct": false, "explanation": "読みは「てーぷ」。「れ」「と」が「て」「ぷ」に変わる。"}, {"text": "ケーキ", "is_correct": false, "explanation": "読みは「けーき」。音の型が似ている。"}], "explanations": {"レート": "正解。読みは「れーと」。", "レーン": "読みは「れーん」。「と」が「ん」に変わる一モーラ差。", "セット": "読みは「せっと」。長音が促音に、「れ」が「せ」に変わる。", "テープ": "読みは「てーぷ」。「れ」「と」が「て」「ぷ」に変わる。", "ケーキ": "読みは「けーき」。音の型が似ている。"}, "sentence_index": null, "correct_answer": "レート"}, "level_3": {"options": [{"text": "レート", "is_correct": true, "explanation": "意味：交換比率をまとめた表を見せてもらった。"}, {"text": "雨", "is_correct": false, "explanation": "意味：雨の表を見せてもらうのは不自然。"}, {"text": "犬", "is_correct": false, "explanation": "意味：犬の表という概念はない。"}, {"text": "声", "is_correct": false, "explanation": "意味：声の表は存在しない。"}], "explanations": {"レート": "意味：交換比率をまとめた表を見せてもらった。", "雨": "意味：雨の表を見せてもらうのは不自然。", "犬": "意味：犬の表という概念はない。", "声": "意味：声の表は存在しない。"}, "sentence_index": 6, "correct_answer": "レート"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ニュースでレートを話を聞いた。", "explanation": "助詞の混同：「レートの話」とすべきで、「を」が二つ並び非文。"}, {"text": "ニュースでレートの話を聞いている昨日。", "explanation": "アスペクト・語順の誤り：「昨日」と「ている」が合わず、位置もおかしい。"}, {"text": "ニュースでレートの一匹の話を聞いた。", "explanation": "助数詞の誤り：比率に「匹」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e965c7d-0d1a-48bb-add4-57cc2d6f6fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = 