INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35057, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「変える」の目的語「店の中」を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格にすると他動詞の目的語にならず非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、変える対象を示さない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表し、比較の相手がなく非文。"}], "correct_answer": "を", "explanations": {"を": "他動詞「変える」の目的語「店の中」を示す。", "が": "主格にすると他動詞の目的語にならず非文。", "へ": "方向を表し、変える対象を示さない。", "より": "比較を表し、比較の相手がなく非文。"}, "error_tags": {"が": "topic_vs_subject", "へ": "direction", "より": "other"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "維持する", "is_correct": true, "explanation": "対義語：同じ状態を続ける。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "関係なし：水の中を進む動作。"}, {"text": "聞く", "is_correct": false, "explanation": "関係なし：音を耳で受ける動作。"}, {"text": "洗う", "is_correct": false, "explanation": "関係なし：汚れを落とす動作。"}], "correct_answer": "維持する", "explanations": {"維持する": "対義語：同じ状態を続ける。", "泳ぐ": "関係なし：水の中を進む動作。", "聞く": "関係なし：音を耳で受ける動作。", "洗う": "関係なし：汚れを落とす動作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e965c7d-0d1a-48bb-add4-57cc2d6f6fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
