INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35156, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "道や線などが、とぎれずに目的の所までつながる。", "primary_collocate": null, "pronunciation": "つうずる", "ipa": "tsɯːzɯɾɯ", "syllable_count": 4, "sentences": [{"text": "この道は駅に通ずる。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "みち えき つう", "sentence_source": "generated"}, {"text": "すべての道はローマに通ずる。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "みち つう", "sentence_source": "generated"}, {"text": "海に通ずる川を下った。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "うみ つう かわ くだ", "sentence_source": "generated"}, {"text": "地下道は隣の駅に通ずる。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "ちかどう となり えき つう", "sentence_source": "generated"}, {"text": "裏の門は公園に通ずる。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "うら もん こうえん つう", "sentence_source": "generated"}, {"text": "山へ通ずる道は細い。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "やま つう みち ほそ", "sentence_source": "generated"}, {"text": "このトンネルは町に通ずる。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "まち つう", "sentence_source": "generated"}, {"text": "二階に通ずる階段がある。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "にかい つう かいだん", "sentence_source": "generated"}, {"text": "村へ通ずる橋が新しくなった。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "むら つう はし あたら", "sentence_source": "generated"}, {"text": "その廊下は庭に通ずる。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "ろうか にわ つう", "sentence_source": "generated"}], "morphological_forms": [{"form": "通じる", "label": "派生"}, {"form": "通じた", "label": "活用"}, {"form": "通じて", "label": "活用"}, {"form": "通じない", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 道などが途切れずある所へつながる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f532336c-988f-4cd4-87c0-b340443a19a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35113, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "以前", "is_correct": true, "explanation": "正解。「いぜん」と読む。"}, {"text": "意見", "is_correct": false, "explanation": "「いけん」と読み、「ぜ」が「け」に変わった一モーラ違いの語。"}, {"text": "遺伝", "is_correct": false, "explanation": "「いでん」と読み、「ぜ」が「で」に変わった一モーラ違いの語。"}, {"text": "自然", "is_correct": false, "explanation": "「しぜん」と読み、「い」が「し」に変わった一モーラ違いの語。"}, {"text": "威厳", "is_correct": false, "explanation": "「いげん」と読み、「ぜ」が「げ」に変わった一モーラ違いの語。"}], "explanations": {"以前": "正解。「いぜん」と読む。", "意見": "「いけん」と読み、「ぜ」が「け」に変わった一モーラ違いの語。", "遺伝": "「いでん」と読み、「ぜ」が「で」に変わった一モーラ違いの語。", "自然": "「しぜん」と読み、「い」が「し」に変わった一モーラ違いの語。", "威厳": "「いげん」と読み、「ぜ」が「げ」に変わった一モーラ違いの語。"}, "sentence_index": null, "correct_answer": "以前"}, "level_3": {"options": [{"text": "以前", "is_correct": true, "explanation": "「住んでいた」という過去の状態に合う。"}, {"text": "明日", "is_correct": false, "explanation": "過去形「住んでいた」と合わない。"}, {"text": "将来", "is_correct": false, "explanation": "未来を表し、過去形と矛盾する。"}, {"text": "今後", "is_correct": false, "explanation": "これから先を表し、過去形と合わない。"}], "explanations": {"以前": "「住んでいた」という過去の状態に合う。", "明日": "過去形「住んでいた」と合わない。", "将来": "未来を表し、過去形と矛盾する。", "今後": "これから先を表し、過去形と合わない。"}, "sentence_index": 0, "correct_answer": "以前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "以前に駅へ行ってください。", "explanation": "「以前」は過去を表すので、これからの依頼には使えない。"}, {"text": "この本は以前がおもしろい。", "explanation": "「以前」を本の性質のように使っており意味が通らない。"}, {"text": "来週の以前に宿題を出す。", "explanation": "未来の時点「来週」と組み合わせる使い方は不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35113, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "以前は明日、東京へ行く。", "corrected_sentence": "以前、東京へ行ったことがある。", "error_description": "「以前」は過去を表すのに、未来の「明日」「行く」と一緒に使っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35113, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "より", "options": [{"text": "より", "is_correct": true, "explanation": "比較の基準を表し「以前より」で「前と比べて」の意味になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す助詞で、この位置では非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、時を表す「以前」には付かない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表し、ここでは意味が通らない。"}], "correct_answer": "より", "explanations": {"より": "比較の基準を表し「以前より」で「前と比べて」の意味になる。", "を": "目的語を表す助詞で、この位置では非文。", "へ": "方向を表し、時を表す「以前」には付かない。", "で": "手段や場所を表し、ここでは意味が通らない。"}, "error_tags": {"を": "object_marking", "へ": "direction", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以後", "is_correct": true, "explanation": "「以前」の反対で、ある時より後を表す。"}, {"text": "昔", "is_correct": false, "explanation": "「以前」とほぼ同じ意味で、反対ではない。"}, {"text": "前", "is_correct": false, "explanation": "「以前」と近い意味で、反対ではない。"}, {"text": "大きい", "is_correct": false, "explanation": "大きさを表す語で、時の前後とは関係がない。"}], "correct_answer": "以後", "explanations": {"以後": "「以前」の反対で、ある時より後を表す。", "昔": "「以前」とほぼ同じ意味で、反対ではない。", "前": "「以前」と近い意味で、反対ではない。", "大きい": "大きさを表す語で、時の前後とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35113, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "以前", "is_correct": true, "explanation": "正解。「いぜん」と読む。"}, {"text": "慈善", "is_correct": false, "explanation": "「じぜん」と読み、最初の「い」が「じ」に変わった一モーラ違いの語。"}, {"text": "緯線", "is_correct": false, "explanation": "「いせん」と読み、「ぜ」が清音「せ」になった一モーラ違いの語。"}, {"text": "以南", "is_correct": false, "explanation": "「いなん」と読み、「ぜ」が「な」に変わった一モーラ違いの語。"}, {"text": "意見", "is_correct": false, "explanation": "「いけん」と読み、「ぜ」が「け」に変わった一モーラ違いの語。"}], "explanations": {"以前": "正解。「いぜん」と読む。", "慈善": "「じぜん」と読み、最初の「い」が「じ」に変わった一モーラ違いの語。", "緯線": "「いせん」と読み、「ぜ」が清音「せ」になった一モーラ違いの語。", "以南": "「いなん」と読み、「ぜ」が「な」に変わった一モーラ違いの語。", "意見": "「いけん」と読み、「ぜ」が「け」に変わった一モーラ違いの語。"}, "sentence_index": null, "correct_answer": "以前"}, "level_3": {"options": [{"text": "以前", "is_correct": true, "explanation": "「以前と変わらず」で、前と同じ様子を表す。"}, {"text": "頭", "is_correct": false, "explanation": "「頭と変わらず元気だ」は意味が通らない。"}, {"text": "背中", "is_correct": false, "explanation": "「背中と変わらず」は意味をなさない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気と変わらず元気だ」は不自然。"}], "explanations": {"以前": "「以前と変わらず」で、前と同じ様子を表す。", "頭": "「頭と変わらず元気だ」は意味が通らない。", "背中": "「背中と変わらず」は意味をなさない。", "天気": "「天気と変わらず元気だ」は不自然。"}, "sentence_index": 6, "correct_answer": "以前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "以前は明日の天気を知らせる。", "explanation": "「以前」は過去を表すのに、未来の「明日」のことを今行う文に使っており誤り。"}, {"text": "このりんごは以前だ。", "explanation": "「以前」を物の性質として述語に使っており誤り。"}, {"text": "彼は以前に背が高い。", "explanation": "「以前に」を程度の副詞のように使っており意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35113, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "以前より、来年は旅行する。", "corrected_sentence": "以前より、よく旅行するようになった。", "error_description": "「以前より」は過去と今を比べる表現なのに、未来の「来年」と組み合わせている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35113, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「書く」の目的語「手紙」を表す。"}, {"text": "が", "is_correct": false, "explanation": "主格を表し、「手紙が書いた」は非文になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、書く対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "名詞修飾の助詞で、「手紙の書いた」は非文。"}], "correct_answer": "を", "explanations": {"を": "他動詞「書く」の目的語「手紙」を表す。", "が": "主格を表し、「手紙が書いた」は非文になる。", "へ": "方向を表し、書く対象を示せない。", "の": "名詞修飾の助詞で、「手紙の書いた」は非文。"}, "error_tags": {"が": "object_marking", "へ": "direction", "で": "instrument"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以降", "is_correct": true, "explanation": "ある時より後を表し、「以前」の反対になる。"}, {"text": "過去", "is_correct": false, "explanation": "「以前」に近い意味で、反対ではない。"}, {"text": "かつて", "is_correct": false, "explanation": "「以前」と似た意味の語で、反対ではない。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す語で、時の前後と関係ない。"}], "correct_answer": "以降", "explanations": {"以降": "ある時より後を表し、「以前」の反対になる。", "過去": "「以前」に近い意味で、反対ではない。", "かつて": "「以前」と似た意味の語で、反対ではない。", "重い": "重さを表す語で、時の前後と関係ない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35132, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "読み書き", "is_correct": true, "explanation": "正解。「よみかき」と読む。"}, {"text": "読み方", "is_correct": false, "explanation": "「よみかた」と読み、語末の「き」が「た」に変わった一モーラ違いの語。"}, {"text": "読みかけ", "is_correct": false, "explanation": "「よみかけ」と読み、語末の「き」が「け」に変わった一モーラ違いの語。"}, {"text": "横書き", "is_correct": false, "explanation": "「よこがき」と読み、「みか」が「こが」に変わった（二モーラ違いで判定で落ちうる）語。"}], "explanations": {"読み書き": "正解。「よみかき」と読む。", "読み方": "「よみかた」と読み、語末の「き」が「た」に変わった一モーラ違いの語。", "読みかけ": "「よみかけ」と読み、語末の「き」が「け」に変わった一モーラ違いの語。", "横書き": "「よこがき」と読み、「みか」が「こが」に変わった（二モーラ違いで判定で落ちうる）語。"}, "sentence_index": null, "correct_answer": "読み書き"}, "level_3": {"options": [{"text": "読み書き", "is_correct": true, "explanation": "漢字を読んだり書いたりする練習として自然。"}, {"text": "料理", "is_correct": false, "explanation": "「漢字の料理」は意味が通らない。"}, {"text": "散歩", "is_correct": false, "explanation": "「漢字の散歩」は意味をなさない。"}, {"text": "洗濯", "is_correct": false, "explanation": "「漢字の洗濯」は不自然。"}], "explanations": {"読み書き": "漢字を読んだり書いたりする練習として自然。", "料理": "「漢字の料理」は意味が通らない。", "散歩": "「漢字の散歩」は意味をなさない。", "洗濯": "「漢字の洗濯」は不自然。"}, "sentence_index": 0, "correct_answer": "読み書き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "読み書きで駅まで歩いた。", "explanation": "「読み書き」を移動の手段のように使っており誤り。"}, {"text": "このスープは読み書きがする。", "explanation": "食べ物の性質のように使っていて意味が通らない。"}, {"text": "公園で読み書きを投げた。", "explanation": "物のように「投げる」の目的語にしており誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
