INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35132, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "読み書き", "is_correct": true, "explanation": "正解。「よみかき」と読む。"}, {"text": "読み替え", "is_correct": false, "explanation": "「よみかえ」と読み、語末の「き」が「え」に変わった一モーラ違いの語。"}, {"text": "読みかけ", "is_correct": false, "explanation": "「よみかけ」と読み、語末の「き」が「け」に変わった一モーラ違いの語。"}, {"text": "縦書き", "is_correct": false, "explanation": "「たてがき」と読み、音の大きく異なる（判定で落ちうる）語。"}], "explanations": {"読み書き": "正解。「よみかき」と読む。", "読み替え": "「よみかえ」と読み、語末の「き」が「え」に変わった一モーラ違いの語。", "読みかけ": "「よみかけ」と読み、語末の「き」が「け」に変わった一モーラ違いの語。", "縦書き": "「たてがき」と読み、音の大きく異なる（判定で落ちうる）語。"}, "sentence_index": null, "correct_answer": "読み書き"}, "level_3": {"options": [{"text": "読み書き", "is_correct": true, "explanation": "祖母と一緒にする活動として「読み書きをした」が自然。"}, {"text": "眠り", "is_correct": false, "explanation": "「眠りをした」は日本語として不自然。"}, {"text": "昼", "is_correct": false, "explanation": "「昼をした」は意味が通らない。"}, {"text": "机", "is_correct": false, "explanation": "物であり「机をした」は意味をなさない。"}], "explanations": {"読み書き": "祖母と一緒にする活動として「読み書きをした」が自然。", "眠り": "「眠りをした」は日本語として不自然。", "昼": "「昼をした」は意味が通らない。", "机": "物であり「机をした」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "読み書き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "読み書きが空を飛んでいる。", "explanation": "行為である「読み書き」を飛ぶものとして扱っており誤り。"}, {"text": "この部屋は読み書きが広い。", "explanation": "部屋の広さとは関係がなく、意味が通らない。"}, {"text": "読み書きを冷蔵庫に入れた。", "explanation": "物のように扱っていて誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batc