INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52219, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とてもびっくりするような、すごいこと。", "primary_collocate": null, "pronunciation": "げきてき", "ipa": "ɡekiteki", "syllable_count": 4, "sentences": [{"text": "劇的だった。", "target_word": "劇的だ", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "劇的な試合だった。", "target_word": "劇的な", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "結末は劇的です。", "target_word": "劇的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "とても劇的な話でした。", "target_word": "劇的な", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彼の勝ち方は劇的だった。", "target_word": "劇的だ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "最後に劇的に逆転した。", "target_word": "劇的に", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "劇的な再会に、みんなが驚いた。", "target_word": "劇的な", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "劇的で感動的な物語を読んでいる。", "target_word": "劇的で", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "試合は最後の一秒で劇的に決まったと聞いた。", "target_word": "劇的に", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "映画のような劇的な出来事が、本当に私の身に起こった。", "target_word": "劇的な", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "劇的な", "label": "活用"}, {"form": "劇的に", "label": "活用"}, {"form": "劇的だ", "label": "活用"}, {"form": "劇的で", "label": "活用"}], "register": "plain", "sense_fingerprint": "形状詞 | とてもびっくりするようなこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bafd5310-271f-46d7-a9d3-884a595dca6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EX