INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36965, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、主語には使えません。"}, {"text": "と", "is_correct": false, "explanation": "「水と生成する」では意味が通りません。"}, {"text": "が", "is_correct": true, "explanation": "作り出される「水」が主語なので「が」が合います。"}, {"text": "に", "is_correct": false, "explanation": "「水に生成する」は不自然です。"}], "correct_answer": "が", "explanations": {"へ": "「へ」は方向を表すので、主語には使えません。", "と": "「水と生成する」では意味が通りません。", "が": "作り出される「水」が主語なので「が」が合います。", "に": "「水に生成する」は不自然です。"}, "error_tags": {"へ": "direction", "と": "companion", "に": "target"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "発生", "is_correct": false, "explanation": "「発生」は近い意味で、反対ではありません。"}, {"text": "記録", "is_correct": false, "explanation": "「記録」は反対ではありません。"}, {"text": "説明", "is_correct": false, "explanation": "「説明」は反対ではありません。"}, {"text": "消滅", "is_correct": true, "explanation": "作り出す「生成」の反対は、なくなる「消滅」です。"}], "correct_answer": "消滅", "explanations": {"発生": "「発生」は近い意味で、反対ではありません。", "記録": "「記録」は反対ではありません。", "説明": "「説明」は反対ではありません。", "消滅": "作り出す「生成」の反対は、なくなる「消滅」です。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8ff9c99-a30b-43a3-8a2a-fab66ea99ca6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36964, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生成", "is_correct": true, "explanation": "「生成」が聞こえた語です。"}, {"text": "先生", "is_correct": false, "explanation": "「先生」（せんせい）は別の語で、音が一つ違います。"}, {"text": "制裁", "is_correct": false, "explanation": "「制裁」（せいさい）は別の語で、音が一つ違います。"}, {"text": "制定", "is_correct": false, "explanation": "「制定」（せいてい）は別の語で、音が一つ違います。"}, {"text": "税制", "is_correct": false, "explanation": "「税制」（ぜいせい）は別の語で、音が一つ違います。"}], "explanations": {"生成": "「生成」が聞こえた語です。", "先生": "「先生」（せんせい）は別の語で、音が一つ違います。", "制裁": "「制裁」（せいさい）は別の語で、音が一つ違います。", "制定": "「制定」（せいてい）は別の語で、音が一つ違います。", "税制": "「税制」（ぜいせい）は別の語で、音が一つ違います。"}, "sentence_index": null, "correct_answer": "生成"}, "level_3": {"options": [{"text": "食べる", "is_correct": false, "explanation": "画像は食べるものではありません。"}, {"text": "生成する", "is_correct": true, "explanation": "「画像を作り出す」という意味なので「生成する」が合います。"}, {"text": "洗う", "is_correct": false, "explanation": "画像は洗うものではありません。"}, {"text": "運転する", "is_correct": false, "explanation": "画像は運転するものではありません。"}], "explanations": {"食べる": "画像は食べるものではありません。", "生成する": "「画像を作り出す」という意味なので「生成する」が合います。", "洗う": "画像は洗うものではありません。", "運転する": "画像は運転するものではありません。"}, "sentence_index": 0, "correct_answer": "生成する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は毎朝、近くの公園を生成して健康を保っている。", "explanation": "「生成」は作り出すことで、歩くという意味では使えません。"}, {"text": "このペンは字が生成に書きやすい。", "explanation": "「生成に」は様子を表す言い方ではなく、「書きやすい」につながりません。"}, {"text": "ホテルの部屋を電話で生成した。", "explanation": "「生成」に予約するという意味はありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8ff9c99-a30b-43a3-8a2a-fab66ea99ca6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
