INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36964, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "が", "is_correct": false, "explanation": "「生成が学びます」では主語になり、意味が通りません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「学びます」の対象にはなりません。"}, {"text": "を", "is_correct": true, "explanation": "「文字の生成」の後に、学ぶ対象を表す「を」が必要です。"}, {"text": "と", "is_correct": false, "explanation": "「と」は一緒にする相手を表し、ここでは合いません。"}], "correct_answer": "を", "explanations": {"が": "「生成が学びます」では主語になり、意味が通りません。", "へ": "「へ」は方向を表すので、「学びます」の対象にはなりません。", "を": "「文字の生成」の後に、学ぶ対象を表す「を」が必要です。", "と": "「と」は一緒にする相手を表し、ここでは合いません。"}, "error_tags": {"が": "subject", "へ": "direction", "と": "companion"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "作成した", "is_correct": false, "explanation": "「作成した」は似た意味で、反対ではありません。"}, {"text": "保存した", "is_correct": false, "explanation": "「保存した」は反対の意味ではありません。"}, {"text": "発見した", "is_correct": false, "explanation": "「発見した」は反対の意味ではありません。"}, {"text": "消去した", "is_correct": true, "explanation": "作り出す「生成した」の反対は、なくす「消去した」です。"}], "correct_answer": "消去した", "explanations": {"作成した": "「作成した」は似た意味で、反対ではありません。", "保存した": "「保存した」は反対の意味ではありません。", "発見した": "「発見した」は反対の意味ではありません。", "消去した": "作り出す「生成した」の反対は、なくす「消去した」です。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8ff9c99-a30b-43a3-8a2a-fab66ea99ca6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
