INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52968, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "ソート", "is_correct": false, "explanation": "「ソート」（そーと）は別の語で、音が一つ違います。"}, {"text": "ロート", "is_correct": false, "explanation": "「ロート」（ろーと）は別の語で、音が一つ違います。"}, {"text": "オート", "is_correct": true, "explanation": "「オート」が聞こえた語です。"}, {"text": "オーク", "is_correct": false, "explanation": "「オーク」（おーく）は別の語で、音が一つ違います。"}, {"text": "オーム", "is_correct": false, "explanation": "「オーム」（おーむ）は別の語で、音が一つ違います。"}], "explanations": {"ソート": "「ソート」（そーと）は別の語で、音が一つ違います。", "ロート": "「ロート」（ろーと）は別の語で、音が一つ違います。", "オート": "「オート」が聞こえた語です。", "オーク": "「オーク」（おーく）は別の語で、音が一つ違います。", "オーム": "「オーム」（おーむ）は別の語で、音が一つ違います。"}, "sentence_index": null, "correct_answer": "オート"}, "level_3": {"options": [{"text": "ミニ", "is_correct": false, "explanation": "「ミニモード」はこの文に合いません。"}, {"text": "プレ", "is_correct": false, "explanation": "「プレモード」はこの文に合いません。"}, {"text": "オート", "is_correct": true, "explanation": "「オートモード」は自動で動く設定の名前です。"}, {"text": "ベビー", "is_correct": false, "explanation": "「ベビーモード」はこの文に合いません。"}], "explanations": {"ミニ": "「ミニモード」はこの文に合いません。", "プレ": "「プレモード」はこの文に合いません。", "オート": "「オートモード」は自動で動く設定の名前です。", "ベビー": "「ベビーモード」はこの文に合いません。"}, "sentence_index": 6, "correct_answer": "オート"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このオートドアは、人がいつも手で押さないと開かない。", "explanation": "「オート」は自動の意味なので、手で押すドアには使えません。"}, {"text": "オートクルーズは、ハンドルを一日中ずっと手で回す機能だ。", "explanation": "「オート」は自動の意味なので、手で回す機能とは合いません。"}, {"text": "オートロックは、毎回鍵で自分で閉める必要がある仕組みだ。", "explanation": "「オート」は自動の意味なので、自分で閉める仕組みとは合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8ff9c99-a30b-43a3-8a2a-fab66ea99ca6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, vali