INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37945, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が生まれる、いちばんもととなる部分や力。", "primary_collocate": null, "pronunciation": "こんげん", "ipa": "koŋɡeɴ", "syllable_count": 4, "sentences": [{"text": "その姿を凝視する子供の瞳には、生命が持つ根源的な逞しさへの畏敬の念が宿っている。", "target_word": "根源", "complexity_tier": "T6", "furigana": "こんげん", "sentence_source": "mined"}, {"text": "そこには、理屈や打算といった人為的な思惑が介在する余地はなく、ただ生命の根源的な渇望と、眼前の事物に対する純粋な受容があるのみだ。", "target_word": "根源", "complexity_tier": "T6", "furigana": "こんげん", "sentence_source": "mined"}, {"text": "戦争の根源には、貧しさがあると言われる。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "この問題の根源を、みんなで考えてみよう。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "生命の根源は、水にあると考えられている。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "悲しみの根源を知れば、心が軽くなる。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "彼は争いの根源を取り除こうと努力した。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "力の根源は、毎日の小さな努力だ。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "すべての悪の根源は欲だという人もいる。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}, {"text": "原因を探ると、根源は意外に単純だった。", "target_word": "根源", "complexity_tier": "T3", "furigana": "こんげん", "sentence_source": "generated"}], "morphological_forms": [{"form": "根源的", "label": "派生"}, {"form": "根源的な", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事を生む一番のもと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this 