INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52474, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "心身が強く、困難に負けないさま。", "primary_collocate": null, "pronunciation": "たくましい", "ipa": "takɯmaɕiː", "syllable_count": 5, "sentences": [{"text": "その姿を凝視する子供の瞳には、生命が持つ根源的な逞しさへの畏敬の念が宿っている。", "target_word": "逞しさ", "complexity_tier": "T6", "furigana": "たくましい", "sentence_source": "mined"}, {"text": "苛烈な寒風が頬を打つ外の世界へと、無垢な好奇心を携えて駆け出していくその背中には、人間が本来備えている、過酷な環境をも楽しみへと変貌させる逞しさが凝縮されていたのである。", "target_word": "逞しさ", "complexity_tier": "T6", "furigana": "たくましい", "sentence_source": "mined"}, {"text": "彼女は逞しい心で、苦しい日々を乗り越えた。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "逞しく生きる彼の姿に、勇気をもらった。", "target_word": "逞しく", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "失敗しても立ち上がる逞しい人だ。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "困難に負けない逞しさを身につけたい。", "target_word": "逞しさ", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "母は逞しく、一人で三人の子を育てた。", "target_word": "逞しく", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "逞しい精神が、チームを救った。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "彼は逞しくて、何があっても笑っている。", "target_word": "逞しく", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "逞しい若者たちが、町を元気にしている。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}], "morphological_forms": [{"form": "逞しく", "label": "活用"}, {"form": "逞しかった", "label": "活用"}, {"form": "逞しくない", "label": "活用"}, {"form": "逞しさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 心が強く困難に負けない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286390ce-0447-431c-b554-5d3f880b0ae5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52473, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "体が丈夫で元気な様子。", "primary_collocate": null, "pronunciation": "たくましい", "ipa": "takɯmaɕiː", "syllable_count": 5, "sentences": [{"text": "彼は腕の逞しい漁師だ。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "逞しい体の男が、重い荷物を運んだ。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "毎日泳いで、体が逞しくなった。", "target_word": "逞しく", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "逞しい馬が、丘を走っていく。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "父は肩が広くて、逞しい人だ。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "逞しい腕で、彼は子どもを持ち上げた。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "弟は野菜をたくさん食べて、逞しく育った。", "target_word": "逞しく", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "逞しい体つきの選手が入場した。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "筋肉のついた逞しい胸を、彼は張った。", "target_word": "逞しい", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}, {"text": "病気が治って、彼はまた逞しくなった。", "target_word": "逞しく", "complexity_tier": "T3", "furigana": "たくましい", "sentence_source": "generated"}], "morphological_forms": [{"form": "逞しく", "label": "活用"}, {"form": "逞しかった", "label": "活用"}, {"form": "逞しくない", "label": "活用"}, {"form": "逞しさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 体が丈夫で元気なさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286390ce-0447-431c-b554-5d3f880b0ae5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52566, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の本質的な部分を小さくまとめて示したもの。または、全体を縮めて表した図や模型。", "primary_collocate": null, "pronunciation": "しゅくず", "ipa": "ɕɯkɯzɯ", "syllable_count": 3, "sentences": [{"text": "裏庭の片隅に設えられた僅かな土塊、すなわち小さな花壇は、幼き子にとって広大な宇宙の縮図であった。", "target_word": "縮図", "complexity_tier": "T6", "furigana": "しゅくず", "sentence_source": "mined"}, {"text": "この製作の全工程は、まさに宇宙の理を机の上に縮図として描き出す、崇高な知的探究なのである。", "target_word": "縮図", "complexity_tier": "T6", "furigana": "しゅくず", "sentence_source": "mined"}, {"text": "この町は日本の社会の縮図だ。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "学校はいわば小さな社会の縮図である。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "満員電車は現代生活の縮図だと思う。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "この小説は、時代の縮図を描いている。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "市場には人間社会の縮図がある。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "家族は社会の縮図だと言われる。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "その村は、国全体の縮図のようだった。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "クラスの様子は、世の中の縮図に見える。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 全体の本質を小さく示したもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286390ce-0447-431c-b554-5d3f880b0ae5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52565, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "小さい（ちいさい）絵（え）のように、大きなものごとの大切（たいせつ）なところだけをうつし出（だ）したもの。", "primary_collocate": null, "pronunciation": "しゅくず", "ipa": "ɕɯkɯzɯ", "syllable_count": 3, "sentences": [{"text": "地図は、広い土地の縮図である。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "先生は黒板に学校の縮図をかいた。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "町の縮図を見て、道を確かめた。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "この模型は、城の縮図としてよくできている。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "縮図を広げて、旅行の計画を立てた。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "一万分の一の縮図で、町の形を示した。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "子どもたちは、教室の縮図を紙に作った。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "縮図を見ると、全体の形がよく分かる。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "縮図と実物をくらべて、違いを探した。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}, {"text": "机の上に、島の縮図が広げてあった。", "target_word": "縮図", "complexity_tier": "T3", "furigana": "しゅくず", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 全体を縮めて表した図や模型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286390ce-0447-431c-b554-5d3f880b0ae5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52404, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "子", "is_correct": true, "explanation": "「子」が聞こえた語と同じである。"}, {"text": "戸", "is_correct": false, "explanation": "「戸」は似ているが別の語である。"}, {"text": "木", "is_correct": false, "explanation": "「木」は似ているが別の語である。"}, {"text": "碁", "is_correct": false, "explanation": "「碁」は似ているが別の語である。"}, {"text": "手", "is_correct": false, "explanation": "「手」は似ているが別の語である。"}], "explanations": {"子": "「子」が聞こえた語と同じである。", "戸": "「戸」は似ているが別の語である。", "木": "「木」は似ているが別の語である。", "碁": "「碁」は似ているが別の語である。", "手": "「手」は似ているが別の語である。"}, "sentence_index": null, "correct_answer": "子"}, "level_3": {"options": [{"text": "子", "is_correct": true, "explanation": "「子」が文の意味に合う。"}, {"text": "机", "is_correct": false, "explanation": "「机」では文の意味が通らない。"}, {"text": "靴", "is_correct": false, "explanation": "「靴」では文の意味が通らない。"}, {"text": "窓", "is_correct": false, "explanation": "「窓」では文の意味が通らない。"}], "explanations": {"子": "「子」が文の意味に合う。", "机": "「机」では文の意味が通らない。", "靴": "「靴」では文の意味が通らない。", "窓": "「窓」では文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭の子に水をやったら、きれいな花が咲いた。", "explanation": "「子」は人であり、植物のように水をやって花が咲くものではない。"}, {"text": "冷蔵庫から子を出して、コップについで飲んだ。", "explanation": "「子」は人であり、飲み物のようにコップにつぐものではない。"}, {"text": "雨が強いので、子をさして出かけた。", "explanation": "「子」は人であり、傘のようにさすものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8dd3ffe-ea12-4eb9-bdf3-34152b24e919') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
