INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52444, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "儀式や場面の空気が静かで重々しく、おごそかな様子。", "primary_collocate": null, "pronunciation": "げんしゅく", "ipa": "ɡeɴɕɯkɯ", "syllable_count": 4, "sentences": [{"text": "我々大人が往々にして見落とす微小な営みを、彼は無心に、そして厳粛に刻み続けているのである。", "target_word": "厳粛に", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "凍てつく空気の中、ボタンを一つひとつ留める仕草には、未知の領域へ挑む戦士のような厳粛ささえ漂っていた。", "target_word": "厳粛さ", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "式は厳粛だった。", "target_word": "厳粛だ", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "厳粛な式が始まります。", "target_word": "厳粛な", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会場は厳粛な空気でした。", "target_word": "厳粛な", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "みんなが厳粛に黙とうしている。", "target_word": "厳粛に", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厳粛で静かな会場だった。", "target_word": "厳粛で", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "式典は厳粛に行われ、誰も私語をしなかった。", "target_word": "厳粛に", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "厳粛さを保つため、会場では携帯電話を切るよう求められた。", "target_word": "厳粛さ", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "追悼式の厳粛な雰囲気に包まれて、参列者はみな深く頭を下げた。", "target_word": "厳粛な", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "厳粛な", "label": "活用"}, {"form": "厳粛に", "label": "活用"}, {"form": "厳粛だ", "label": "活用"}, {"form": "厳粛さ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 式や場の空気がおごそかな様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54d23b8-25f6-4348-806a-5ac3bd5c0318') ON CONFLICT (sense_id, asset_typ