INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52443, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "人の顔つきや態度、声がとても真面目で、重みがある様子。", "primary_collocate": null, "pronunciation": "げんしゅく", "ipa": "ɡeɴɕɯkɯ", "syllable_count": 4, "sentences": [{"text": "父は厳粛な顔だ。", "target_word": "厳粛な", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "彼の声は厳粛だ。", "target_word": "厳粛だ", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "先生は厳粛に話しました。", "target_word": "厳粛に", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "兄は厳粛な表情でした。", "target_word": "厳粛な", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彼は厳粛な顔で名前を呼んだ。", "target_word": "厳粛な", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厳粛に答える姿が印象的だった。", "target_word": "厳粛に", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厳粛さを感じる声だった。", "target_word": "厳粛さ", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厳粛な態度で話せば、相手も真剣に聞いてくれるだろう。", "target_word": "厳粛な", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "社長は厳粛な口調で、会社の厳しい状況を説明した。", "target_word": "厳粛な", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "いつも冗談ばかり言う彼が、あの日だけは厳粛な顔つきで私たちに向き合っていた。", "target_word": "厳粛な", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "厳粛な", "label": "活用"}, {"form": "厳粛に", "label": "活用"}, {"form": "厳粛だ", "label": "活用"}, {"form": "厳粛さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 人の態度や表情が真面目で重い様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54d23b8-25f6-4348-806a-5ac3bd5c0318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36113, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "言葉や絵、音楽などで表したり伝えたりする、心の気持ち。", "primary_collocate": null, "pronunciation": "かんじょう", "ipa": "kaɲdʑoː", "syllable_count": 4, "sentences": [{"text": "クレヨンのざらついた質感と鮮やかな色彩が交わる瞬間、言葉にできない感情が視覚化されていく。", "target_word": "感情", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "この憧れの感情は、やがてグローバルな大衆向けブランドによって巧妙に咀嚼され、誰もが手が届く価格帯へと昇華されるのだ。", "target_word": "感情", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "歌に感情を込める。", "target_word": "感情", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "絵で感情を伝えます。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "感情のこもった歌に拍手が起きた。", "target_word": "感情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "言葉にできない感情は、音楽が語ってくれる。", "target_word": "感情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感情が声に乗ると、せりふは生きた言葉になる。", "target_word": "感情", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "感情を込めて読めば、聞き手にも気持ちが伝わる。", "target_word": "感情", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "手紙には、言葉にならなかった感情が丁寧に書かれていた。", "target_word": "感情", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "作家は登場人物の感情を細かく描くことで、読者の心を強く動かした。", "target_word": "感情", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "感情的", "label": "派生"}, {"form": "感情表現", "label": "派生"}, {"form": "感情移入", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 表現して伝える心の気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: ざらつい (Zipf 1.67)']: