INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36112, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "うれしい、悲しい、怒りなど、心の中に自然にわいてくる気持ちそのもの。", "primary_collocate": null, "pronunciation": "かんじょう", "ipa": "kaɲdʑoː", "syllable_count": 4, "sentences": [{"text": "感情が顔に出る。", "target_word": "感情", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "強い感情がわいた。", "target_word": "感情", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "悲しい感情をおさえました。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "感情は人によって違います。", "target_word": "感情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "うれしい感情が心にあふれてきた。", "target_word": "感情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "怒りの感情を、ぐっとこらえている。", "target_word": "感情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感情をことばにするのは難しいです。", "target_word": "感情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感情を抑えられなくなって、思わず泣いてしまった。", "target_word": "感情", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "驚きや喜びといった感情は、誰にでも自然に起こるものだ。", "target_word": "感情", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "試合に負けた悔しい感情がなかなか消えず、その夜はほとんど眠れなかった。", "target_word": "感情", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "感情的", "label": "派生"}, {"form": "感情表現", "label": "派生"}, {"form": "感情移入", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 心の中にわく喜怒哀楽の気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54d23b8-25f6-4348-806a-5ac3bd5c0318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, p