INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52134, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人や組織が、理想や考えを自分の行動で具体的に示すこと。", "primary_collocate": null, "pronunciation": "たいげん", "ipa": "taiɡeɴ", "syllable_count": 4, "sentences": [{"text": "ロボット工学の深淵を志す者がまず体現すべきは、DIYの精神に根ざした泥臭い試行錯誤のプロセスに他ならない。", "target_word": "体現", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "その姿は、まさに宇宙の摂理そのものを体現しているかのようであった。", "target_word": "体現して", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "彼は夢を体現した。", "target_word": "体現した", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "この選手は努力を体現しています。", "target_word": "体現して", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先生は誠実さを体現しました。", "target_word": "体現しました", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彼女の生き方は自由を体現している。", "target_word": "体現して", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理想を体現する人になりたい。", "target_word": "体現する", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "親切の心を体現できるように、毎日行動を続けている。", "target_word": "体現できる", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "この会社は、挑戦の精神を体現した製品を作り続けている。", "target_word": "体現した", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "彼は言葉ではなく行動によって、チームの信じる価値を体現し続けた。", "target_word": "体現し", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "体現する", "label": "活用"}, {"form": "体現した", "label": "活用"}, {"form": "体現できる", "label": "活用"}, {"form": "体現者", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 理想や考えを行動で具体的に示す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54d23b8-25f6-4348-806a-5ac3bd5c0318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52133, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある性質や考えが、そのままの形になって現れたもの。", "primary_collocate": null, "pronunciation": "たいげん", "ipa": "taiɡeɴ", "syllable_count": 4, "sentences": [{"text": "彼は善の体現だ。", "target_word": "体現", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "この像は平和の体現です。", "target_word": "体現", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "母は愛の体現でした。", "target_word": "体現", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "その町並みは古い文化の体現だ。", "target_word": "体現", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彼女は努力の体現として尊敬されている。", "target_word": "体現", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "誠実さの体現としては、この作品が最も分かりやすい。", "target_word": "体現", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "その選手の動きは、技術の体現そのものだった。", "target_word": "体現", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "この小説は、時代の空気の体現だと言われている。", "target_word": "体現", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "彼こそ、日本の職人気質の体現と呼ぶにふさわしい人だ。", "target_word": "体現", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "王の姿は、国民が信じてきた強さの体現として、長く語り伝えられた。", "target_word": "体現", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "体現する", "label": "活用"}, {"form": "体現した", "label": "活用"}, {"form": "体現者", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 性質がそのまま形になって現れたもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54d23b8-25f6-4348-806a-5ac3bd5c0318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_us