INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35668, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが終わったあと。", "primary_collocate": null, "pronunciation": "あと", "ipa": "ato", "syllable_count": 2, "sentences": [{"text": "食事の後に、歯をみがきます。", "target_word": "後", "complexity_tier": "T2", "furigana": "あと", "sentence_source": "generated"}, {"text": "宿題は後でやります。", "target_word": "後", "complexity_tier": "T2", "furigana": "あと", "sentence_source": "generated"}, {"text": "後から友だちが来るよ。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}, {"text": "お風呂の後は、すぐに寝る。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}, {"text": "授業が終わった後、図書館へ行った。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}, {"text": "雨の後の道はぬれている。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}, {"text": "旅行の後、写真を整理した。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}, {"text": "帰った後で、電話がありました。", "target_word": "後", "complexity_tier": "T2", "furigana": "あと", "sentence_source": "generated"}, {"text": "寝る前でなく、起きた後に勉強する。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}, {"text": "ケーキを食べた後、お茶を飲んだ。", "target_word": "後", "complexity_tier": "T3", "furigana": "あと", "sentence_source": "generated"}], "morphological_forms": [{"form": "後で", "label": "派生"}, {"form": "後から", "label": "派生"}, {"form": "後ほど", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 何かが終わった時点より後", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a32954-d7c9-438d-a77f-6039c0b280e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37595, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自然の現象や物体の動きの法則を研究する学問分野。", "primary_collocate": null, "pronunciation": "ぶつり", "ipa": "bɯtsɯɾi", "syllable_count": 3, "sentences": [{"text": "電子工作により、センサーやアクチュエータといった「感覚器官」と「筋肉」を物理的に実装する。", "target_word": "物理的", "complexity_tier": "T6", "furigana": "ぶつりてき", "sentence_source": "mined"}, {"text": "しかる後に、プログラミングという「神経系」を構築し、抽象的論理と物理的挙動を厳密に同期させるのだ。", "target_word": "物理的", "complexity_tier": "T6", "furigana": "ぶつりてき", "sentence_source": "mined"}, {"text": "彼女の人生におけるこの学校の初日は、単なる物理的な場所の移動を意味するものではない。", "target_word": "物理的", "complexity_tier": "T6", "furigana": "ぶつりてき", "sentence_source": "mined"}, {"text": "彼は大学院で物理を研究している。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "物理の法則は、宇宙のどこでも変わらない。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "量子の世界を扱う物理は、直感に反することが多い。", "target_word": "物理", "complexity_tier": "T4", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "物理の発展が、現代の技術を支えてきた。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "彼女は物理で博士号を取得した。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "物理の知識がなければ、この実験は理解できない。", "target_word": "物理", "complexity_tier": "T4", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "アインシュタインは物理に革命をもたらした。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}], "morphological_forms": [{"form": "物理学", "label": "派生"}, {"form": "物理的", "label": "派生"}, {"form": "物理学者", "label": "派生"}, {"form": "物理法則", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 自然法則を研究する学問", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: アクチュエータ (Zipf 2.3)']::text[], 'f4a32954-d7c9-438d-a77f-6039c0b280e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37594, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物の動きや力について考える学問のことです。", "primary_collocate": null, "pronunciation": "ぶつり", "ipa": "bɯtsɯɾi", "syllable_count": 3, "sentences": [{"text": "物理は、むずかしいです。", "target_word": "物理", "complexity_tier": "T2", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "私は物理が好きです。", "target_word": "物理", "complexity_tier": "T2", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "明日、物理のテストがあります。", "target_word": "物理", "complexity_tier": "T2", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "物理を勉強すると、ボールの動きが分かる。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "兄は高校で物理を教えている。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "物理の宿題が多くて、困っている。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "物理の先生は、実験をよく見せてくれる。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "力と運動を学ぶ物理は、身近な学問だ。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "物理が苦手なので、友達に教えてもらった。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}, {"text": "来年は物理と化学を選ぶつもりだ。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ぶつり", "sentence_source": "generated"}], "morphological_forms": [{"form": "物理学", "label": "派生"}, {"form": "物理的", "label": "派生"}, {"form": "物理室", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 力と運動を学ぶ学校の教科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 