INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52218, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自然の中で生まれ育ち、人間の手で飼育・栽培されていない状態。", "primary_collocate": null, "pronunciation": "やせい", "ipa": "jasei", "syllable_count": 3, "sentences": [{"text": "修業の途上にある若きパン職人は、夜明け前の凛とした空気が張り詰めるアトリエにて、野生の酵母が織りなす微細かつ劇的な化学反応と黙々と格闘していた。", "target_word": "野生", "complexity_tier": "T6", "furigana": "やせい", "sentence_source": "mined"}, {"text": "静謐な工房において、作り手は野生酵母と乳酸菌の共生するサワードウの種起こしから営為を開始する。", "target_word": "野生酵母", "complexity_tier": "T6", "furigana": "やせい", "sentence_source": "mined"}, {"text": "野生の猿が山で暮らしている。", "target_word": "野生の", "complexity_tier": "T2", "furigana": "やせい", "sentence_source": "generated"}, {"text": "野生で育った花は強い。", "target_word": "野生", "complexity_tier": "T2", "furigana": "やせい", "sentence_source": "generated"}, {"text": "森には野生の動物がまだ残っている。", "target_word": "野生の", "complexity_tier": "T2", "furigana": "やせい", "sentence_source": "generated"}, {"text": "野生のキノコを食べるのは危ないので、よく調べてからにしてください。", "target_word": "野生の", "complexity_tier": "T5", "furigana": "やせい", "sentence_source": "generated"}, {"text": "野生の本能を失った犬は、森では生きられない。", "target_word": "野生の", "complexity_tier": "T3", "furigana": "やせい", "sentence_source": "generated"}, {"text": "野生に戻された鳥は、すぐに空へ飛んでいった。", "target_word": "野生に", "complexity_tier": "T3", "furigana": "やせい", "sentence_source": "generated"}, {"text": "野生と飼育の違いを説明してください。", "target_word": "野生", "complexity_tier": "T3", "furigana": "やせい", "sentence_source": "generated"}, {"text": "この魚は野生ではなく、養殖です。", "target_word": "野生", "complexity_tier": "T2", "furigana": "やせい", "sentence_source": "generated"}], "morphological_forms": [{"form": "野生の", "label": "派生"}, {"form": "野生化", "label": "派生"}, {"form": "野生動物", "label": "派生"}, {"form": "野生種", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 飼育されず自然のままの状態", "co