INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39569, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を自然の状態やあるがままにしておくこと。また、思いのままに行うこと。", "primary_collocate": null, "pronunciation": "まま", "ipa": "mama", "syllable_count": 2, "sentences": [{"text": "しかし、抽出された液は未だ不安定な色彩に過ぎず、そのままでは時間と共に退色してしまう。", "target_word": "まま", "complexity_tier": "T6", "furigana": "まま", "sentence_source": "mined"}, {"text": "窓を開けたまま、寝てしまった。", "target_word": "まま", "complexity_tier": "T2", "furigana": "まま", "sentence_source": "generated"}, {"text": "靴をはいたまま、部屋に入らないでください。", "target_word": "まま", "complexity_tier": "T3", "furigana": "まま", "sentence_source": "generated"}, {"text": "何も言わないまま、彼は帰っていった。", "target_word": "まま", "complexity_tier": "T3", "furigana": "まま", "sentence_source": "generated"}, {"text": "昔のままの町並みが、今も残っている。", "target_word": "まま", "complexity_tier": "T3", "furigana": "まま", "sentence_source": "generated"}, {"text": "見たままを話してください。", "target_word": "まま", "complexity_tier": "T2", "furigana": "まま", "sentence_source": "generated"}, {"text": "思いのままに生きるのは、むずかしい。", "target_word": "まま", "complexity_tier": "T3", "furigana": "まま", "sentence_source": "generated"}, {"text": "彼は言われるがままに動いた。", "target_word": "まま", "complexity_tier": "T2", "furigana": "まま", "sentence_source": "generated"}, {"text": "この店は、昔のままです。", "target_word": "まま", "complexity_tier": "T2", "furigana": "まま", "sentence_source": "generated"}, {"text": "立ったまま話すのは、疲れる。", "target_word": "まま", "complexity_tier": "T2", "furigana": "まま", "sentence_source": "generated"}], "morphological_forms": [{"form": "そのまま", "label": "派生"}, {"form": "たまま", "label": "活用"}, {"form": "ままに", "label": "活用"}, {"form": "ままで", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | あるがままの状態・思いのまま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}