INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36529, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "未だ", "is_correct": true, "explanation": "「未だ」が聞こえた語と同じ。"}, {"text": "筏", "is_correct": false, "explanation": "「筏」は見出し語と一音だけ違う別の語。"}, {"text": "今や", "is_correct": false, "explanation": "「今や」は見出し語と一音だけ違う別の語。"}, {"text": "今に", "is_correct": false, "explanation": "「今に」は見出し語と一音だけ違う別の語。"}], "explanations": {"未だ": "「未だ」が聞こえた語と同じ。", "筏": "「筏」は見出し語と一音だけ違う別の語。", "今や": "「今や」は見出し語と一音だけ違う別の語。", "今に": "「今に」は見出し語と一音だけ違う別の語。"}, "sentence_index": null, "correct_answer": "未だ"}, "level_3": {"options": [{"text": "未だ", "is_correct": true, "explanation": "「未だ」が文の意味に合う。"}, {"text": "ぜひ", "is_correct": false, "explanation": "「ぜひ」は形は合うが、意味が合わない。"}, {"text": "わざわざ", "is_correct": false, "explanation": "「わざわざ」は形は合うが、意味が合わない。"}, {"text": "わざと", "is_correct": false, "explanation": "「わざと」は形は合うが、意味が合わない。"}], "explanations": {"未だ": "「未だ」が文の意味に合う。", "ぜひ": "「ぜひ」は形は合うが、意味が合わない。", "わざわざ": "「わざわざ」は形は合うが、意味が合わない。", "わざと": "「わざと」は形は合うが、意味が合わない。"}, "sentence_index": 0, "correct_answer": "未だ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試験は未だ合格したので、みんなで喜んだ。", "explanation": "「未だ」は状態が続くときに使うので、合格が決まった文には合わない。"}, {"text": "彼女は未だ新しい家に引っ越したと報告した。", "explanation": "「未だ」は完了していないことを表すので、「引っ越した」とは合わない。"}, {"text": "未だ、その問題はすっかり解決した。", "explanation": "「未だ」は今も続く状態を表すので、「すっかり解決した」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68d810d-6531-4761-a40b-78e26fe52fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
