INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52923, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "宿す", "is_correct": true, "explanation": "「宿す」が聞こえた語と同じ。"}, {"text": "戻す", "is_correct": false, "explanation": "「戻す」は見出し語と一音だけ違う別の語。"}, {"text": "窶す", "is_correct": false, "explanation": "「窶す」は見出し語と一音だけ違う別の語。"}, {"text": "宿る", "is_correct": false, "explanation": "「宿る」は見出し語と一音だけ違う別の語。"}], "explanations": {"宿す": "「宿す」が聞こえた語と同じ。", "戻す": "「戻す」は見出し語と一音だけ違う別の語。", "窶す": "「窶す」は見出し語と一音だけ違う別の語。", "宿る": "「宿る」は見出し語と一音だけ違う別の語。"}, "sentence_index": null, "correct_answer": "宿す"}, "level_3": {"options": [{"text": "宿して", "is_correct": true, "explanation": "「宿して」が文の意味に合う。"}, {"text": "壊して", "is_correct": false, "explanation": "「壊して」は形は合うが、意味が合わない。"}, {"text": "割って", "is_correct": false, "explanation": "「割って」は形は合うが、意味が合わない。"}, {"text": "拭いて", "is_correct": false, "explanation": "「拭いて」は形は合うが、意味が合わない。"}], "explanations": {"宿して": "「宿して」が文の意味に合う。", "壊して": "「壊して」は形は合うが、意味が合わない。", "割って": "「割って」は形は合うが、意味が合わない。", "拭いて": "「拭いて」は形は合うが、意味が合わない。"}, "sentence_index": 6, "correct_answer": "宿して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は大きな荷物を肩に宿して、坂を登った。", "explanation": "「宿す」は物を担ぐ意味ではないので、荷物の目的語に使えない。"}, {"text": "私は友だちを電話に宿した。", "explanation": "「宿す」は人を電話で呼ぶ意味ではないので、使えない。"}, {"text": "犬が公園でボールを宿して遊んでいる。", "explanation": "「宿す」はくわえる意味ではないので、ボールの目的語に使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68d810d-6531-4761-a40b-78e26fe52fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
